(window.GIM_TS=window.GIM_TS||{})["Shabbat.1"]={"from":24,"a":[["\u0003לא מטמו\u0004 \u0005[אינו מטמא]\u0006 אותה, כלומר, אינו גורם לה שתטמא אף דברים אחרים? \u0003אמר רבה בר בר חנה:\u0004 דעה זו, דעת \u0003ר' יהושע היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003ר' אליעזר אומר: האוכל אוכל\u0004 שהוא \u0003ראשון\u0004 לטומאה — נעשה הוא עצמו \u0003ראשון\u0004 לטומאה והראשון מטמא את התרומה. \u0003ו\u0004ה\u0003אוכל אוכל\u0004 שהוא \u0003שני\u0004 לטומאה — נעשה הוא עצמו \u0003שני\u0004 לטומאה; והאוכל \u0003אוכל שלישי\u0004 לטומאה — נעשה הוא \u0003שלישי\u0004 לטומאה. \u0003ר' יהושע אומר: האוכל אוכל ראשון ו\u0004כן האוכל \u0003אוכל שני\u0004 — נעשה הוא עצמו \u0003שני\u0004 לטומאה בלבד, והשני לטומאה אם נגע בתרומה — פוסל אותה ואינו מטמאה. והאוכל אוכל \u0003שלישי\u0004 — נעשה \u0003שני\u0004 לטומאה, ואולם טומאתו זו חלה רק \u0003ל\u0004גבי ה\u0003קודש, ואין\u0004 הוא נעשה \u0003שני ל\u0004טמא \u0003תרומה.\u0004 ודרגת שלישי זו אינה אלא בחולין, שאין אוכלים תרומה טמאה. ותיתכן רק בחולין \u0003שנעשו על\u0004 (באופן) שיהיו טהורים באותה דרגה של \u0003טהרת תרומה.\u0004","על עצם גזירת חכמים שואלים: ה\u0003אוכל אוכל\u0004 שהוא \u0003ראשון\u0004 לטומאה \u0003ו\u0004ה\u0003אוכל אוכל\u0004 שהוא \u0003שני\u0004 לטומאה, \u0003מאי טעמא גזרו ביה רבנן\u0004 \u0005[מה טעם גזרו בו חכמים ]\u0006 \u0003טומאה,\u0004 כלומר, שיהא האוכלם טמא? ומשיבים: משום \u0003דזימנין דאכיל\u0004 \u0005[שלפעמים שאוכל]\u0006 \u0003אוכלין טמאין, ושקיל\u0004 \u0005[ולוקח]\u0006 \u0003משקין\u0004 של \u0003תרומה, ושדי לפומיה ופסיל להו\u0004 \u0005[ומשליך,\u0006 מניח אותם \u0005בפיו ופוסל אותם],\u0006 את האוכלים הללו, שכן המאכל הטמא נוגע בתוך פיו במשקה ופוסל אותו. וכדי שלא יקרה כן גזרו שהאוכל מאכל טמא יהא הוא עצמו טמא, ולא יגע בתרומה כלל.","וכמו כן שואלים: ה\u0003שותה משקין טמאין מאי טעמא גזרו ביה רבנן\u0004 \u0005[מה טעם גזרו בו חכמים ]\u0006 \u0003טומאה?\u0004 ומשיבים: משום \u0003דזימנין דשתה\u0004 \u0005[שלפעמים\u0006 \u0005ששותה]\u0006 \u0003משקין טמאין, ושקל\u0004 \u0005[ולוקח]\u0006 \u0003אוכלין\u0004 של \u0003תרומה ושדי לפומיה ופסיל להו\u0004 \u0005[ומשליך,\u0006 מניח, \u0005בפיו ופוסל אותם],\u0006 את האוכלים הללו. ושואלים: \u0003היינו הך\u0004 \u0005[זהו זה]!\u0006 הרי שני הדברים הינם גזירה אחת וטעם אחד, ומדוע הפרידו ביניהן להחשיבן כשתי גזירות נפרדות? ומשיבים: \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 שאדם אוכל אוכלים טמאים — \u0003שכיחי\u0004 \u0005[מצוי],\u0006 כי האוכל רגיל להוסיף ולשתות מדי פעם, והאוכל מאכל טמא עשוי לשתות משקה של תרומה. \u0003והא\u0004 \u0005[ו\u0006אולם \u0005זה]\u0006 שאדם שותה \u0003משקים טמאים הרי זה לא שכיחי\u0004 \u0005[מצוי]\u0006 שיכניס השותה בתוך כדי שתיה דבר מאכל לפיו, ואפשר היה לומר שבדבר שאינו שכיח לא גזרו חכמים, על כן הודגש שאף במקרה זה גזרו חכמים טומאה.","בין השמונה עשר דבר שגזרו בו ביום שנינו גם על \u0003הבא ראשו ורובו במים שאובין\u0004 שנטמא מדבריהם. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 \u0003טומאה? אמר רב ביבי אמר רב אסי:\u0004 טעמו של דבר הוא, שמשום \u0003שבתחלה,\u0004 בימים הראשונים, \u0003היו טובלין\u0004 להטהר \u0003במי מערות מכונסין וסרוחין.\u0004 ואף שמים אלה מטהרים מטומאה, \u0003ו\u0004אולם מחמת הסירחון \u0003היו נותנין עליהם\u0004 הטובלים \u0003מים שאובין\u0004 כדי להתנקות. \u0003ו\u0004מכיון שכבר \u0003התחילו\u0004 במנהג זה \u0003ועשאום קבע,\u0004 לכך \u0003גזרו\u0004 חכמים \u0003טומאה\u0004 על המים השאובים שלא ירחצו בהם בשעת טהרה.","ושאלו: \u0003מאי\u0004 \u0005[מה]\u0006 משמעות הדבר שהיו עושים אותם \u0003קבע?\u0004 — \u0003אמר אביי, שהיו אומרים: לא אלו,\u0004 מי המערה, \u0003מטהרין, אלא אלו ואלו,\u0004 מי המערה והמים השאובים יחד, הם ה\u0003מטהרין. אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: מאי נפקא מינה, הא קא טבלי בהנך\u0004 \u0005[מה יוצא מזה,\u0006 מה רע בכך, ו\u0005הרי הם טובלים באלה],\u0006 ומה בכך אם מישהו מחזיק בסברה שאינה נכונה? הרי סוף סוף הוא טובל כראוי! \u0003אלא אמר רבא:\u0004 הבעיה היתה שהגיעו לידי כך \u0003שהיו אומרים: לא אלו,\u0004 מי המערה, \u0003מטהרין, אלא אלו,\u0004 המים השאובים, \u0003מטהרין.\u0004 ולכן גזרו חכמים שלא ישתמשו במים השאובים לטהרה כלל.","גזירה אחרת היתה ש\u0003טהור שנפלו על ראשו ורובו שלשה לוגין מים שאובין,\u0004 שהוא טמא. ומבארים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 \u0003טומאה?\u0004 — \u0003דאי\u0004 \u0005[שאם]\u0006 \u0003לא\u0004 גזירה \u0003הא\u0004 \u0005[זו]\u0006 שגזרו טומאה גם על טהור גמור שאינו זקוק לטבילה, שנפלו עליו מים שאובים, \u0003לא קיימא הא\u0004 \u0005[היתה עומדת זו],\u0006 שלא היתה הגזירה הראשונה יכולה להתקיים, כי לא היו מבחינים בין טהור גמור לעולה מן הטבילה.","ועוד מבארים: \u0003וספר\u0004 תורה \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 \u0003טומאה?\u0004 — \u0003אמר רב משרשיא:\u0004 לפי \u0003שבתחלה היו\u0004 כהנים עמי הארץ \u0003מצניעים\u0004 דברי \u0003אוכל\u0004 של \u0003תרומה אצל ספר\u0004 ה\u0003תורה, ואמרו: האי\u0004 \u0005[זה]\u0006 \u0003קדש והאי\u0004 \u0005[וזה]\u0006 \u0003קדש,\u0004 וראוי להם שיימצאו יחד. \u0003כיוון דקחזו דקאתו לידי פסידא\u0004 \u0005[שראו\u0006 חכמים \u0005שהם באים לידי הפסד,\u0006 קלקול\u0005],\u0006 שהעכברים היו נמשכים אחר מאכלי התרומה והיו מכרסמים גם את ספרי התורה, לכך \u0003גזרו ביה רבנן\u0004 \u0005[בו חכמים]\u0006 \u0003טומאה.\u0004 ומשגזרו טומאה על ספר התורה, לא הניחו עוד מאכלים לידו.","ומבארים עוד: \u0003והידים\u0004 ששנינו שאף בהן גזרו טומאה, טעם הדבר הוא \u0003מפני שהידים עסקניות הן,\u0004 שידיו של אדם נוגעות בחפצים מלוכלכים או טמאים ואין אדם שם לב במה נגע בידיו, וגנאי למאכל קודש שיגעו בו ידיים מלוכלכות. \u0003תנן\u0004 \u0005[שנויה\u0006 משנה\u0005]:\u0006 \u0003אף ידים הבאות מחמת ספר,\u0004 כלומר, ידיים שנגעו בספר תורה, אף הן נחשבות טמאות ו\u0003פוסלות את התרומה.\u0004 וטעמה של גזירה זו \u0003משום\u0004 דברי \u0003ר' פרנך.\u0004 ש\u0003אמר ר' פרנך אמר ר' יוחנן: האוחז ספר תורה\u0004 באופן שהספר \u0003ערום\u0004 בלא כיסוי, עונשו שהוא עצמו \u0003נקבר ערום.\u0004 על כך תמהים: וכי שייקבר \u0003ערום\u0004 ממש \u0003סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? ומדוע ייענש בבזיון גדול כל כך עבור חטא זה? \u0003אלא אמר ר' זירא:\u0004 הכוונה היא שייקבר \u0003ערום בלי מצות.\u0004 ותוהים עוד: וכי שייקבר \u0003ערום בלי מצו‍ת סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? וכי בגלל עבירה כעין זו יילקחו ממנו כל זכויותיו? \u0003אלא אימא\u0004 \u0005[אמור]:\u0006 \u0003ערום בלא אותה מצוה.\u0004 שאם נגע בספר התורה בלא כיסוי אף לשם מצוה — אין אותה מצוה נחשבת לו, מאחר שלא עשה אותה כראוי.","ודרך אגב שואלים: \u0003הי גזור ברישא\u0004 \u0005[איזו,\u0006 מגזירות אלה, \u0005גזרו בתחילה]?\u0006 \u0003אילימא הא גזור ברישא\u0004 \u0005[אם תאמר\u0006 כי את \u0005זו,\u0006 טומאת ידיים בכלל \u0005גזרו בתחילה],\u0006"],["\u0003כיון דהך גזור ברישא, הא תו\u0004 \u0005[ש\u0006את \u0005זו גזרו בתחילה, אלה עוד]\u0006 \u0003למה לי?\u0004 שאם גזרו טומאה על סתם ידיים, שוב אין צורך עוד לגזור טומאה על ידיים שנגעו בספר תורה, שהרי בכל מקרה הן טמאות! \u0003אלא\u0004 ודאי על \u0003הך גזור ברישא\u0004 \u0005[זו גזרו בתחילה],\u0006 \u0003והדר גזור בכולהו\u0004 \u0005[וחזרו\u0006 אחר כך ו\u0005גזרו על כל]\u0006 ה\u0003ידים.\u0004","בין הגזירות שנמנו נמצאת גם ההלכה ש\u0003טבול יום\u0004 פוסל את התרומה. ותמהים: והרי \u0003טבול יום דאורייתא\u0004 \u0005[מן התורה]\u0006 \u0003הוא\u0004 מטמא, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \"נפש אשר תגע בו וטמאה עד הערב ולא יאכל מן הקדשים כי אם רחץ בשרו במים. \u0003ובא השמש וטהר\u0004 ואחר יאכל מן הקדשים כי לחמו הוא\" (ויקרא כב, ו–ז), הרי שעד שעת השקיעה אסור הוא לנגוע בקדשים, והוא הדין לתרומה! ומשיבים: \u0003סמי\u0004 \u0005[מחק]\u0006 \u0003מכאן,\u0004 מרשימת הגזירות, את \u0003טבול יום.\u0004","בין הגזירות שנמנו הוזכרה גם טומאת \u0003האוכלין שנטמאו במשקין.\u0004 ושואלים: \u0003במשקין דמאי\u0004 \u0005[של מה],\u0006 שנטמאו ממה? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי מדובר \u0003במשקין הבאין\u0004 (שטומאתם באה) \u0003מחמת\u0004 מגע ב\u0003שרץ\u0004 — והלא אלה \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הם]\u0006 טמאים, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 בטומאת השרצים: \u0003\"וכל משקה אשר ישתה\u0004 בכל כלי יטמא\u0003\"\u0004 (ויקרא יא, לד)! \u0003אלא\u0004 מדובר \u0003במשקין\u0004 הבאין, שטומאתם באה, \u0003מחמת ידים\u0004 טמאות, שהם מדברי סופרים, \u0003ו\u0004טומאה זו \u0003גזירה\u0004 היא שגזרו בהם \u0003משום משקין הבאין מחמת שרץ.\u0004","בין הגזירות שנמנו, נמנתה הגזירה של \u0003הכלים שנטמאו במשקין.\u0004 ושואלים: \u0003כלים דאיטמאו\u0004 \u0005[שנטמאו]\u0006 \u0003במשקין דמאי\u0004 \u0005[של מה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 כי נטמאו \u0003במשקין\u0004 של \u0003זב,\u0004 כלומר, אחת מן ההפרשות הנוזליות הבאות מן הזב (רוק, מי רגלים וכו') — והלא \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הם]\u0006 טמאים! \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וכי ירק הזב בטהור\u0004 וכבס בגדיו ורחץ במים וטמא עד הערב\u0003\"\u0004 (ויקרא טו, ח). ודרשו: \u0003מה שביד טהור טמאתי לך.\u0004 שלא רק האדם שנגעו בו נוזלי הזב נטמא, אלא גם חפצים המצויים בידו! \u0003אלא\u0004 כאן \u0003במשקין הבאין,\u0004 שנטמאו \u0003מחמת שרץ,\u0004 שלפי דין התורה אין הם מטמאים כלים, \u0003וגזירה\u0004 היא שגזרו חכמים \u0003משום\u0004 דמיונם ל\u0003משקין\u0004 של ה\u0003זב.\u0004","בין הדברים שנמנו במשנה כאלה שגזרו עליהם תלמידי שמאי והלל, היו גם הידים של כל אדם שלא נטהר לשם טהרת תרומה, ונגע בה שטמאוה. ושואלים: \u0003ו\u0004על ה\u0003ידים\u0004 האם \u0003תלמידי שמאי והלל גזור\u0004 \u0005[גזרו]\u0006 עליהם טומאה? הלא גזירה זו \u0003שמאי והלל\u0004 עצמם \u0003גזור\u0004 \u0005[גזרו]\u0006 עליהם. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים גזרו טומאה על ארץ העמים,\u0004 שאדמת חוץ לארץ מטמאה, \u0003ו\u0004כן גזרו טומאה \u0003על כלי זכוכית\u0004 אף שאינם כלולים בתורה בין הדברים המקבלים טומאה. \u0003שמעון בן שטח תיקן\u0004 את סגנון ה\u0003כתובה לאשה, ו\u0004כן \u0003גזר טומאה\u0004 מיוחדת \u0003על כלי מתכות. שמאי והלל גזרו טומאה על הידים!\u0004","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שהכוונה בברייתא זו הינה \u0003שמאי וסיעתו והלל וסיעתו, והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב יהודה אמר שמואל:\u0004 על \u0003שמנה עשר דבר גזרו\u0004 בו ביום, \u0003ובשמנה עשר\u0004 דבר \u0003נחלקו\u0004 קודם, ושמונה עשרה מחלוקות היו רק בין תלמידי הלל ושמאי, \u0003ואילו הלל ושמאי\u0004 עצמם \u0003לא נחלקו אלא בשלשה מקומות.\u0004 ש\u0003אמר רב הונא: בשלשה מקומות נחלקו\u0004 שמאי והלל \u0003ותו לא\u0004 \u0005[ולא עוד].\u0006 \u0003וכי תימא\u0004 \u0005[ואם\u0006 \u0003תאמר]\u0004 כי \u0003אתו אינהו גזור\u0004 \u0005[באו הם,\u0006 הלל ושמאי, ו\u0005גזרו]\u0006 על הידיים \u0003לתלות,\u0004 שהדברים שנטמאו בידיים יהיו טמאים, אבל לא לענין שיצטרכו לשרוף אותם כאלה שנטמאו בטומאה ודאית, אלא להשאירם תלויים ועומדים עד שייטמאו או יתקלקלו מעצמם. \u0003ואתו תלמידייהו\u0004 \u0005[ובאו תלמידיהם]\u0006 \u0003וגזרו לשרוף. והאמר\u0004 \u0005[והרי אמר]\u0006 החכם \u0003אילפא: ידים תחלת גזירתן\u0004 היתה \u0003לשריפה\u0004 בלא פקפוק! \u0003אלא\u0004 יש להסביר כי \u0003אתו אינהו גזור\u0004 \u0005[באו הם\u0006 ו\u0005גזרו]\u0006 \u0003ולא קבלו מינייהו\u0004 \u0005[מהם]\u0006 העם גזירה זו, \u0003ואתו תלמידייהו\u0004 \u0005[ובאו תלמידיהם]\u0006 ו\u0003גזרו וקבלו מינייהו\u0004 \u0005[מהם].\u0006","ועוד שואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 לא ברור הדבר, שהרי גזירת ידיים \u0003שלמה\u0004 המלך \u0003גזר!\u0004 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: בשעה שתיקן שלמה\u0004 תקנת ה\u0003עירובין ו\u0004תקנת \u0003נטילת ידים\u0004 לטהר את הידיים מטומאתן, \u0003יצתה בת קול ואמרה\u0004 בשבחו: \u0003\"בני אם חכם לבך ישמח לבי גם אני\"\u0004 (משלי כג, טו), וכן: \u0003\"חכם בני ושמח לבי ואשיבה חרפי דבר\"\u0004 (משלי כז, יא)! ומתרצים: \u0003אתא\u0004 \u0005[בא]\u0006"],["\u0003שלמה גזר\u0004 טומאת ידים \u0003ל\u0004גבי ה\u0003קדשים, ואתו אינהו וגזור\u0004 \u0005[ובאו הם וגזרו]\u0006 עליהן \u0003אף ל\u0004גבי \u0003תרומה.\u0004","\u0003גופא\u0004 \u0005[לגוף]\u0006 הדברים שהוזכרו קודם בדרך אגב, מביאים את מה ש\u0003אמר רב יהודה אמר שמואל: שמנה עשר דבר גזרו\u0004 בו ביום \u0003ובשמנה עשר\u0004 דבר \u0003נחלקו\u0004 קודם. ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003הושוו,\u0004 כלומר, שבשמונה עשר דבר, הסכימו! ומתרצים: \u0003בו ביום נחלקו, ולמחר,\u0004 לאחר שכבר נתגלתה ההכרעה במנין \u0003הושוו\u0004 והסכימו שני הצדדים.","\u0003גופא\u0004 \u0005[לגוף]\u0006 הדברים שהוזכרו קודם דנים עוד במה שהוזכר ש\u0003אמר רב הונא\u0004 שרק \u0003בשלשה מקומות נחלקו שמאי והלל\u0004. ומביאים את פרטי המחלוקות. האחת, \u0003שמאי אומר: מקב\u0004 בצק יש להפריש \u0003חלה,\u0004 ובפחות מזה אין חובת הפרשה כי אין זה ככמות \"ראשית עריסותיכם\" (במדבר טו, כ). \u0003והלל אומר: מקביים. ו\u0004אילו \u0003חכמים אומרים: לא כדברי זה ולא כדברי זה, אלא קב ומחצה\u0004 הוא ה\u0003חייב בחלה.\u0004 ו\u0003משהגדילו המדות\u0004 וקבעו לקב נפח גדול יותר, \u0003אמרו\u0004 כי לפי מידת הקב החדשה \u0003חמשת רבעים\u0004 של קב \u0003קמח\u0004 הם ה\u0003חייבים בחלה. ר' יוסי אומר: חמשה\u0004 רבעים עצמם עדיין \u0003פטורין,\u0004 ורק \u0003חמשה ועוד\u0004 משהו \u0003חייבין.\u0004","\u0003ואידך\u0004 \u0005[\u0006ומחלוקת \u0005אחרת]\u0006 שהיתה בין הלל ושמאי, ש\u0003הלל אומר: מלא הין\u0004 (שנים עשר לוג) \u0003מים שאובים\u0004 שנשפכו לתוך מקווה שעדיין לא הושלם בתוכו שיעורו המלא שהוא ארבעים סאה מים, המים השאובים הללו \u0003פוסלים את\u0004 מי \u0003המקוה\u0004 הנמצאים, ועושים אף אותם כשאובים. ואף אם ישלימו אחר כך את שיעור המקווה במים כשרים יהא פסול לטבילה. והלל השתמש בלשון \"הין\" (שהוא לשון תורה), ולא \"סאה\" (שהוא לשון משנה), משום \u0003שחייב אדם לומר בלשון רבו\u0004 , וכך שמעה מפי רבותיו שמעיה ואבטליון. \u0003שמאי אומר:\u0004 רק \u0003תשעה קבין\u0004 מים פוסלים. \u0003וחכמים אומרים: לא כדברי זה ולא כדברי זה,\u0004 אלא שלא קבעו שיעור לדבר. \u0003עד שבאו שני גרדיים\u0004 (אורגים) \u0003משער האשפה שבירושלים והעידו משום\u0004 (בשם) \u0003שמעיה ואבטליון ששלשה לוגין מים שאובין פוסלים את המקוה, וקיימו חכמים את דבריהם\u0004 כנגד דברי חכמי ישראל הגדולים הלל ושמאי. והדגישו את מקצועם ומקומם לומר שעל אף מקצועם שהיה נחשב כבזוי, ומקומם שהיה מקום שאינו מכובד, מכל מקום אין משוא פנים בתורה.","\u0003ואידך\u0004 \u0005[\u0006ומחלוקת \u0005אחרת]\u0006 שהיתה בין הלל ושמאי, ש\u0003שמאי אומר: כל הנשים דיין שעתן.\u0004 כלומר, אשה המגלה שראתה דם נידה ולא הרגישה מתחילה בדבר, אינה צריכה לחשוש שמא התחילה שפיעת הדם מוקדם יותר לרגע שנוכחה בדבר, ודיה להיות טמאה משעה זו. \u0003ו\u0004אילו \u0003הלל אומר: מפקידה לפקידה\u0004 (מבדיקה לבדיקה), שאשה שראתה דם, אם אינה יודעת מתי התחילה שפיעת הדם הריהי נחשבת טמאה למפרע בכל הזמן שעבר משעת הבדיקה האחרונה שבדקה את עצמה ומצאה שהיא טהורה, \u0003אפילו\u0004 היתה בדיקה זו \u0003לימים הרבה\u0004 (לפני זמן רב). וכל דבר שנגעה בו במשך הזמן נחשב לטמא. ו\u0003חכמים אומרים: לא כדברי זה ולא כדברי זה, אלא\u0004 כללו של דבר: \u0003מעת לעת ממעט על יד מפקידה לפקידה,\u0004 כלומר, אם בדקה אשה את עצמה לפני זמן רב, אינה צריכה לחשוש אלא ליממה (מעת לעת) האחרונה, לפני ראיית הדם. \u0003ו\u0004אילו \u0003מפקידה לפקידה ממעט על יד מעת לעת,\u0004 שאם בדקה עצמה בתוך היממה הרי קודם לשעת הבדיקה ודאי שהיא טהורה.","ושואלים: \u0003ותו ליכא\u0004 \u0005[ויותר\u0006 מחלוקות \u0005אין]?\u0006 \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 מה ששנינו ש\u0003הלל אומר\u0004 שמותר \u0003לסמוך\u0004 ידים על ראשי הקרבנות שמקריבים ביום טוב, ואין בכך משום מלאכה וחילולו של יום טוב, \u0003ושמאי אומר שלא לסמוך.\u0004 ומשיבים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב הונא\u0004 את דבריו, הרי זה \u0003היכא דליכא פלוגתא דרבוותא בהדייהו\u0004 \u0005[שאין מחלוקת\u0006 החכמים \u0005הגדולים\u0006 שלפניהם \u0005עמם],\u0006 אבל המחלוקת בדבר הסמיכה ביום טוב עתיקה היא, ונחלקו בה כבר חכמי הזוגות מראשיתם.","ועוד שואלים: \u0003והאיכא\u0004 \u0005[והרי יש]\u0006 עוד את הענין \u0003הבוצר\u0004 ענבים על מנת לדורכם \u0003לגת,\u0004 שנחלקו אם הנוזל היוצא מן הענבים נחשב כיוצא מרצון, ומשום כך מכשיר אותם לקבל טומאה. ש\u0003שמאי אומר: הוכשר, והלל אומר: לא הוכשר.\u0004 ודוחים ואומרים: \u0003בר מיניה דההיא, דהתם קא שתיק ליה\u0004 \u0005[חוץ מההיא, ששם שתק לו]\u0006 \u0003הלל לשמאי\u0004 וקיבל בסוף את דעתו.","קודם הוזכר ש\u0003יוסי בן יועזר איש צרידה ויוסי בן יוחנן איש ירושלים גזרו טומאה על ארץ העמים ועל כלי זכוכית.\u0004 ושואלים: וכי גזירות אלה גזרו שני חכמים אלה שהיו חכמי הזוגות הראשונים? \u0003והא רבנן\u0004 \u0005[והרי החכמים]\u0006 שהיו ב\u0003שמנים שנה\u0004 האחרונות של הבית השני \u0003גזור\u0004 \u0005[גזרו]\u0006 זאת! שכן \u0003אמר רב כהנא: כשחלה ר' ישמעאל בר' יוסי שלחו לו\u0004 חכמים: \u0003רבי, אמור לנו\u0004 שוב \u0003שנים ושלשה דברים שאמרת\u0004 לנו פעם \u0003משום\u0004 (בשם) \u0003אביך.\u0004","\u0003שלח להם, כך אמר אבא: מאה ושמנים שנה עד שלא חרב הבית,\u0004 כלומר, לפני שחרב הבית, \u0003פשטה מלכות הרשעה\u0004 (רומי) \u0003על ישראל. שמנים שנה עד שלא חרב הבית גזרו טומאה על ארץ העמים ועל כלי זכוכית.\u0004 וב\u0003ארבעים שנה עד שלא חרב הבית גלתה לה\u0004 ה\u0003סנהדרין\u0004 מלשכת הגזית \u0003וישבה לה בחנויות.\u0004 על הדברים האחרונים שואלים: \u0003למאי הילכתא\u0004 \u0005[למה ההלכה]?\u0006 מה המשמעות ההלכתית של מעשה זה? \u0003אמר ר' יצחק בר אבדימי: לומר שלא דנו\u0004 עוד \u0003דיני קנסות.\u0004 ותוהים: שהפסיקו לדון \u0003דיני קנסות סלקא דעתך\u0004 \u0005[עולה על דעתך]\u0006 לומר? והרי אף דורות רבים לאחר החורבן עוד המשיכו לדון דיני קנסות בארץ ישראל! \u0003אלא אימא\u0004 \u0005[\u0006תקן ו\u0005אמור]:\u0006 \u0003שלא דנו\u0004 עוד \u0003דיני נפשות,\u0004 שכן ניטלה מן הסנהדרין האפשרות לדון למוות, ולכן יצאו מרצון מלשכת הגזית. שעל פי ההלכה, כיון שאין הסנהדרין יושבת במקומה, שוב לה אין סמכות לדון דיני נפשות (תוס'). ואם כן למדנו שחכמי שמונים השנים האחרונות לפני החורבן הם שגזרו טומאה על ארץ העמים!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי \u0003ב\u0004אותם \u0003שמנים שנה נמי אינהו הוו\u0004 \u0005[גם כן הם,\u0006 יוסי בן יועזר ויוסי בן יוחנן, \u0005היו],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 כי \u0003הלל ושמעון\u0004 בנו, ונכדו \u0003גמליאל, ו\u0004בנו \u0003שמעון נהגו נשיאותן לפני הבית\u0004 (בעוד בית המקדש קיים) \u0003מאה שנה. ואילו יוסי בן יועזר איש צרידה ויוסי בן יוחנן הוו קדמי טובא\u0004 \u0005[היו קדומים הרבה]\u0006 לפני הלל!"],["\u0003אלא\u0004 יש לומר שגזירה זו נעשתה בשלבים שונים, ראשית \u0003אתו אינהו\u0004 \u0005[באו הם]\u0006 יוסי בן יועזר ויוסי בן יוחנן ו\u0003גזור אגושא\u0004 \u0005[וגזרו על גוש\u0006 עפר\u0005]\u0006 של ארץ העמים שתרומה הנוגעת בו יש \u0003לשרוף\u0004 אותה, \u0003ואאוירא\u0004 \u0005[ועל אויר]\u0006 ארץ העמים לא גזרו \u0003ולא כלום. ואתו רבנן\u0004 \u0005[ובאו החכמים]\u0006 שהיו ב\u0003שמנים\u0004 ה\u0003שנה\u0004 האחרונים עד לחורבן הבית \u0003גזור אאוירא\u0004 \u0005[גזרו על האויר]\u0006 שתרומה שנכנסה לארץ העמים יש \u0003לתלות\u0004 את דינה ולא לשורפה.","ושואלים: \u0003למימרא דחדא גזירתא הוה\u0004 \u0005[האם לומר,\u0006 מכאן, \u0005שגזירה אחת\u0006 מיד \u0005היתה]\u0006 לדון את התרומה בדין החמור של \u0003שריפה? והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003אילפא\u0004 כי \u0003ידים תחלת גזירתן לשריפה!\u0004 ומכאן אפשר להסיק בדרך הדיוק \u0003כי ידים\u0004 בלבד \u0003הוא\u0004 שמ \u0003תחלת גזירתן\u0004 כבר גזרו עליהן שיטמאו טומאה גמורה עד \u0003לשריפה\u0004 של תרומה הנוגעת בהן, \u0003הא מידי אחרינא\u0004 \u0005[הרי דבר אחר]\u0006 — \u0003לא\u0004 גזרו בו מיד בחומרה יתירה זו.","\u0003אלא\u0004 כך יש לתאר את שלבי הגזירה: \u0003אתו אינהו גזור אגושא לתלות\u0004 \u0005[באו הם,\u0006 יוסי בן יועזר ויוסי בן יוחנן ו\u0005גזרו\u0006 על הדבר שנגע \u0005בגוש]\u0006 העפר \u0003לתלות, ואאוירא\u0004 \u0005[ועל האויר]\u0006 לא גזרו \u0003ולא כלום. ואתו רבנן\u0004 \u0005[ובאו חכמים]\u0006 של \u0003שמנים\u0004 ה\u0003שנה\u0004 האחרונות והחמירו דרגה אחת, ש\u0003גזור אגושא\u0004 \u0005[גזרו על\u0006 תרומה הנוגעת \u0005בגוש\u0006 עפר\u0005]\u0006 ארץ העמים שיש \u0003לשרוף\u0004 אותו, \u0003ואאוירא\u0004 \u0005[ועל האויר]\u0006 שהנכנס לאויר ארץ העמים שיש \u0003לתלות\u0004 את דינו.","ועוד שואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 האם ברור הדבר? והרי גזירה זו \u0003באושא,\u0004 שנים רבות לאחר החורבן, \u0003גזור\u0004 \u0005[גזרו\u0006 חכמים\u0005]!\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003על ששה ספקות\u0004 של טומאה \u0003שורפין את התרומה\u0004 שנגעה בהם: \u0003על ספק בית הפרס,\u0004 כלומר, תרומה שנכנסה למקום שנחרש בו קבר ואין ידוע היכן מצויות עצמות המת, וספק אם נטמאה התרומה. \u0003ו\u0004כן \u0003על ספק עפר הבא מארץ העמים,\u0004 שכל טומאתו הנה בבחינת ספק טומאה, ונגעה בו תרומה, וספק אם כן אם נטמאה. \u0003ו\u0004כן \u0003על ספק בגדי עם הארץ,\u0004 שמאחר שאינו נזהר לאכול בטהרה חוששים אנו שמא נגעה בבגדיו אשה נדה, ומחשיבים אותם כטמאים טומאה חמורה, ונגעה בהם תרומה, וספק הוא אם כן אם נטמאה. \u0003ו\u0004כן \u0003על ספק כלים הנמצאין,\u0004 שאינם שלו ומצאם, ומאחר שכן אינו יודע אם טמאים הם, ואם נגעה בהם תרומה הרי זה ספק אם נטמאה. \u0003ו\u0004כן \u0003על ספק הרוקין,\u0004 שמא רוק זה מרוקו של זב הוא ומטמא מן התורה. ואם נגעה בו תרומה, הריהי ספק טמאה. \u0003וספק מי רגלי אדם\u0004 אף על פי שהיו \u0003כנגד מי רגלי בהמה,\u0004 שאנו חוששים שמא הם של זב, וטמאים מן התורה, ואם נגעה בו תרומה, ספק הוא אם נטמאה. ובכל אלה קבעו חכמים כי \u0003על ודאי מגען,\u0004 כאשר ברור שנגעו דברים אלה בתרומה, \u0003ועל\u0004 אף שהוא \u0003ספק טומאתן,\u0004 כלומר, שבכל אלה איננו יודעים טומאה ודאית, בכל זאת \u0003שורפין את התרומה\u0004 שנגעה בהם.","\u0003ר' יוסי אומר: אף על ספק מגען\u0004 אם היה זה \u0003ברשות היחיד\u0004 — \u0003שורפין את\u0004 התרומה שנגעה בהם. שכן בטומאה האסורה מן התורה, ספיקה הנמצא ברשות היחיד אף הוא מטמא, ולדעת ר' יוסי חמורות גזירות אלה, אף שהן מספק, עד שהחמירו בהן כבדין תורה. \u0003וחכמים אומרים:\u0004 מאחר שדברים אלה הינם טמאים רק מדברי סופרים, לכך ספק מגען \u0003ברשות היחיד\u0004 אין שורפים אלא \u0003תולין,\u0004 ואילו \u0003ברשות הרבים\u0004 — \u0003טהורין\u0004 לגמרי.","\u0003ואמר עולא: אלו\u0004 ה\u0003ששה ספיקות באושא התקינו\u0004 איך צריך לנהוג בהם הלכה למעשה. ואם כן, הרי שגוש עפר ארץ העמים מטמא מזמן תקנת אושא ולא שמונים שנה לפני חורבן הבית! אלא יש להסביר כי \u0003אתו אינהו\u0004 \u0005[באו הם]\u0006 יוסי בן יועזר ויוסי בן יוחנן, \u0003גזור אגושא\u0004 \u0005[גזרו על גוש]\u0006 עפר חוץ לארץ שבתרומה שנגעה בו יש \u0003לתלות\u0004 את דינה ולא לשורפה, \u0003ואאוירא\u0004 \u0005[ועל אויר\u0006\u0005]\u0006 ארץ העמים לא גזרו \u0003ולא כלום. ואתו רבנן\u0004 \u0005[ובאו החכמים]\u0006 של \u0003שמנים שנה\u0004 האחרונות של הבית \u0003גזור אידי ואידי\u0004 \u0005[\u0006ו\u0005גזרו על זה ועל זה]\u0006 \u0003לתלות. ואתו\u0004 \u0005[ובאו]\u0006 חכמי העיר \u0003אושא גזור אגושא\u0004 \u0005[\u0006ו\u0005גזרו על גוש\u0006 עפר\u0005]\u0006 ארץ העמים שתרומה הנוגעת בו יש \u0003לשרוף\u0004 אותה. \u0003ואאוירא\u0004 \u0005[ועל האויר]\u0006 — \u0003כדקאי קאי\u0004 \u0005[כמו שהוא עומד יעמוד]\u0006 שלא החמירו יותר בדבר זה.","אחד מן הדברים שהוזכרו קודם היתה גזירת הטומאה על כלי זכוכית. ושואלים: \u0003כלי זכוכית מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003גזור בהו רבנן\u0004 \u0005[גזרו בהם חכמים]\u0006 \u0003טומאה? אמר ר' יוחנן אמר ריש לקיש: הואיל ותחלת ברייתן\u0004 (עשייתם) של כלי זכוכית \u0003מן החול,\u0004 לכך \u0003שוינהו רבנן\u0004 \u0005[עשו אותם חכמים]\u0006 \u0003ככלי חרס,\u0004 שאף הם מיוצרים מאדמה. ושואלים: \u0003אלא\u0004 אם אמנם השוו חכמים טומאת זכוכית לטומאת כלי חרס, אם כן \u0003מעתה לא תהא להן\u0004 לכלי זכוכית \u0003טהרה במקוה\u0004 כדרך שאין טהרה לכלי חרס. ו\u0003אלמה תנן\u0004 \u0005[מדוע שנינו]\u0006 בדיני טבילת כלים: \u0003ואלו\u0004 החומרים \u0003חוצצין בכלים,\u0004 שאם היו דבוקים בכלי וטבלו אותו אינו נטהר: \u0003הזפת והמור\u0004 שדבקו \u0003בכלי זכוכית\u0004 מעכבים את הטבילה. ומכאן שלכלי זכוכית טהרה במקווה!","ומשיבים שכרגיל אין לזכוכית טהרה בטבילה אלא \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]?\u0006 — במקרה המיוחד \u0003כגון שניקבו\u0004 כלי הזכוכית \u0003והטיף לתוכן אבר\u0004 (עופרת) מותכת לסתום את החור. \u0003ו\u0004הלכה זו כשיטת \u0003ר' מאיר היא,\u0004 ש\u0003אמר : הכל הולך אחר המעמיד,\u0004 כלומר, חפץ שהוא כשלעצמו אינו מסוגל או ראוי לשימוש, וחיזקו אותו בדבר אחר או בחומר אחר (\"מעמיד\") — דנים את החפץ כולו על פי המעמיד. ולכן, כלי זכוכית אלה כיון שמעמידם הוא עופרת שהיא נטהרת בטבילה כשאר מתכות, אף כלי הזכוכית הללו יש להם טהרה במקווה. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כלי זכוכית שנקבו והטיף לתוכן אבר, אמר רבן שמעון בן גמליאל\u0004 כי \u0003ר' מאיר מטמא וחכמים מטהרין.\u0004","ועוד שואלים: \u0003אלא מעתה,\u0004 אם מדמים כלי זכוכית לכלי חרס, אם כן"],["ש\u0003לא ליטמו\u0004 \u0005[ייטמאו]\u0006 \u0003מגבן\u0004 (מצידם החיצון), \u0003אלמה תנן\u0004 \u0005[\u0006ו\u0005מדוע שנינו\u0006 במשנה\u0005]\u0006 כי \u0003כלי חרס וכלי נתר\u0004 (כלים העשויים מאדמה), דיני \u0003טומאתן שוה,\u0004 שכלים אלה \u0003מיטמאין,\u0004 שדבר טמא הנכנס בחללן מטמא אותן, \u0003ו\u0004כן \u0003מטמאין\u0004 אחרים \u0003מאויריהן,\u0004 וכשהם טמאים אם נכנס דבר מאכל בחללם — הריהו נטמא. \u0003ו\u0004כן \u0003מיטמאין\u0004 הם \u0003מאחוריהן,\u0004 שאם היה בתחתית הכלי חלל ובית קיבול — גם הוא מקבל טומאה. \u0003ו\u0004אולם \u0003אין\u0004 כלי חרס \u0003מיטמאין מגביהן,\u0004 שאם נגעה טומאה בצדו החיצוני של הכלי — אין תוכו טמא. \u0003ו\u0004כן, כלי חרס \u0003שבירתן מטהרתן.\u0004 ומכאן נסיק שדווקא כלי \u0003נתר וכלי חרס הוא\u0004 ש\u0003טומאתן שוה\u0004 ודינם כך, \u0003אבל מידי אחרינא\u0004 \u0005[דבר אחר]\u0006 — \u0003לא,\u0004 ומדוע לא נמנו כלי הזכוכית עם סוגי כלים אלה? ומשיבים: \u0003כיון דכי\u0004 \u0005[שאם]\u0006 \u0003נשתברו\u0004 כלי זכוכית \u0003יש להם תקנה,\u0004 שאפשר להתיך את הזכוכית וליצור ממנה כלי מחדש, \u0003שוינהו\u0004 \u0005[עשו אותם]\u0006 חכמים \u0003ככלי מתכות\u0004 שאף הם ניתנים להתכה ויציקה מחודשת. ושואלים:","\u0003אלא מעתה,\u0004 אם אמנם הושוו כלי זכוכית לכלי מתכת, אם כן ש\u0003יחזרו\u0004 כלי זכוכית שבורים שיצרום מחדש על ידי התכה ויצירה מחדש \u0003לטומאתן\u0004 ה\u0003ישנה ככלי מתכת\u0004? \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי מתכות\u0004 בין \u0003פשוטיהן\u0004 (כלים פשוטים, שטוחים, שאין בהם חלל) \u0003ו\u0004בין \u0003מקבליהן\u0004 (כלים שיש להם בית קיבול מסויים) כולם עשויים להיות \u0003טמאין.\u0004 ואם \u0003נשברו\u0004 כלים אלה — \u0003טהרו\u0004 בכך. אך אם \u0003חזר ועשה מהן,\u0004 מן הכלים השבורים, \u0003כלים\u0004 חדשים — \u0003חזרו לטומאתן\u0004 ה\u0003ישנה. ואילו גבי\u0004 \u0005[אצל]\u0006 \u0003כלי זכוכית תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כלי עץ וכלי עור וכלי עצם וכלי זכוכית, פשוטיהן טהורין ו\u0004רק \u0003מקבליהן טמאין.\u0004 ואם \u0003נשברו\u0004 — \u0003טהרו.\u0004 ואולם אם \u0003חזר ועשה מהן כלים\u0004 — הריהם \u0003מקבלין טומאה מכאן ולהבא,\u0004 משעת עשייתם מחדש והלאה. ונדייק: \u0003מכאן ולהבא אין\u0004 \u0005[כן,\u0006 מטמאים\u0005],\u0006 אבל \u0003למפרע\u0004 — \u0003לא,\u0004 והרי שאין דין טומאה ישנה בכלי זכוכית!","ומשיבים: \u0003טומאת כלי זכוכית\u0004 הרי היא כולה \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 \u0003ו\u0004אולם גם \u0003טומאה ישנה\u0004 החוזרת וחלה על כלי מתכת שיצקום מחדש — היא \u0003דרבנן\u0004 \u0005[מדברי סופרים],\u0006 ו\u0003בטומאה דאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003אחיתו בה רבנן\u0004 \u0005[הורידו\u0006 החשיבו \u0005לה חכמים]\u0006 \u0003טומאה\u0004 וגזרו על טומאה ישנה. ואולם \u0003בטומאה דרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003לא אחיתו לה רבנן\u0004 \u0005[הורידו לה חכמים]\u0006 \u0003טומאה.\u0004 שלא רצו להוסיף ולגזור גזירת טומאה ישנה שמדברי סופרים על כלי זכוכית שעיקר טומאתם רק מדברי חכמים.","ועוד שואלים: \u0003פשוטיהן\u0004 של כלי זכוכית \u0003מיהא ליטמא\u0004 \u0005[על כל פנים ייטמאו],\u0006 \u0003דהא\u0004 \u0005[שהרי]\u0006 טומאת \u0003פשוטי כלי מתכות דאורייתא נינהו\u0004 \u0005[מן התורה היא],\u0006 וראוי איפוא לגזור טומאה זו בכלי זכוכית מדברי סופרים? ומשיבים: \u0003עבדי בהו רבנן הכירא כי היכי\u0004 \u0005[עשו בהם חכמים היכר כדי]\u0006 ש\u0003לא לשרוף עלייהו\u0004 \u0005[ישרפו עליהם]\u0006 \u0003תרומה וקדשים,\u0004 שעל ידי שינוי זה בין כלי זכוכית לכלי מתכת יבינו הכל שאין טומאת כלי זכוכית מן התורה, ולא יבואו לשרוף תרומה וקדשים שנגעו בכלי זכוכית טמאים אלא ישאירום תלויים בדינם."],["\u0003רב אשי אמר:\u0004 מתחילה אין צורך להשוות את כלי הזכוכית לכלי מתכת אלא \u0003לעולם\u0004 נאמר כי כלי זכוכית כ\u0003כלי חרס דמו\u0004 \u0005[\u0006הם \u0005נחשבים],\u0006 \u0003ודקא קשיא\u0004 \u0005[וזה שהיה קשה]\u0006 \u0003לך\u0004 ש\u0003לא ליטמו\u0004 \u0005[ייטמאו]\u0006 \u0003מגבן\u0004 כשאר כלי חרס? — \u0003הואיל ו\u0004בכלי זכוכית \u0003נראה תוכו כברו\u0004 (כצדו החיצוני), יש לדון את שני צידיהם כאילו היו בפנים, שהרי אין חציצה ביניהם למראית העין.","שנינו כי \u0003שמעון בן שטח תיקן\u0004 את נוסח ה\u0003כתובה לאשה וגזר טומאה על כלי מתכות.\u0004 ותמהים: \u0003כלי מתכות\u0004 הלא \u0003דאורייתא נינהו\u0004 \u0005[מן התורה הם]\u0006 מיטמאים! \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"אך את הזהב ואת הכסף\u0004 את הנחושת את הברזל את הבדיל ואת העופרת. כל דבר אשר יבא באש תעבירו באש וטהר אך במי נידה יתחטא וכל אשר לא יבא באש תעבירו במים\u0003\"\u0004 (במדבר לא, כב–כג)! ומשיבים: \u0003לא נצרכה\u0004 תקנה זו של שמעון בן שטח לטומאת מתכת בכלל, כי אם \u0003לטומאה ישנה\u0004 החוזרת על כלי מתכת. וכפי ש\u0003אמר רב יהודה אמר רב: מעשה בשל ציון המלכה,\u0004 שהיתה אחותו של שמעון בן שטח, \u0003שעשתה משתה לבנה ונטמאו כל כליה, ושברתן ונתנתן לצורף וריתכן ועשה מהן כלים חדשים. ואמרו חכמים: יחזרו\u0004 כל הכלים \u0003לטומאתן\u0004 ה\u0003ישנה.\u0004","לעיקר הדבר שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 גזרו בהם חכמים טומאה? ומשיבים: \u0003משום גדר מי חטאת נגעו בה.\u0004 כי, כדי להטהר מטומאת מת יש צורך להזות מי חטאת ביום השלישי וביום השביעי לטהרו (\"הוא יתחטא בו ביום השלישי וביום השביעי יטהר ואם לא יתחטא ביום השלישי וביום השביעי לא יטהר\". במדבר יט, ב) ודבר זה טרחה יתירה הוא, ולפיכך יבואו אנשים לשבור או לפגום את כלי המתכת שנטמאו, כדי לטהרם בדרך קלה יותר, ועל ידי כך יתבטל השימוש במי חטאת. ומשום כך גזרו חכמים שלעולם כלי מתכת טמאים עד שייטהרו כדינם.","שואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 שטומאה ישנה בכלי מתכות \u0003לא לכל הטומאות אמרו, אלא לטומאת המת בלבד אמרו\u0004 לגזור שיחזרו לטומאתם הישנה, ולדעתו, \u0003שפיר\u0004 \u0005[יפה]\u0006 טעם זה, שיש לומר שרק בה גזרו כיון שטהרתה קשה, שהרי צריך לשם כך טבילה והזייה שלישי ושביעי, אבל בטומאות אחרות שלטהרתן די בטבילה בלבד, לא יבוא אדם לשבור את הכלי כדי להמנע מטרחת הטבילה ולכך אין לגזור בהן.","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003לכל הטומאות אמרו\u0004 גזירת טומאה ישנה, ואף לאלו שאין צורך בהזיית מי חטאת לטהרתם, \u0003מאי איכא למימר\u0004 \u0005[מה\u0006 אם כן \u0005יש לומר]\u0006 בטעם הדבר? \u0003אמר אביי: גזירה\u0004 גזר שמעון בן שטח \u0003שמא לא יקבנו\u0004 לאותו כלי כדי לטהרו \u0003בכדי\u0004 שיעור \u0003טהרתו.\u0004 שהרי כדי ייטהר הכלי מטומאתו בדרך של שבירה, צריך שיווצר בו נקב בשיעור שלא יוכל להחזיק את הדברים אותם הוא אמור להחזיק, ומאחר שהוא חס על הכלי לא ישברנו דיו, ולא יטהר הכלי.","\u0003רבא אמר: גזירה\u0004 היא \u0003שמא יאמרו\u0004 ש\u0003טבילה בת יומא\u0004 \u0005[יום],\u0006 \u0003עולה לה,\u0004 לכלי זה כדי לטהרה. שלא ידעו אנשים כיצד נטהר כלי המתכת, ויחשבו שטהרתו היתה לא על ידי שבירה כי אם על ידי טבילה, ויבואו לחשוב שכל כלי שנטבל נטהר על ידי טבילה בו ביום, עוד לפני הערב השמש שלא כדין התורה. ומשום כך גזר עליו טומאה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל המעשי \u0005ביניהם],\u0006 בין נמוקי אביי ורבא? ומשיבים: \u0003איכא בינייהו דרצפינהו מרצף\u0004 \u0005[יש ביניהם,\u0006 הבדל זה, \u0005ששבר את הכלי שבירה גמורה].\u0006 שמצד החשש לענין שמא לא יקבנו כראוי אין לחשוש עוד, ואולם לגזירה שמא יאמרו שטבילה עולה בו ביום עדיין יש לחשוש.","עד כאן נמנו אחדות מגזירות שמונה עשר דבר, ועדיין לא נמנו כולן. ושואלים: \u0003ואידך מאי\u0004 \u0005[והאחרת מה]\u0006 \u0003היא?\u0004 ומשיבים, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 במסכת מקואות: \u0003המניח כלים תחת הצינור\u0004 (המרזב של מי הגשמים) כדי \u0003לקבל\u0004 בכלים אלה \u0003מי גשמים\u0004 — דין \u0003אחד\u0004 להם אם היו \u0003כלים גדולים\u0004 שמרוב גודלם אינם נטמאים, \u0003ו\u0004דין \u0003אחד\u0004 להם אם היו \u0003כלים קטנים\u0004 שאינם חשובים ואינם נטמאים, \u0003ואפילו\u0004 היו אלה \u0003כלי אבנים\u0004 או \u0003כלי אדמה\u0004 או \u0003כלי גללים,\u0004 שהם עשויים מגללי בקר מיובשים, וכל אלה אינם נחשבים ככלים לענין טומאה ואינם מקבלים טומאה כלל — המים שבכלים נחשבים מים שאובים, ואם נזלו המים מכלים אלה וזרמו אל המקווה שעדיין לא הושלם מילויו לכדי שיעורו שהוא ארבעים סאה והם השלימוהו — הריהם \u0003פוסלין\u0004 בכך \u0003את המקוה.\u0004 ומוסיפים שלענין זה אין הבדל בדין, ו\u0003אחד המניח\u0004 את הכלים בכוונה תחילה מתחת לאותו מרזב כדי לקבל את המים היורדים ממנו, \u0003ואחד השוכח\u0004 שם את הכלים ונתמלאו שלא על פי כוונתו, אלו \u0003דברי בית שמאי. ובית הלל מטהרין\u0004 את המקוה \u0003בשוכח\u0004 את הכלים. ו\u0003אמר ר' מאיר: נמנו ורבו בית שמאי על בית הלל,\u0004 בעליית חנניה בן חזקיה. \u0003ו\u0004עוד אמר ר' מאיר כי \u0003מודים בית שמאי בשוכח\u0004 כלים \u0003בחצר\u0004 ונתמלאו מי גשמים \u0003שהוא טהור\u0004 להשלים את המקוה לכדי שיעורו. \u0003אמר ר' יוסי: עדיין\u0004 ה\u0003מחלוקת במקומה עומדת,\u0004 ולא הודו בית הלל לבית שמאי כלל.","\u0003אמר רב משרשיא:\u0004 החכמים \u0003דבי\u0004 \u0005[של\u0006 \u0005בית\u0006 מדרשו\u0005]\u0006 של \u0003רב אמרי\u0004 \u0005[היו אומרים]:\u0006 \u0003הכל מודים\u0004 שאם הניח את הכלים \u0003בשעת קישור עבים\u0004 (עננים) בשמים, קרוב לשעת הגשם, שהמים שבכלים \u0003טמאים\u0004 (נפסלים), שוודאי נתכוון שימלאו המים את הכלים. ואם הניחם \u0003בשעת פיזור עבים\u0004 ואחר כך נתקשרו העבים וירדו גשמים ונתמלאו בהם הכלים — ל\u0003דברי הכל\u0004 המים \u0003טהורין\u0004 להשלים את המקווה לכדי שיעורו, שהרי בשעת הנחת הכלים לא היתה דעתו על מי הגשמים. \u0003לא נחלקו אלא\u0004 באופן \u0003שהניחם בשעת קישור עבים\u0004, אלא שבאותה שעה לא ירדו גשמים, \u0003ונתפזרו\u0004 העבים, \u0003ו\u0004רק אחר כך \u0003חזרו ונתקשרו\u0004 העבים וירד גשם ומילא את הכלים. ובכגון זה \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 בית הלל \u0005סבור]\u0006 שמאחר שנתפזרו העבים לאחר שהניח את הכלים — \u0003בטלה מחשבתו\u0004 למלא את הכלים במים, ונשארו הכלים בחצר משכחה, וכשנתמלאו אחר כך — לא מרצונו נתמלאו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 בית שמאי \u0005סבור]\u0006 ש\u0003לא בטלה מחשבתו,\u0004 שהרי היתה כאן כוונה מתחילה, ולבסוף נתבצעה כוונתו למרות ההפסק שבינתיים.","ותוהים: אכן לדעת ר' מאיר השלמנו למנין הגזירות גזירה נוספת, \u0003ו\u0004אולם \u0003ל\u0004דעת \u0003ר' יוסי\u0004 ש\u0003אמר\u0004 שבענין זה ה\u0003מחלוקת עדיין במקומה עומדת,\u0004 אם כן \u0003בצרי להו\u0004 \u0005[חסרו להן]\u0006 גזירות להשלמת המנין! \u0003אמר רב נחמן בר יצחק: אף\u0004 הגזירה ש\u0003בנות\u0004 ה\u0003כותים\u0004 (השומרונים) נחשבות ל\u0003נדות מעריסתן בו ביום גזרו.\u0004 שלפי ההלכה כל הרואה דם נידה ללא הבדל גיל, אפילו היא בת יום אחד — מטמאה. והכותים שאינם מקבלים את ההלכה יתכן שיש ביניהם ילדות שראו דם נידה עוד לפני התבגרותן, ולא חששו הכותים משום טומאה. ועל כן, מספק זה גזרו טומאה על כל בנות הכותים אף מעריסתן.","ושואלים: \u0003ואידך מאי היא\u0004 \u0005[וה\u0006גזירות ה\u0005אחרות מה הן]?\u0006 ומשיבים כי גזירה אחרת נזכרת במשנה. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]\u0006 מסורת הלכה שכל \u0003המטלטלין מביאין את הטומאה בעובי המרדע.\u0004 שאם האהיל צידם האחד על המת וצידם האחר על כלים, הרי הכלים טמאים משום אהל. \u0003אמר ר' טרפון:\u0004"],["\u0003אקפח\u0004 (אאבד) \u0003את בני\u0004 אם אין \u0003זו הלכה מקופחת\u0004 (מקוטעת, פגומה), \u0003ששמע השומע\u0004 פסק הלכה בענין מציאות אחרת, \u0003וטעה\u0004 וחשב כי הלכה זו נקבעה ביחס לכך שהמטלטלים מביאים את הטומאה (כשיש בהיקפן כעובי המרדע) על דבר אחר כשהם מאהילים על שניהם כאחת. ואולם ההלכה המקורית כך היא: אם היה \u0003האיכר עובר ומרדעו על כתפו ואיהל\u0004 המרדע ב\u0003צדו\u0004 ה\u0003אחת על הקבר\u0004 — \u0003טימאו אותו,\u0004 את המרדע עצמו, \u0003משום כלים המאהילים על המת.\u0004 כי כל חפץ המצוי למעלה מקבר המת (מאהיל) נטמא על ידי כך. ואולם מזה שהמרדע נטמא כשלעצמו, מכל מקום אין בכך כדי ללמד שהוא מביא את הטומאה על חפצים אחרים.","\u0003אמר ר' עקיבא: אני אתקן\u0004 ואסביר את ההלכה \u0003שיהו דברי חכמים קיימים\u0004 כלשונם, וכך תתפרש הלכה זו: \u0003שיהו כל המטלטלים מביאין את הטומאה על האדם שנושא אותן\u0004 אם היו מטלטלים אלה עבים לפחות \u0003בעובי המרדע,\u0004 כי, כפי שיבואר אחר כך, חפץ עגול כהיקפו של המרדע יש לגזור בו כאילו היה ממש אהל על המת. ודבר המשמש אהל (כיסוי) על המת, לא זו בלבד שהוא עצמו נטמא אלא אף \"כל אשר באהל יטמא שבעת ימים\" (במדבר יט, יד), ולכן אף האדם הנושא את המרדע נטמא בשל המרדע. \u0003ו\u0004אולם אותם מטלטלים שהאהילו על המת הם עצמם מביאים את הטומאה \u0003על עצמם\u0004 באהל זה \u0003בכל שהן,\u0004 ואין צורך בשיעור מסויים. \u0003ו\u0004אולם אותם חפצים המאהילים על המת לגבי \u0003שאר אדם\u0004 (שאינו נושא אותם) \u0003ו\u0004כן לגבי \u0003כלים\u0004 — אינם מטמאים אלא \u0003בפותח טפח,\u0004 שיש ברחבם של הכלים הללו לפחות טפח.","\u0003ואמר ר' ינאי: ומרדע זה שאמרו,\u0004 דווקא ש\u0003אין בעביו טפח ו\u0004אולם \u0003יש בהיקפו טפח, וגזרו\u0004 חכמים \u0003על היקפו משום עביו.\u0004 שאילו היה עוביו טפח היה מטמא באהל מדברי תורה, על כן החמירו בהיקפו טפח מגזירת חכמים והוא עוד אחד משמונה עשר דבר.","ושואלים: \u0003ול\u0004דעת \u0003ר' טרפון\u0004 ש\u0003אמר אקפח את בני\u0004 לפי \u0003שזו הלכה מקופחת,\u0004 הלא \u0003בצרי להו\u0004 \u0005[חסרו להן]\u0006 הגזירות ואין שמונה עשר! \u0003אמר רב נחמן בר יצחק: אף\u0004 הגזירה \u0003שבנות כותים\u0004 נחשבות כ\u0003נדות מעריסתן, בו ביום גזרו. ובאידך\u0004 \u0005[ובאחרת]\u0006 סבור הוא \u0003כר' מאיר,\u0004 לענין מים שאובים, ועל ידי כך הושלם מנין הגזירות.","\u0003ואידך\u0004 \u0005[והאחרת]\u0006 עוד גזירה מאותן גזירות — ענין \u0003הבוצר לגת.\u0004 שנחלקו שמאי והלל אם הנוזלים שנסחטו בלא כוונה מן הענבים שנבצרו על מנת לדרכם ולעשותם יין מכשירים לקבל טומאה או לא. ש\u0003שמאי אומר: הוכשר\u0004 המשקה הזה לקבל טומאה, \u0003הלל אומר: לא הוכשר. אמר לו הלל לשמאי:\u0004 אם כן, \u0003מפני מה בוצרין\u0004 ענבים \u0003בטהרה\u0004 (בכלים טהורים), שצריך לדעתך להזהר מטומאה בשעת בצירה, כי הענבים מוכשרים לטומאה על ידי המיץ הנוזל מהם, \u0003ו\u0004אולם \u0003אין מוסקין\u0004 זיתים \u0003בטהרה,\u0004 והרי לדעתך שהוכשר המשקה היוצא לקבל טומאה אם כן מדוע אין חוששים למוהל הזב מן הזיתים?","\u0003אמר לו\u0004 שמאי: \u0003אם תקניטני\u0004 (תרגיז אותי) ותעמוד על כך שאין למצוא הבדל בין מסיקה ובצירה, הרי כדי שלא לסתור את הדבר — \u0003גוזרני טומאה אף על המסיקה.\u0004 וסיפרו, שכיון שהיתה המחלוקת חריפה ביותר \u0003נעצו חרב בבית המדרש,\u0004 ו\u0003אמרו: הנכנס\u0004 לבית המדרש — \u0003יכנס, והיוצא\u0004 — \u0003אל יצא,\u0004 כדי שיתאספו כל החכמים ויגיעו לקביעת הלכה. \u0003ואותו היום היה הלל כפוף ויושב לפני שמאי כאחד מן התלמידים.\u0004 ואמרו: \u0003והיה\u0004 היום \u0003קשה לישראל כיום שנעשה בו העגל,\u0004 כי הלל שהיה נשיא הוכרח לשבת בהכנעה לפני שמאי, ושיטת בית שמאי גברה בהצבעה שנערכה באותו יום. \u0003וגזור\u0004 \u0005[וגזרו]\u0006 \u0003שמאי והלל ולא קבלו מינייהו\u0004 \u0005[מהם],\u0006 \u0003ואתו תלמידייהו גזור\u0004 \u0005[ובאו תלמידיהם\u0006 ו\u0005גזרו]\u0006 \u0003וקבלו מינייהו\u0004 \u0005[מהם].\u0006","לעיקר הדבר שואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 גזרו שהמשקים שנסחטו בלא כוונה על הענבים נחשבים לטמאים? \u0003אמר ר' זעירי אמר ר' חנינא: גזירה\u0004 גזרו חכמים מתוך החשש \u0003שמא יבצרנו\u0004 את הענבים \u0003בקופות\u0004 (סלים) \u0003טמאות,\u0004 ומשום טומאת הכלי ממילא נחשב המשקה שבו כמכשיר לטומאה.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003כלי טמא חושב משקים,\u0004 כלומר, משקים הנמצאים בכלי טמא הרי הם כאילו היו שם מרצונו, ומכשירים לקבל טומאה אף אם לא נתכוון למשקים שבכלי. ואולם \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 ש\u0003אין כלי טמא חושב משקין, מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006 בהסבר הגזירה? \u0003אלא אמר זעירי אמר ר' חנינא:\u0004 הטעם אינו כפי שאמרנו, אלא \u0003גזירה\u0004 זו גזרו \u0003שמא יבצרנו בקופות מזופפות\u0004 (משוחות בזפת ואטומות), שכיון שאין המשקים היוצאים מן הענבים הולכים לאיבוד מתוך הקופות הללו, נוח לו שייצאו המשקים מן הענבים שעל ידי כך הוא מזרז את דריכת הענבים בגת. וכיון שנוח לו במשקים הריהם מכשירים לטומאה.","\u0003רבא אמר:\u0004 טעם ה\u0003גזירה\u0004 הוא \u0003משום הנושכות,\u0004 שהם אשכולות ענבים הדבוקים זה בזה, וכשמפרידים אותם ניתז המיץ, וכיון שהדבר נעשה בידיו מדעת ומרצון, מכשיר המשקה היוצא. וכפי \u0003שאמר רב נחמן אמר רבה בר אבוה\u0004 בדומה: \u0003פעמים שאדם הולך לכרמו\u0004 כדי \u0003לידע\u0004 (לדעת) \u0003אם\u0004 כבר \u0003הגיעו ענבים ל\u0004זמן \u0003בצירה או לא, ונוטל אשכול ענבים לסוחטו, ומזלף\u0004 (מתיז, שופך) את המיץ \u0003על גבי\u0004 ה\u0003ענבים,\u0004 ועל פי טיב המיץ יודע אם בשלו הענבים כל צרכם. ואם כן, מיץ ענבים זה בידיו ולרצונו נעשה, ולכך הוא מכשיר לקבל טומאה, שאפילו \u0003בשעת בצירה\u0004 יתכן ש\u0003עדיין משקה\u0004 זה \u0003טופח\u0004 (רטוב) \u0003עליהם.\u0004","מאחר ועדיין לא נמנו כל שמונה עשרה הגזירות \u0003שגזרו בו ביום, שואלים: ואידך\u0004 \u0005[והאחרת]\u0006 מה היא? \u0003אמר\u0004"],["\u0003טבי רישבא\u0004 \u0005[צייד העופות]\u0006 שכך \u0003אמר שמואל: אף\u0004 הגזירה ש\u0003גידולי תרומה,\u0004 כלומר, שהפירות היוצאים מתרומה שנזרעה בארץ, אף הם נחשבים לתרומה, אף גזירה זו \u0003בו ביום גזרו.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 גזרו כך? \u0003אמר ר' חנינא: גזירה משום תרומה טהורה ביד ישראל,\u0004 שאדם שלא ירצה לתת לכהן את התרומה, יזרענה בקרקע ובכך יבטלה מדין תרומה. וכדי שלא יבואו לעשות כן גזרו שגם הצומח מן התרומה נחשב כתרומה, ועל כן אינו מרויח בכך כלום.","\u0003אמר רבא: אי דחשידי להכי, אפרושי נמי\u0004 \u0005[אם חשודי\u0006 \u0005ם\u0006 הם \u0005על כך, להפריש גם כן]\u0006 \u0003לא ליפרשו\u0004 \u0005[יפרישו]\u0006 תרומה כלל! \u0003אלא אמר רבא:\u0004 אנו יודעים כי \u0003ישראל,\u0004 שלא כלוי, \u0003כיון\u0004 שמעיקר הדין \u0003אפשר למעבד\u0004 \u0005[לעשות],\u0006 להפריש כתרומה, \u0003חטה אחת כ\u0004דעת \u0003שמואל\u0004 שאמר שמן התורה אין שיעור קבוע לתרומה, ואף אם מפריש חטה אחת על כל הגורן יצא ידי חובתו, \u0003ו\u0004מאחר ואותו אדם בכל זאת \u0003לא קעביד\u0004 \u0005[עשה]\u0006 כך כדי להפטר מחובת ההפרשה, הרי \u0003הימוני מהימני\u0004 \u0005[נאמן\u0006 הוא\u0005],\u0006 ואין לחשוש שמא ירצה להפטר מן ההפרשה באמצעות זריעתה. \u0003אלא\u0004 טעם ה\u0003גזירה\u0004 הוא \u0003משום תרומה טמאה ביד כהן.\u0004 שתרומה זו אסורה באכילה אף לכהן ודינה בשריפה, אלא שמותר לכהן להנות משריפתה, וחוששים \u0003דילמא משהי לה גביה\u0004 \u0005[שמא ישהה אותה אצלו]\u0006 וימתין עד עונת הזריעה, ואז ישתמש בה לזריעה. \u0003ו\u0004יתכן כי בשל כך \u0003אתי\u0004 \u0005[יבוא]\u0006 \u0003לידי תקלה,\u0004 שבמשך הזמן עלול הוא לשכוח שהתרומה טמאה, ויאכלנה.","ועוד בענין שמונה עשרה הגזירות\u0003, שואלים: ואידך\u0004 \u0005[והאחרת]\u0006 מה היא? \u0003אמר ר' חייא בר אמי משמיה\u0004 \u0005[משמו]\u0006 של \u0003עולא: אף\u0004 גזירה זו ש\u0003מי\u0004 שהחזיק ארנק ובו כסף בערב שבת, ו\u0003החשיך\u0004 לו \u0003בדרך,\u0004 שאף שמדברי תורה מותר לו לטלטל את הארנק בהפסקות של פחות מארבע אמות, ומכל מקום אסרו עליו חכמים לעשות כן, ואמרו שצריך שיהיה \u0003נותן\u0004 את \u0003כיסו\u0004 (ארנקו) \u0003לגוי\u0004 המהלך עמו בדרך — \u0003בו ביום גזרו.\u0004","\u0003ואידך\u0004 \u0005[ו\u0006הגזירה \u0005האחרת]\u0006 — \u0003אמר\u0004 החכם \u0003באלי אמר אבימי סנוותאה\u0004 \u0005[מן\u0006 המקום \u0005סנוותה]:\u0006 \u0003פתן\u0004 של הגוים \u0003ושמנן ויינן ובנותיהן\u0004 — \u0003כולן\u0004 גזירה אחת \u0003משמונה עשר דבר הן.\u0004 ושואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר,\u0004 שלשיטתו נמצאו כבר שמונה עשרה גזירות. \u0003אלא ל\u0004שיטת \u0003ר' יוסי,\u0004 הסבור שבענין כלים שבחצר שנוי הדבר במחלוקת, אם כן רק \u0003שבסרי הווין\u0004 \u0005[שבע עשרה הן]!\u0006 ומשיבים: \u0003איכא\u0004 \u0005[יש]\u0006 אותו דבר שאמר \u0003רב אחא בר אדא.\u0004 ש\u0003אמר רב אחא בר אדא אמר ר' יצחק: גזרו\u0004 איסור \u0003על\u0004 אכילת \u0003פתן\u0004 של גוים \u0003משום שמנן. ו\u0004גזרו איסור \u0003על שמנן\u0004 — \u0003משום יינן.\u0004 ויש כאן איפוא שתי גזירות נפרדות.","ותוהים: \u0003על פתן משום שמנן?! מאי אולמיה\u0004 \u0005[מה תוקפו]\u0006 של האיסור ב\u0003שמן\u0004 יותר \u0003מ\u0004ב\u0003פת\u0004 לחם? \u0003אלא\u0004 יש לומר כי \u0003גזרו\u0004 איסור \u0003על פתן ו\u0004על \u0003שמנן משום יינן. ועל יינן\u0004 גזרו איסור \u0003משום\u0004 שהוא מביא לקירוב הלבבות ויבואו לשאת את \u0003בנותיהן. ועל בנותיהן\u0004 — \u0003משום דבר אחר\u0004 (עבודה זרה). \u0003ו\u0004עוד גזרו \u0003על דבר אחר\u0004 — \u0003משום דבר אחר.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 אותו \u0003דבר אחר\u0004 שרמזו כאן? \u0003אמר רב נחמן בר יצחק: גזרו על תינוק גוי\u0004 שיהיה דינו \u0003שמטמא בזיבה\u0004 כזב גדול, אף על פי שאין בו טומאה. וזאת כדי להרחיק את ילדי ישראל מילדי הגוים, \u0003שלא יהיה תינוק ישראל רגיל אצלו במשכב זכור.\u0004 ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003ל\u0004שיטת \u0003ר' מאיר נמי תשסרי הויין\u0004 \u0005[גם כן\u0006 קשה שהרי לפי זה \u0005תשע עשרה\u0006 גזירות \u0005הן]!\u0006 ומשיבים: לשיטת ר' מאיר גזירת ה\u0003אוכלין ו\u0004ה\u0003כלים שנטמאו במשקין בחדא חשיב להו\u0004 \u0005[כאחת חושב הוא אותן],\u0006 ואם כן אף לשיטתו יש שמונה עשרה גזירות בלבד.","במשנה זו מצויה מחלוקת יסודית בין בית הלל ובית שמאי: האם יש צורך להרחיק מדברים שאסור לעשותם בשבת עוד בערב שבת, או שמא מותר להתחיל בפעולה לפני השבת, אף שהוא יודע שעשייתה תימשך מאליה ביום השבת. ובפרטים אלה נחלקו: ש\u0003בית שמאי אומרים: אין שורין\u0004 בערב שבת סמוך לשבת \u0003דיו\u0004 יבש במים \u0003ו\u0004לא \u0003סמנים\u0004 יבשים של צבע, \u0003ו\u0004לא \u0003כרשינין\u0004 למאכל בהמה לרככם במים, \u0003אלא\u0004 אם נותר עד כניסת השב די זמן \u0003כדי\u0004 (כשברור) \u0003שישורו\u0004 דיים \u0003מבעוד יום\u0004 לפני כניסת השבת כדי צרכם, ושרייתם הנוספת בשבת לא תביא תועלת. \u0003ובית הלל מתירין.\u0004 וכן \u0003בית שמאי אומרים: אין נותנין אונין\u0004 (חבילות חוטים) \u0003של פשתן לתוך התנור\u0004 בערב שבת \u0003אלא כדי שיהבילו\u0004 (יתחממו) \u0003מבעוד יום. ו\u0004כן \u0003לא\u0004 מכניסים \u0003את הצמר ליורה\u0004 של צבע \u0003אלא כדי שיקלוט\u0004 את \u0003העין\u0004 (הגוון) מבעוד יום. \u0003ובית הלל מתירין.\u0004","\u0003בית שמאי אומרים: אין פורסין מצודות\u0004 (מלכודות) ל\u0003חיה, ועופות ודגים אלא כדי\u0004 שיעור זמן שיש שאפשרות \u0003שיצודו\u0004 בהן \u0003מבעוד יום, ובית הלל מתירין. ו\u0004כן אמרו \u0003בית שמאי\u0004 ש\u0003אין מוכרין לגוי\u0004 בערב שבת, \u0003ו\u0004אף \u0003אין טוענין עמו\u0004 משא על חמורו \u0003ואין מגביהין עליו\u0004 משא \u0003אלא\u0004 תוך \u0003כדי\u0004 הזמן \u0003שיגיע\u0004 הגוי \u0003למקום קרוב\u0004 עוד לפני השבת, ולא יהיה חלק ליהודי בחילול השבת הנעשה על ידי הגוי. \u0003ובית הלל מתירין.\u0004 וכן \u0003בית שמאי אומרים: אין נותנין עורות לעבדן\u0004 (מעבד עורות) גוי, \u0003ולא כלים\u0004 (בגדים) \u0003לכובס גוי אלא\u0004 ב\u0003כדי שיעשו מבעוד יום\u0004 לפני השבת. \u0003ובכולן בית הלל מתירין עם\u0004"],["\u0003השמש,\u0004 כלומר, כל עוד השמש זורחת ביום הששי — מותר לתת את הדברים לגוי. \u0003אמר רבן שמעון בן גמליאל: נוהגים היו בית אבא,\u0004 הנשיאים שמבית הלל, \u0003שהיו נותנים כלי לבן\u0004 שלהם \u0003לכובס גוי\u0004 רק \u0003שלשה ימים קודם לשבת. ו\u0004אולם \u0003שוין\u0004 (מסכימים) \u0003אלו ואלו,\u0004 גם בית שמאי וגם בית הלל, \u0003שטוענין\u0004 מלכתחילה את \u0003קורת בית הבד\u0004 על הזיתים מערב שבת מבעוד יום כדי שייסחטו הזיתים במשך השבת, \u0003ו\u0004כן שטוענים את \u0003עגולי הגת\u0004 לסייע בדריכת הענבים.","לפני בירור הדברים לגופם, מבררים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 הסובר כי \u0003נתינת מים לדיו\u0004 בלי לעשות פעולה נוספת — \u0003זו היא\u0004 בכלל \u0003שרייתן,\u0004 וחייבים עליה בשבת משום אב מלאכה של לישה? \u0003אמר רב יוסף:\u0004 שיטה זו — שיטת \u0003רבי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 היה \u0003אחד נותן את הקמח ואחד\u0004 אחר \u0003נותן את המים\u0004 לכלי אחד — \u0003האחרון חייב,\u0004 משום לישת בצק, שהיא מלאכה האסורה בשבת, אף שלא לש את הבצק בפועל, אלו \u0003דברי רבי. ר' יוסי אומר: אינו חייב\u0004 על מלאכת לישה \u0003עד שיגבל\u0004 (ילוש) ממש את הבצק. הרי שלשיטת רבי השריה במים בלבד נחשבת למלאכה.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003קאמר\u0004 \u0005[אמר]\u0006 \u0003ר' יוסי\u0004 כן \u0003אלא בקמח, דבר\u0004 \u0005[שבן]\u0006 \u0003גיבול הוא,\u0004 שהוא עשוי להיגבל, ולכן אין לישה אלא כשמגבלים ממש את הקמח במים. \u0003אבל דיו דלאו בר\u0004 \u0005[שלא בן]\u0006 \u0003גיבול הוא, אימא\u0004 \u0005[אמור]\u0006 אולי כי שרייתו בכגון זה נחשבת לגביו כמלאכה שלמה ועל כן \u0003ליחייב\u0004 \u0005[יהיה חייב]\u0006 אף לדעת ר' יוסי! ודוחים: \u0003לא סלקא דעתך\u0004 \u0005[יעלה\u0006 על דעתך] לומר כן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 היה \u0003אחד נותן את האפר ואחד נותן את המים\u0004 — \u0003האחרון חייב,\u0004 אף שלא לש אותם כאחד, אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר:\u0004 אינו חייב \u0003עד שיגבל\u0004 אותם.","הרי שלדעת ר' יוסי בר' יהודה אינו חייב משום מלאכת לישה אלא אם לש את הדבר בפועל, וכפי שאמר לגבי אפר אף שאינו בר גיבול. ושואלים: \u0003ודילמא מאי\u0004 \u0005[ושמא מה\u0006 משמעו\u0005]\u0006 של \u0003\"אפר\"\u0004 האמור כאן — \u0003עפר\u0004 הוא \u0003דבר\u0004 \u0005[שבן]\u0006 \u0003גיבול הוא,\u0004 ולכן אמר שאינו חייב עד שיגבל, אבל באפר שאינו בר גיבול אף הוא סובר כי חייב אף אם לא גיבלו בפועל\u0003?!\u0004 ודוחים: \u0003והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא אחת לשון \u0003\"אפר\", והתניא\u0004 \u0005[והרי שנינו]\u0006 בברייתא אחרת לשון \u0003\"עפר\"!\u0004 ונמצא שבשני המקרים השונים חלק ר' יוסי בר' יהודה. ואולם הוכחה זו נדחית: \u0003מידי גבי הדדי תניא\u0004 \u0005[וכי שנויות הן זו אצל זו]?\u0006 שאילו היו שתי ברייתות אלה שנויות יחד אפשר היה באמת ללמוד מכאן שר' יוסי בר' יהודה חולק גם באפר וגם בעפר. ואולם מאחר והברייתא המדברת באפר נשנתה במקום אחר על ידי אמורא אחר שמסרה בשם ר' יוסי, ואין אם כן להוכיח מהבדל הלשונות דבר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003פותקין\u0004 (פותחים) את תעלת המים העוברת סמוך לגינה כדי שיבואו \u0003מים לגינה ערב שבת עם חשיכה ו\u0004נותנים לה שתהיה \u0003מתמלאת והולכת כל היום,\u0004 יום השבת, \u0003כולו. ו\u0004כן \u0003מניחין מוגמר\u0004 (בשמים המונחים על גבי גחלים) \u0003תחת הכלים\u0004 (בגדים) ב\u0003ערב שבת ו\u0004הבגדים \u0003מתגמרין\u0004 (מתבשמים) \u0003והולכין כל היום כולו. ו\u0004כמו כן \u0003מניחין\u0004 מלכתחילה \u0003גפרית תחת הכלים\u0004 ב\u0003ערב שבת עם חשיכה,\u0004 כדי שיקבלו גוון במשך השבת, \u0003ומתגפרין,\u0004 מקבלים אותו גוון, \u0003והולכין כל היום,\u0004 יום השבת, \u0003כולו. ומניחין קילור\u0004 \u0005[תחבושת רטובה]\u0006 \u0003על גבי העין ו\u0004כן \u0003איספלנית\u0004 \u0005[תחבושת שמשוחה עליה משחה]\u0006 \u0003על גבי מכה\u0004 ב\u0003ערב שבת עם חשיכה, ומתרפאת\u0004 המכה \u0003והולכת כל היום,\u0004 יום השבת, \u0003כולו. אבל אין נותנין חטין\u0004 (חיטים) \u0003לתוך הריחים של מים אלא\u0004 לפי מידה \u0003בכדי שיטחנו מבעוד יום\u0004 ולא בשבת.","ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 אסרו בריחיים והתירו בשאר המלאכות? \u0003אמר רבה: מפני שמשמעת קול,\u0004 ונשמע הדבר ברבים שטוחנים בריחיים בשבת. ואף שאין בכך איסור מלאכה, מכל מקום יש בדבר זלזול בכבוד השבת, ומשום כך אסרו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף\u0004 לרבה: \u0003ולימא מר\u0004 \u0005[ויאמר אדוני]\u0006 נימוק טוב יותר, \u0003משום שביתת כלים,\u0004 שאף כליו של אדם מישראל צריך שלא יעשו מלאכה ביום השבת! וכפי \u0003דתניא\u0004 \u0005[ששנינו\u0006 במכילתא\u0005]:\u0006 מה שנאמר \u0003\"ובכל אשר אמרתי אליכם תשמרו\"\u0004 (שמות כג, יג), הרי זה רמז לדברים שנאמרו בתורה שבעל פה, ובאים \u0003לרבות שביתת כלים\u0004 ביום השבת. \u0003אלא אמר רב יוסף:\u0004 טעם האיסור בריחיים הוא \u0003משום שביתת כלים.\u0004","מאחר שהוזכרה חובת השבתת הכלים בשבת, אומרים: \u0003השתא\u0004 \u0005[עכשיו]\u0006 ש\u0003אמרת\u0004 כי גם \u0003לבית הלל אית להו\u0004 \u0005[יש להם,\u0006 הם סבורים\u0005]\u0006 כי \u0003שביתת כלים\u0004 בשבת חובה \u0003דאורייתא\u0004 \u0005[שמן התורה]\u0006 היא, אם כן \u0003גפרית ומוגמר\u0004 שמניחים תחת הכלים \u0003מאי טעמא שרו\u0004 \u0005[מה טעם התירו]\u0006 אותם? והלא הדבר נעשה בשבת באמצעות הכלים!ומשיבים: \u0003משום דלא קעביד\u0004 \u0005[שאינו עושה]\u0006 \u0003מעשה,\u0004 שהכלי עצמו אינו עושה כל פעולה בשעה שהגחלים או הגפרית בוערות. וכן \u0003אונין של פשתן מאי טעמא שרו\u0004 \u0005[מה טעם התירו]\u0006 להניח אותם בתנור ערב שבת עם חשיכה כדי ליבשם אף על פי שהמלאכה נמשכת ביום השבת — \u0003משום דלא עביד\u0004 \u0005[שאינו עושה]\u0006 בכך \u0003מעשה\u0004 של ממש, שכן אין התנור עושה כל פעולה, אלא אדרבא הוא \u0003מינח נייחא\u0004 \u0005[נח]\u0006 במקומו ומלאכת הייבוש נעשית מאליה. ואולם לפי זה \u0003מצודות חיה ודגים דקא עביד\u0004 \u0005[שהן עושות]\u0006 \u0003מעשה\u0004 של ממש בלכידה, \u0003מאי טעמא שרו\u0004 \u0005[מה טעם התירו]\u0006 להניחם בערב שבת עם חשיכה? ומסבירים: \u0003התם נמי בלחי וקוקרי דלא קעביד\u0004 \u0005[שם גם כן\u0006 מדובר \u0005בחכה וברשת שאינן עושות]\u0006 \u0003מעשה,\u0004 אלא הן עומדות במקומן והדג בא אליהם ונלכד ממילא. ואכן מלכודת העושה פעולה מסויימת — אסורה.","\u0003והשתא\u0004 \u0005[ו\u0006אולם \u0005עכשיו]\u0006 ש\u0003אמר רב אושעיא אמר רב אסי: מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 שלדעתו חובת \u0003שביתת כלים\u0004 בשבת \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 היא — דעת \u0003בית שמאי היא ולא\u0004 דעת \u0003בית הלל,\u0004 ואם כן יש לומר ש\u0003ל\u0004שיטת \u0003בית שמאי בין קעביד\u0004 \u0005[שהוא עושה]\u0006 \u0003מעשה, בין דלא קעביד\u0004 \u0005[שאינו עושה]\u0006 \u0003מעשה\u0004 — \u0003אסור. ול\u0004דעת \u0003בית הלל, אף על גב דקעביד\u0004 \u0005[אף על פי שהוא עושה]\u0006 \u0003מעשה\u0004 — מכל מקום \u0003שרי\u0004 \u0005[מותר].\u0006 ושואלים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמרת\u0004 כי \u0003ל\u0004דעת \u0003בית שמאי אף על גב דלא עביד\u0004 \u0005[אף על פי שאינו עושה]\u0006 \u0003מעשה\u0004 — \u0003אסור, אי הכי\u0004 \u0005[אם כך],\u0006"],["\u0003מוגמר וגפרית\u0004 תחת הכלים \u0003מאי טעמא שרו\u0004 \u0005[מה טעם התירו]\u0006 \u0003בית שמאי\u0004 לעשות כן? ומשיבים: לא דובר בכלי שמניחים בתוכו את המוגמר, כי אם \u0003התם מנח אארעא\u0004 \u0005[שם מונח\u0006 חומר הבעירה, \u0005על הארץ]\u0006 ואין איפוא כל כלי החייב בשביתה. ועוד שואלים: \u0003גיגית\u0004 שמניחים בה פירות או תבואה כדי להתסיסם ולעשות מהם שיכר, והם שוהים בה זמן רב, \u0003ונר\u0004 השבת, \u0003וקדרה\u0004 שמניחים על האש מבעוד יום, \u0003ושפוד\u0004 שהניחו עליו צלי מבעוד יום \u0003מאי טעמא שרו\u0004 \u0005[מה טעם התירו]\u0006 \u0003בית שמאי\u0004 להניחם בערב שבת מבעוד יום אף שמלאכתם נמשכת ונעשית לאורך זמן ואף בתוך יום השבת? ומשיבים: מדובר באופן \u0003דמפקר להו אפקורי\u0004 \u0005[שמפקיר אותם,\u0006 את הכלים\u0005],\u0006 שלדעת בית שמאי יש להפקיר מבעוד יום את הכלים הללו, וכיון שהפקירם — אינם עוד כלים של ישראל ואינם חייבים איפוא בשביתה.","ושואלים: על פי סיכומים אלה \u0003מאן תנא להא דתנו רבנן\u0004 \u0005[מי הוא ששנה\u0006 משנה \u0005זו ששנו חכמים]:\u0006 \u0003לא תמלא אשה קדרה עססיות ותורמסין\u0004 (מיני קטניות) \u0003ותניח לתוך התנור\u0004 כדי לבשלם ב\u0003ערב שבת עם חשכה. ואם נתנן\u0004 — לא רק שאסורים ביום השבת עצמו, אלא אף \u0003למוצאי שבת אסורין\u0004 באכילה מיד עם צאת השבת, וצריך להמתין \u0003בכדי שיעשו,\u0004 כלומר, שיעור זמן המספיק לבישול תבשיל זה מתחילה, כדי שלא יהנה ממלאכה שנעשתה בשבת. \u0003וכיוצא בו\u0004 אמרו: \u0003לא ימלא נחתום\u0004 (אופה) \u0003חבית של מים ויניח לתוך התנור ערב שבת, עם חשכה\u0004 כדי להרתיח את המים שבתוכה, \u0003ואם עשה כן\u0004 — אף \u0003למוצאי שבת אסורין\u0004 המים מיד עם צאת השבת עד כדי זמן \u0003בכדי שיעשו\u0004 מתחילה. והאם \u0003לימא\u0004 \u0005[נאמר]\u0006 שתוספתא זו לדעת \u0003בית שמאי היא, ולא\u0004 לדעת \u0003בית הלל?\u0004 ומשיבים: \u0003אפילו תימא\u0004 \u0005[תאמר]\u0006 כי היא לדעת \u0003בית הלל,\u0004 ובמקרים אלה אף לדעתם \u0003גזירה\u0004 גזרו חכמים מחשש \u0003שמא יחתה\u0004 (ינער) המבשל את ה\u0003גחלים\u0004 כדי להחיש את הבישול.","ושואלים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003מוגמר וגפרית נמי לגזור\u0004 \u0005[גם כן יגזרו]\u0006 עליהם לאסור את הנחתם מתחת לכלים בערב שבת עם חשיכה! ומשיבים: \u0003התם לא מחתי להו\u0004 \u0005[שם אינו חותה אותם],\u0006 \u0003דאי מחתי סליק בהו קוטרא, וקשי להו\u0004 \u0005[ש\u0006כן \u0005אם יחתה יעלה בהם עשן, וקשה,\u0006 מזיק, \u0005להם],\u0006 שתוספת עשן עצים מקלקלת את ריח הבושם ואת ציפוי הגפרית. ועוד שואלים: ב\u0003אונין של פשתן נמי ליגזור\u0004 \u0005[גם כן נגזור]!\u0006 ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003כיון דקשי להו זיקא\u0004 \u0005[שמזיקה להם הרוח],\u0006 לפיכך \u0003לא מגלי להו\u0004 \u0005[אינו מגלה אותם],\u0006 ולא יבוא לחתות. ועוד שואלים: ב\u0003צמר\u0004 שמכניסים \u0003ליורה\u0004 כדי לצובעו גם כן \u0003לגזור\u0004 \u0005[יגזרו]!\u0006 \u0003אמר שמואל:\u0004 המדובר הוא \u0003ביורה עקורה\u0004 מעל גבי האש, שאין חשש שיחתה בגחלים. ועדיין שואלים: \u0003וניחוש\u0004 \u0005[ונחשוש]\u0006 \u0003שמא מגיס\u0004 \u0005[יבחוש]\u0006 \u0003בה,\u0004 באותה יורה, והריהו מסייע בכך לבישול, ואסור הדבר מן התורה! אלא יש לומר שמדובר \u0003ב\u0004יורה שהיא \u0003עקורה\u0004 מעל האש \u0003וטוחה\u0004 (מכוסה בטיט), שמדביקים טיט סביב לכיסויה כדי שלא תיפתח.","ומעירים: \u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 שבדברים אלה איסור העמדת הקדירה על גבי האש הוא מחמת \u0003גזירה\u0004 שגזרו חכמים מחשש \u0003שמא יחתה בגחלים,\u0004 אם כן \u0003האי קדרה חייתא שרי לאנוחה\u0004 \u0005[קדירה זו של בשר חי מותר להניחה]\u0006 ב\u0003ערב שבת עם חשיכה בתנורא\u0004 \u0005[בתנור].\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003כיון דלא חזי לאורתא\u0004 \u0005[שאינה ראויה לערב],\u0006 שלא תספיק להתבשל עד אז, \u0003אסוחי מסח דעתיה מיניה\u0004 \u0005[מסיח דעתו\u0006 \u0003ממנה] ולא אתי לחתויי\u0004 \u0005[יבוא לחתות]\u0006 ב\u0003גחלים. ו\u0004כן \u0003בשיל\u0004 \u0005[\u0006בשר \u0005מבושל]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005]\u0006 להניחו על גבי האש בערב שבת עם חשיכה, שכיון שהוא מבושל למדי לא יבוא אדם לחתות בגחלים להוסיף בבישולו. \u0003בשיל ולא בשיל\u0004 \u0005[מבושל ואינו מבושל]\u0006 די צרכו — \u0003אסיר\u0004 \u0005[אסור],\u0006 שיש לחשוש שמא יבוא לחתות בגחלים. \u0003ואי שדא ביה גרמא חייא\u0004 \u0005[ואם השליך בה,\u0006 בקדירה זו\u0005, עצם חיה,\u0006 לא מבושלת\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005],\u0006 שבגלל העצם לא יוציא את הבשר בערב.","\u0003והשתא\u0004 \u0005[ועכשיו]\u0006 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 כי \u0003כל מידי דקשי ליה זיקא\u0004 \u0005[דבר שקשה,\u0006 שמזיקה \u0005לו הרוח]\u0006 \u0003לא מגלי ליה\u0004 \u0005[אין מגלים אותו],\u0006 אפשר לומר כי \u0003האי בשרא דגדיא ושריק\u0004 \u0005[אותו בשר של גדי\u0006 ששמים אותו בתנור ששפתו \u0005סתומה\u0006 בטיח\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005],\u0006 שבשר הגדי ממהר להתבשל וגם פי התנור סתום, ואין לחשוש שמא יבוא לחתות. \u0003דברחא ולא שריק\u0004 \u0005[\u0006בשר \u0005של תיש ואין\u0006 שפת התנור \u0005סתומה\u0006 בטיח\u0005]\u0006 — \u0003אסור\u0004 \u0005[אסור].\u0006 עד כאן דובר במקרים שדינם ברור, ואולם \u0003דגדיא ולא שריק\u0004 \u0005[\u0006בשר \u0005של גדי ואין\u0006 שפת התנור \u0005סתומה\u0006 טיח\u0005],\u0006 או \u0003דברחא ושריק\u0004 \u0005[של תיש ו\u0006פת התנור \u0005סתומה\u0006\u0005]\u0006 — בכך נחלקו, \u0003רב אשי שרי\u0004 \u0005[התיר],\u0006 \u0003ו\u0004אילו \u0003רב ירמיה מדיפתי אסיר\u0004 \u0005[אסר].\u0006 ושואלים: \u0003ו\u0004לדעת \u0003רב אשי דשרי\u0004 \u0005[שהתיר],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אין צולין בשר, בצל, וביצה\u0004 בערב שבת \u0003אלא\u0004 אם כן יש זמן מספיק \u0003כדי שיצולו מבעוד יום.\u0004 והרי שאין מניחים בערב שבת בתנור בשר שעדיין אינו צלוי דיו! ומשיבים: \u0003התם בברחא ולא שריק\u0004 \u0005[שם,\u0006 מדובר \u0005ב\u0006בשר \u0005תיש\u0006 שאין שפת התנור \u0005סתומה\u0006 בטיח\u0005],\u0006 אבל במקרים אחרים — מותר.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 כי \u0003דגדיא\u0004 \u0005[\u0006בשר \u0005של גדי]\u0006 בין אם התנור \u0003שריק\u0004 \u0005[סתום],\u0006 \u0003בין לא שריק\u0004 \u0005[\u0006ש\u0005אינו סתום]\u0006 לדעת הכל \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005].\u0006 \u0003דברחא נמי ושריק\u0004 \u0005[של תיש גם כן\u0006 כאשר שפת התנור \u0005סתומה]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005].\u0006 \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה \u0003בברחא ולא שריק\u0004 \u0005[ב\u0006בשר \u0005תיש ואין\u0006 שפת התנור \u0005סתומה].\u0006 ש\u0003רב אשי שרי\u0004 \u0005[התיר],\u0006 \u0003ו\u0004אילו \u0003רב ירמיה מדיפתי אסיר\u0004 \u0005[אסר].\u0006 ושואלים: \u0003ול\u0004דעת \u0003רב אשי דשרי\u0004 \u0005[שהתיר],\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003אין צולין בשר, בצל, וביצה\u0004 בערב שבת \u0003אלא\u0004 אם כן יש זמן מספיק \u0003כדי שיצולו מבעוד יום,\u0004 והרי שאין מניחים בערב שבת בתנור בשר שעדיין אינו צלוי דיו! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר ב\u0003בישרא אגומרי\u0004 \u0005[בשר\u0006 העשוי \u0005על גחלים],\u0006 וקיים אז חשש רב יותר שיבוא לחתות בגחלים. \u0003אמר רבינא: האי קרא חייא\u0004 \u0005[אותה דלעת חיה,\u0006 לא מבושלת\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005]\u0006 להניחה \u0003בקדירה על גבי האש בערב שבת עם חשיכה.\u0004 וטעם הדבר — \u0003כיון דקשי ליה זיקא, כבשרא דגדיא דמי\u0004 \u0005[שקשה,\u0006 מזיקה \u0005לה הרוח,\u0006 הרי \u0005כבשר גדי\u0006 היא \u0005נחשבת].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא תוספת לדברי המשנה בענין מחלוקת בית שמאי ובית הלל במכירה לגוי בערב שבת. ש\u0003בית שמאי אומרים: לא ימכור אדם\u0004 חפצו \u0003לגוי, ולא ישאילנו, ולא ילונו, ולא יתן לו\u0004 חפץ \u0003במתנה\u0004 בערב שבת \u0003אלא\u0004 תוך \u0003כדי\u0004 הזמן \u0003שיגיע\u0004 הגוי \u0003לביתו\u0004 מבעוד יום. \u0003ובית הלל אומרים:\u0004 מותר לעשות זאת \u0003כדי\u0004 הזמן \u0003שיגיע\u0004 הגוי \u0003לבית הסמוך לחומה\u0004 של המקום אליו הוא הולך. \u0003ר' עקיבא אומר:\u0004 מותר לתת לגוי בערב שבת תוך \u0003כדי\u0004 הזמן \u0003שיצא\u0004 הגוי \u0003מפתח ביתו\u0004 של הישראלי, ומה שיעשה הגוי אחר כך — אינו חשוב. \u0003אמר ר' יוסי בר' יהודה: הן הן דברי ר' עקיבא, הן הן דברי בית הלל.\u0004 אלא \u0003לא בא ר' עקיבא אלא לפרש\u0004 את \u0003דברי בית הלל.\u0004 שהתנא שגרס בדברי בית הלל עד שיגיע לבית הסמוך לחומה, היתה זו מעין שיטת בית שמאי, ובא ר' עקיבא להבהיר את שיטת בית הלל האמיתית.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא מעין עקרון זה במחלוקת אחרת. ש\u0003בית שמאי אומרים: לא ימכור אדם חמצו\u0004 בערב פסח \u0003לגוי, אלא אם כן יודע בו שיכלה\u0004 החמץ \u0003קודם הפסח, דברי בית שמאי. ובית הלל אומרים: כל זמן שמותר לאוכלו\u0004 — \u0003מותר למוכרו,\u0004 ואין עוד אחריות הישראלי על חמץ שנמכר לגוי משעה שנמכר. ו\u0003ר' יהודה אומר:\u0004"],["\u0003כותח הבבלי\u0004 (תבלין שיש בו פירורי לחם שהחמיצו) \u0003וכל מיני כותח אסור למכור\u0004 לגוי \u0003שלשים יום קודם הפסח.\u0004 שמאחר שהכותח משמש כתבלין בלבד, משאירים אותו זמן רב יותר מאשר מאכלים אחרים.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא אחרת: מלכתחילה \u0003נותנין מזונות לפני הכלב בחצר\u0004 בשבת, ואין חוששים שמא יטלם ויוציאם לרשות הרבים. ואם \u0003נטלו\u0004 הכלב \u0003ויצא\u0004 מחוץ לחצר — \u0003אין נזקקין לו,\u0004 שאין צריך לדאוג שיאכלם הכלב דווקא באותה חצר.","ו\u0003כיוצא בו\u0004 אמרו: \u0003נותנין מזונות לפני הגוי בחצר\u0004 בשבת. ואם \u0003נטלו\u0004 הגוי \u0003ויצא\u0004 — \u0003אין נזקקין לו.\u0004 ושואלים: \u0003הא תו\u0004 \u0005[זה עוד]\u0006 \u0003למה לי,\u0004 והלא \u0003היינו הך\u0004 \u0005[זהו זה],\u0006 כלומר, הרי משמעות ההלכה זהה גם בכלב וגם בגוי, כי איסורי שבת אינן חלים על שניהם. ומשיבים: יש להבדיל, שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 כי \u0003האי\u0004 \u0005[זה,\u0006 הכלב\u0005]\u0006 הרי החובה לדאוג למזונותיו \u0003רמי עליה\u0004 \u0005[מוטלת עליו],\u0006 על בעל החצר שהוא בעליו, \u0003והאי לא רמי עליה\u0004 \u0005[וזה,\u0006 הגוי מזונותיו \u0005אינם מוטלים עליו],\u0006 על בעל החצר, ואם כן כאשר יש בדבר חשש של חילול שבת היה מקום לומר שלא יתן לו מזונו, ועל כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שגם בגוי מותר.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003לא ישכיר אדם\u0004 את \u0003כליו לגוי בערב שבת,\u0004 שנראה כאילו היהודי מקבל שכר בעד עבודה הנעשית בשבת. ואולם \u0003ב\u0004יום \u0003רביעי וב\u0004יום \u0003חמישי\u0004 — \u0003מותר.\u0004 ו\u0003כיוצא בו, אין משלחין איגרות ביד גוי בערב שבת,\u0004 ואולם \u0003ברביעי ובחמישי\u0004 — \u0003מותר.\u0004 אף על פי כן \u0003אמרו עליו על ר' יוסי הכהן ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שאמרו זאת \u0003על ר' יוסי החסיד שלא נמצא כתב ידו ביד גוי מעולם,\u0004 כדי שלא יזדמן שהגוי יטלטל את מכתבו בשבת.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003אין משלחין איגרת ביד גוי\u0004 ב\u0003ערב שבת, אלא אם כן קוצץ לו דמים,\u0004 כלומר, קובע לו שכר קצוב עבור העברת המכתב. שאז כל מה שעושה הגוי במכתב זה איננו בשליחותו של ישראל, כי אם לשם עצמו, שהרי שכרו קצוב מראש. \u0003בית שמאי אומרים:\u0004 אין מוסרים איגרת בערב שבת לידי גוי אלא כשיש עדיין שיעור זמן \u0003כדי שיגיע\u0004 הגוי \u0003לביתו\u0004 לפני חשיכה. \u0003ובית הלל אומרים: כדי שיגיע לבית הסמוך לחומה\u0004 של העיר אליה נשלח.","ושואלים: \u0003והלא קצץ\u0004 \u0005[קבע]\u0006 מחיר, ומה משנה לנו אם יגיע בערב שבת או ביום השבת? \u0003אמר רב ששת, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003ואם לא קצץ\u0004 את מחיר השליחות — \u0003בית שמאי אומרים:\u0004 אין מוסרים לו את האיגרת אלא אם כן נשאר עד כניסת השבת שיעור זמן \u0003כדי שיגיע\u0004 הגוי \u0003לביתו. ובית הלל\u0004 מגבילים את ההיתר למסור לגוי ו\u0003אומרים:\u0004 שיעור הזמן הוא \u0003עד שיגיע לבית הסמוך לחומה.\u0004","ושואלים: \u0003והאמרת רישא\u0004 \u0005[והרי אמרת בתחילה]\u0006 ש\u0003אין משלחין\u0004 אלא אם כן קצץ? הרי שבלא קציצה אין לשלוח כלל! ומשיבים: \u0003לא קשיא\u0004 אפשר להסביר כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שמותר למסור לגוי איגרת בערב שבת אפילו בלא לקצוץ הרי זה באופן \u0003דקביע בי\u0004 \u0005[כשקבוע בית]\u0006 \u0003דואר במתא\u0004 \u0005[בעיר],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שמותר למסור אפילו בלי לקצוץ, הרי זה באופן ש\u0003לא קביע בי דואר במתא\u0004 \u0005[קבוע בית דואר בעיר].\u0006","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003אין מפליגין בספינה פחות משלשה ימים קודם לשבת,\u0004 שלא ייראה הדבר שעושה הישראלי מלאכה ביום השבת. \u0003במה דברים אמורים\u0004 — כשהפליג \u0003לדבר הרשות, אבל\u0004 אם הפליג \u0003לדבר מצוה\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005].\u0006 אבל גם אז צריך שיהא \u0003פוסק\u0004 (קובע) \u0003עמו,\u0004 עם הגוי המנהיג את הספינה, \u0003על מנת לשבות, ו\u0004אולם אף על פי שפסק עמו — הגוי \u0003אינו שובת, דברי רבי. רבן שמעון בן גמליאל אומר: אינו צריך\u0004 לפסוק. \u0003ו\u0004אולם להפליג בספינה הנוסעת \u0003מצור לצידן,\u0004 שהנסיעה היא נסיעה קצרה בים — \u0003אפילו בערב שבת מותר.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003אין צרין על עיירות של גוים\u0004 במלחמה \u0003פחות משלשה ימים קודם לשבת,\u0004 כדי שלא יצטרכו להתחיל בחילול שבת בהקמת המצור. \u0003ו\u0004אולם \u0003אם\u0004 כבר \u0003התחילו\u0004 במצור פחות משלושה ימים לפני שבת — \u0003אין מפסיקין\u0004 מכל פעולות המלחמה אף בשבת. \u0003וכן היה שמאי אומר:\u0004 ממה שנאמר \u0003\"\u0004ובנית מצור על העיר אשר היא עושה עמך מלחמה \u0003עד רדתה\"\u0004 (דברים כ, כ), למדים כי מאחר ויש לעשות את המצור \"עד רדתה\", יש אם כן להמשיך במצור \u0003אפילו בשבת.\u0004","שנינו במשנה ש\u0003אמר רבן שמעון בן גמליאל: נוהגין היו\u0004 בית רבן גמליאל שלא היו נותנים כלי לבן לכובס גוי אלא שלושה ימים לפני השבת. \u0003תניא\u0004 \u0005[שנינו\u0006 בתוספתא\u0005]\u0006 ש\u0003אמר ר' צדוק: כך היה מנהגו של בית רבן גמליאל, שהיו נותנין כלי לבן לכובס\u0004 גוי \u0003שלשה ימים קודם לשבת ו\u0004כלים \u0003צבועים\u0004 היו נותנים לו \u0003אפילו בערב שבת.\u0004 ומעירים: \u0003ומדבריהם למדנו שהלבנים קשים לכבסן יותר מן הצבועין,\u0004 שבלבן ניכר כל כתם יותר.","ואגב הערה זו מספרים כי \u0003אביי הוה יהיב ליה ההוא מנא דצביעא לקצרא\u0004 \u0005[נתן בגד צבוע לכובס].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי לכובס: \u0003כמה בעית עילויה\u0004 \u0005[אתה רוצה עבורו],\u0006 כדי לכבסו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 הכובס לאביי: \u0003כדחיורא\u0004 \u0005[כמו בשל לבן].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: לא תוכל להטעות אותי בנושא זה, ו\u0003כבר קדמוך רבנן\u0004 \u0005[חכמים],\u0006 שמהברייתא למדנו מה קשה יותר לכביסה. ו\u0003אמר אביי\u0004 בענין זה: \u0003האי מאן דיהיב מנא לקצרא, במשחא ניתיב ליה ובמשחא נשקול מיניה\u0004 \u0005[הנותן בגד לכובס, במידה יתן לו ובמידה יקח ממנו].\u0006 \u0003דאי טפי\u0004 \u0005[שאם\u0006 הוא \u0005ארוך יותר]\u0006 — סימן הוא ש\u0003אפסדיה\u0004 \u0005[הפסידו]\u0006 הכובס בכך \u0003דמתחיה\u0004 \u0005[שמתחו].\u0006 \u0003ואי בציר\u0004 \u0005[ואם\u0006 הוא \u0005קצר יותר]\u0006 — ודאי \u0003אפסדיה\u0004 בכך ש\u0003כווציה\u0004 \u0005[כווצו].\u0006","שנינו במשנה כי \u0003שוין אלו ואלו,\u0004 בית שמאי ובית הלל, \u0003שטוענין\u0004 את קורות בית הבד ועיגולי הגת. ושואלים: \u0003מאי שנא כולהו\u0004 \u0005[במה שונים כולם],\u0006 כל הדברים הכתובים במשנה, ש\u0003גזרו בהו\u0004 \u0005[בהם]\u0006 \u0003בית שמאי, ומאי שנא\u0004 \u0005[ובמה שונים]\u0006 \u0003קורות בית הבד ועיגולי הגת\u0004 ש\u0003לא גזרו\u0004 בהם בית שמאי? ומשיבים: \u0003הנך דאי עביד להו\u0004 \u0005[אותם שאם עושה אותם]\u0006 \u0003בשבת\u0004 הריהו \u0003מיחייב\u0004 \u0005[מתחייב]\u0006 בשל כך \u0003קרבן חטאת\u0004 — \u0003גזרו בהו\u0004 \u0005[בהם]\u0006 \u0003בית שמאי\u0004 שלא יעשו אותם ב\u0003ערב שבת עם חשכה.\u0004 ואולם \u0003קורות בית הבד ועיגולי הגת\u0004 שאפילו \u0003אי עביד להו\u0004 \u0005[אם עושה אותם]\u0006 \u0003בשבת\u0004 הוא \u0003לא מיחייב\u0004 \u0005[מתחייב]\u0006 בכך קרבן \u0003חטאת\u0004 — \u0003לא גזרו\u0004 בית שמאי.","ושואלים: \u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 הסבור \u0003שכל מידי דאתי\u0004 \u0005[שבא]\u0006 \u0003ממילא,\u0004 מעצמו, ולא על ידי פעולה בידיים, \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005]\u0006 בשבת? \u0003אמר ר' יוסי בר חנינא:\u0004 דעת תנא זה, דעת \u0003ר' ישמעאל היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003השום והבוסר\u0004 של ענבים, \u0003ו\u0004כן \u0003המלילות\u0004 של חטים \u0003שרסקן מבעוד יום, ר' ישמעאל אומר: יגמור\u0004 ויטפל בהם \u0003משתחשך.\u0004 שלאחר גמר הריסוק שמים את הדברים הללו תחת משקולת, כדי שהנוזלים ימשיכו לצאת. \u0003ור' עקיבא אומר:\u0004"],["\u0003לא יגמור. ו\u0004אילו האמורא \u0003ר' אלעזר אמר:\u0004 משנתנו כשיטת \u0003ר' אלעזר\u0004 התנא \u0003היא. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003חלות דבש שריסקן בערב שבת ויצאו\u0004 הדבש \u0003מעצמן\u0004 ביום השבת — \u0003אסור\u0004 באכילה, ככל דבר שנעשה בשבת. \u0003ור' אלעזר מתיר.\u0004","ושואלים: \u0003ור' יוסי בר חנינא מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' אלעזר,\u0004 שלכאורה דברי ר' אלעזר במשנה קרובים יותר! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה ר' יוסי \u0005לומר]\u0006 \u0003לך\u0004 כי \u0003התם\u0004 \u0005[שם]\u0006 בחלות דבש \u0003הוא דמעיקרא\u0004 \u0005[שמתחילה]\u0006 הוא \u0003אוכל ולבסוף\u0004 הוא \u0003אוכל,\u0004 שהדבש נחשב כמאכל, ואם כן בחלות הדבש לא היתה סחיטה כלל, שמשמעה הוצאת נוזלים ממאכל. ואולם \u0003הכא מעיקרא\u0004 \u0005[כאן\u0006 במשנה היה הכל \u0005בתחילה]\u0006 \u0003אוכל והשתא\u0004 \u0005[ועכשיו]\u0006 נעשה \u0003משקה,\u0004 והרי זה בכלל סחיטה. \u0003ור' אלעזר אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 כתשובה לטענה זו: \u0003הא שמעינן ליה\u0004 \u0005[הרי שמענו אותו]\u0006 את \u0003ר' אלעזר\u0004 ש\u0003אפילו\u0004 ב\u0003זיתים וענבים\u0004 הוא \u0003נמי שרי\u0004 \u0005[גם כן התיר].\u0006 \u0003דהא כי אתא\u0004 \u0005[שהרי כאשר בא]\u0006 \u0003רב הושעיא מנהרדעא, אתא ואייתי מתניתא בידיה\u0004 \u0005[בא והביא ברייתא בידו],\u0006 שנאמר בה: \u0003זיתים וענבים שריסקן מערב שבת ויצאו\u0004 הנוזלים \u0003מעצמן\u0004 — \u0003אסורין. ר' אלעזר ור' שמעון מתירין.\u0004 ומשיבים כי \u0003ר' יוסי בר חנינא\u0004 את ה\u0003ברייתא לא שמיע ליה\u0004 \u0005[שמע\u0006 ידע\u0005].\u0006","ומצד שני שואלים: \u0003ור' אלעזר מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אמר כר' יוסי בר חנינא\u0004 שמשנתנו כדעת ר' ישמעאל היא? ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך\u0004 ר' אלעזר: וכי \u0003לאו איתמר עלה\u0004 \u0005[לא נאמר עליה]\u0006 ש\u0003אמר רבא בר חנינא אמר ר' יוחנן:\u0004 כאן מדובר \u0003במחוסרין דיכה,\u0004 שכאשר השום והבוסר לא נדוכו כלל במדוך — \u0003דכולי עלמא לא פליגי\u0004 \u0005[הכל מסכימים]\u0006 שאסור להניח אותם באופן שיצאו נוזליהם מעצמם בשבת. \u0003כי פליגי\u0004 \u0005[כאשר נחלקו]\u0006 היה זה באופן שכבר נידוכו כל צרכם ואולם עדיין \u0003מחוסרין\u0004 הם עוד \u0003שחיקה\u0004 יתירה. \u0003והני נמי\u0004 \u0005[ואלה גם כן]\u0006 במשנתנו \u0003כמחוסרין דיכה דמו\u0004 \u0005[נחשבים].\u0006 ומסופר ש\u0003הורה ר' יוסי בר חנינא\u0004 לנהוג למעשה \u0003כ\u0004שיטת \u0003ר' ישמעאל,\u0004 ולהתיר לגמור את הטיפול בהם אף משתחשך.","ומתוך שעסקו בדברים השייכים לבית הבד מביאים עוד דברים אחדים בענין זה: \u0003שמן של בדדין\u0004 (בעלי בית הבד) ו\u0003מחצלות של\u0004 (שמשתמשים בהם) \u0003בדדין\u0004 למלאכתם, \u0003רב אסר\u0004 לטלטלם בשבת משום שהם מוקצים לצורך מסויים, ודבר שהוקצה והונח לשימוש מקצועי אסור לטלטלו בשבת. \u0003ושמואל שרי\u0004 \u0005[התיר],\u0006 שלדעת שמואל אין דין מוקצה שייך ברוב הדברים. ומעין מחלוקת זו נחלקו ב\u0003הני כרכי דזוזי\u0004 \u0005[אותן כריכות,\u0006 מחצלות, העשויות לכסות בהן את המרכולת שמביאים \u0005בספינה],\u0006 ש\u0003רב אסר\u0004 משום מוקצה, \u0003ושמואל שרי\u0004 \u0005[התיר].\u0006 וכן \u0003אמר רב נחמן: עז\u0004 שמגדלים אותה \u0003לחלבה, ורחל\u0004 (כבשה) שמגדלים אותה \u0003לגיזתה, ותרנגולת\u0004 שמגדלים אותה \u0003לביצתה, ותורי דרידיא\u0004 \u0005[ושוורים של חרישה],\u0006 שכל אלה לא הוכנו לצורך אכילה, \u0003ו\u0004כן \u0003תמרי דעיסקא\u0004 \u0005[תמרים\u0006 שהוכנו \u0005לעסק\u0006 מסחר\u0005]\u0006 בכל אלה, \u0003רב אסר\u0004 להשתמש בהם לאכילה, או לשוחטם אף ביום טוב מטעם מוקצה, כיון שאין דעתו מבעוד יום לאכול מהם, שהרי הכינם לצורך אחר. \u0003ושמואל אמר: מותר,\u0004 שלדעתו אין דין מוקצה. ומעירים כי \u0003קמיפלגי בפלוגתא\u0004 \u0005[חלוקים הם במחלוקת]\u0006 התנאים \u0003ר' יהודה ור' שמעון\u0004 בענין מוקצה.","ומסופר: \u0003ההוא תלמידא דאורי\u0004 \u0005[תלמיד אחד הורה]\u0006 \u0003ב\u0004עיר \u0003חרתא דארגיז כר' שמעון\u0004 שמוקצה מותר, ו\u0003שמתיה\u0004 \u0005[החרימו]\u0006 \u0003רב המנונא.\u0004 ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003כר' שמעון סבירא לן\u0004 \u0005[סבורים אנו],\u0006 ופוסקים כדבריו, ומדוע אם כן החרימו? ומשיבים: \u0003באתריה\u0004 \u0005[במקומו]\u0006 של \u0003רב הוה\u0004 \u0005[היה]\u0006 זה, ו\u0003לא איבעי ליה למיעבד הכי\u0004 \u0005[היה צריך לעשות כך].\u0006 שאף שפוסקים להיתר, כיון שהעיר היתה בתחום מרותו של רב — כל שהתיר ברבים שלא כדעת רב, הרי זה כמזלזל בכבודו. בדרך אגב מסופר כי \u0003הני תרי תלמידי\u0004 \u0005[אותם שני\u0006 \u0003תלמידים], חד\u0004 \u0005[אחד]\u0006 היה \u0003מציל\u0004 מן הדליקה \u0003בחד מנא\u0004 \u0005[בכלי אחד],\u0006 \u0003וחד\u0004 \u0005[ואחד]\u0006 היה \u0003מציל בארבע וחמש מאני\u0004 \u0005[כלים].\u0006 שהתירו להציל דברים מפני הדליקה בשבת, ונחלקו אם יש להעדיף טלטול כלי אחד בלבד והליכה פעמים רבות, או להעדיף טלטול כלים רבים ומיעוט בהליכות. \u0003וקמיפלגי בפלוגתא\u0004 \u0005[ונחלקו\u0006 באותה \u0005מחלוקת]\u0006 של \u0003רבה בר זבדא ורב הונא\u0004 שנחלקו אף הם במקום אחר בנושא זה.","במשנה זו נמנו דברים שאין לעשותם בערב שבת, אלא אם כן תיגמר מלאכתם כולה או רובה מבעוד יום. ואמרו: \u0003אין צולין בשר בצל וביצה אלא כדי שיצולו\u0004 דיים \u0003מבעוד יום.\u0004 וכן \u0003אין נותנין פת לתנור\u0004 בערב שבת \u0003עם חשכה, ולא חררה\u0004 (בצק שטוח) \u0003על גבי גחלים, אלא\u0004 אם נותר שיעור זמן \u0003כדי שיקרמו פניה\u0004 של עוגה או לחם זה \u0003מבעוד יום. ר' אליעזר אומר:\u0004 שיעור הזמן הוא \u0003כדי שיקרום\u0004 הקרום \u0003התחתון שלה,\u0004 שהוא נעשה בפחות זמן. ואולם באופן יוצא מן הכלל \u0003משלשלין\u0004 מלכתחילה \u0003את\u0004 קרבן \u0003הפסח בתנור\u0004 בערב שבת \u0003עם חשכה\u0004 באופן שתיגמר צלייתו בשבת אם חל ערב פסח בערב שבת. וכן \u0003מאחיזין\u0004 (מדליקים) מלכתחילה \u0003את האור\u0004 (אש) \u0003במדורת בית המוקד\u0004 במקדש בערב שבת סמוך לחשיכה ומניחים לאש שתתתפשט אחר כך במדורה כולה."],["\u0003ו\u0004אולם \u0003בגבולין,\u0004 כלומר, בכל הארץ מחוץ לתחום המקדש, אין להדליק אש במדורה בערב שבת אלא \u0003כדי שתאחוז האור\u0004 (אש) \u0003ברובו,\u0004 ברוב המדורה, מבעוד יום. \u0003ר' יהודה אומר:\u0004 אם היתה זו מדורה של \u0003פחמין\u0004 — אף בגבולין מותר שתידלק האש בערב שבת עם חשיכה, ואפילו רק \u0003כל שהוא,\u0004 שהפחמים כיון שנדלקו שוב לא יכבו, ואין לחשוש שיבוא לעסוק בהם בשבת.","שנינו במשנה שאין צולים בשר וכו' אלא כדי שיצולו מבעוד יום. ושואלים: \u0003ו\u0004עד \u0003כמה\u0004 צריכים הם להיצלות כדי שייחשבו לצלויים דיים, ומותר יהיה להוסיף מעט להשלים את בישולם אחר כך? \u0003אמר ר' אלעזר אמר רב: כדי שיצולו מבעוד יום כמאכל בן דרוסאי\u0004 שהיה צלוי חלקית. שכיון שהיה בן דרוסאי שודד ונרדף בידי הכל, לא יכול לשהות ולצלות את מאכלו כל צרכו והסתפק בצלייה חלקית. \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 על ידי חכם אחר, ש\u0003אמר רב אסי אמר ר' יוחנן: כל שהוא\u0004 מבושל כבר \u0003כמאכל בן דרוסאי\u0004 בידי ישראל, \u0003אין בו\u0004 עוד \u0003משום בישולי גוים.\u0004 שאם גמר גוי לבשל מאכל זה — מותר באכילה, אף שבדרך כלל אסור לאכול מבישולי גויים. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003חנניה אומר: כל שהוא\u0004 מבושל כבר \u0003כמאכל בן דרוסאי\u0004 — \u0003מותר להשהותו על גבי כירה\u0004 בשבת \u0003ואף על פי ש\u0004כירה זו \u0003אין גרופה\u0004 מן הגחלים \u0003ו\u0004אין \u0003קטומה\u0004 (שלא שמו על הגחלים הלוחשות אפר, קיטמא בארמית,) שבמאכל מבושל במדה זו אין לחשוש שמא יבוא לחתות בגחלים.","שנינו במשנה: \u0003אין נותנין את הפת כו'\u0004 שלר' אליעזר אפשר להניח פת בתנור בערב שבת מבעוד יום בכדי שיעור זמן שיספיק לקרום הצד התחתון שלה. ושואלים: \u0003תחתון\u0004 זה שאמרנו \u0003האיך,\u0004 האם \u0003דגבי\u0004 \u0005[שאצל]\u0006 ה\u0003תנור,\u0004 כלומר, שהוא קרוב אליו יותר, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003תחתון\u0004 שאמרנו הכוונה לזה \u0003דגבי\u0004 \u0005[שאצל]\u0006 \u0003האור\u0004 (אש), שהוא קרוב יותר אליה? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ששנינו בברייתא ש\u0003ר' אליעזר אומר\u0004 במפורש: \u0003כדי שיקרמו פניה המדובקין בתנור.\u0004","שנינו במשנה כי \u0003משלשלין את\u0004 קרבן \u0003הפסח\u0004 בתנור ערב שבת עם חשיכה. ומסבירים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הותר הדבר? — \u0003משום\u0004 ש\u0003בני חבורה\u0004 העוסקים בפסח \u0003זריזין הן\u0004 ומדקדקים במצוה ולא יבואו לעבור על דיני שבת. ושואלים: \u0003הא לאו הכי\u0004 \u0005[הרי אם לא כך]\u0006 \u0003לא\u0004 היתה רשות בידם לעשות כן?! \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003גדיא\u0004 \u0005[\u0006בשר \u0005גדי]\u0006 \u0003בין\u0004 היתה שפת התנור \u0003שריק\u0004 \u0005[סתומה\u0006 בטיח\u0005]\u0006 \u0003בין לא\u0004 היתה שפת התנור \u0003שריק\u0004 \u0005[סתומה\u0006 בטיח\u0005]\u0006 — \u0003שפיר דמי\u0004 \u0005[יפה נחשב,\u0006 מותר\u0005],\u0006 כי הוצאתו מן התנור מזיקה לו ואין בו חשש. ואם כן, בבשר קרבן הפסח שהוא בהכרח גדי או טלה (שמות יב, ה) אין לחשוש בכל מקרה! ומשיבים: בכל זאת יש צורך להדגיש טעם זה, שכן \u0003התם\u0004 \u0005[שם]\u0006 שהותר, הרי זה דווקא באופן שהיה \u0003הגדי מינתח\u0004 \u0005[מנותח],\u0006 ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בקרבן פסח, הלא הגדי \u0003לא מינתח\u0004 \u0005[מנותח]\u0006 אלא ניצלה כדיני הפסח בשלמותו, ומכיון שכן גם אינו ניצלה מהר, ויש מקום לחשוש לחתיה בגחלים להחשת הצליה, אך משום שבני חבורה זריזים הם — התירו.","שנינו במשנה ש\u0003מאחיזין את האור\u0004 (אש) במדורת בית המוקד במקדש בערב שבת סמוך לחשיכה ומניחים לאש שתתתפשט אחר כך במדורה כולה. ושואלים: \u0003מנא הני מילי\u0004 \u0005[מנין הדברים הללו]\u0006 שמותר הדבר? \u0003אמר רב הונא:\u0004 שכן נאמר: \u0003\"לא תבערו אש בכל משבתיכם\u0004 ביום השבת\u0003\"\u0004 (שמות לה, ג), ולומדים מכאן: \u0003\"בכל משבתיכם\"\u0004 שהם מגורי כל ישראל — \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מבעיר אש, אבל אתה מבעיר אש\u0004 בשבת \u0003במדורת בית המוקד\u0004 השייכת למקדש. \u0003מתקיף\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: אי הכי\u0004 \u0005[אם כך]\u0006 שמותרת הבערת אש זו בערב שבת עם חשיכה, אם כן \u0003אפילו בשבת\u0004 עצמה \u0003נמי\u0004 \u0005[גם כן]\u0006 יהיה מותר להדליקה, ומדוע מאחיזים את האש מבעוד יום? \u0003אלא אמר רב חסדא,\u0004 כך יש להבין את הדברים: \u0003קרא כי אתא\u0004 \u0005[כאשר בא הפסוק]\u0006 הרי \u0003למישרי\u0004 \u0005[להתיר]\u0006 את שריפת ה\u0003אברים ופדרים\u0004 של הקרבנות על גבי המזבח אפילו בשבת \u0003הוא דאתא\u0004 \u0005[שבא\u0006\u0005],\u0006 ואילו מדורת בית המוקד לא הותר להדליקה בשבת עצמה, כיון שאינה חלק מעבודת הקודש, אלא רק לתועלת הכהנים. ומה שלא חששו בהדלקתה בערב שבת עם חשיכה — הרי זה משום שה\u0003כהנים זריזין הן\u0004 וזהירים במצוות, ובוודאי לא יבואו לחתות בגחלים.","שנינו במשנה כי \u0003בגבולין\u0004 אין מדליקים מדורה בערב שבת עם חשיכה אלא אם יש מספיק זמן לפני כניסת השבת \u0003כדי שתאחוז\u0004 האש ברובן. ועל כך שואלים: \u0003מאי\u0004 \u0005[מה\u0006 הוא\u0005]\u0006 בדיוק \u0003רובן? אמר רב: רוב כל אחד ואחד\u0004 מן העצים. \u0003ושמואל אמר:\u0004 די שיידלקו בשיעור כזה \u0003כדי שלא יאמרו \"הבא עצים\u0004 דקים יותר ונוחים יותר לבעירה \u0003ונניח תחתיהם\"\u0004 לסייע בהבערת העצים הקיימים. \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003רב חייא\u0004 ברייתא שיש בה כדי \u0003לסיועיה\u0004 \u0005[לסייע לו]\u0006 \u0003לשמואל,\u0004 מדין שנאמר במנורת המקדש שאמרו שיש להדליקה \u0003כדי שתהא שלהבת עולה מאיליה ולא שתהא שלהבת עולה על ידי דבר אחר.\u0004 הרי שבמקום שדרושה הדלקה די בכך (תוספות).","עד כאן דובר במדורה, ואולם שואלים: מה דינו של \u0003עץ יחידי\u0004 שמדליקים בערב שבת? \u0003רב אמר:\u0004 צריך להדליק מבעוד יום השבת את \u0003רוב עביו\u0004 של העץ. \u0003ואמרי לה\u0004 \u0005[ויש אומרים אותה\u0006 הלכה\u0005]\u0006 בשם רב: צריך להדליק מבעוד יום השבת את \u0003רוב היקפו\u0004 של העץ. \u0003אמר רב פפא:\u0004 מאחר ויש חילוקי דעות בענין ההלכה שאמר רב, ואין אנו יודעים מה בדיוק אמר, \u0003הלכך בעינן\u0004 \u0005[לכן צריכים אנו]\u0006 להדליק את \u0003רוב עביו, ובעינן\u0004 \u0005[וצריכים אנו]\u0006 להדליק גם את \u0003רוב היקפו,\u0004 שאז אנו יוצאים מידי ספק. ומעירים: בעיה זו היא \u0003כתנאי\u0004 \u0005[כמחלוקת תנאים]\u0006 שנחלקו בענין אחר. ששנינו ש\u0003ר' חייא אמר:\u0004 הדלקת האש היא \u0003כדי שישחת העץ מ\u0004כדי אפשרות שיעשו בו \u0003מלאכת האומן, ור' יהודה בן בתירא אומר: כדי שתאחז האש משני צדדין.\u0004 והוסיף: \u0003ואף על פי שאין ראיה לדבר\u0004 שזו נקראת בעירה לענין שבת, מכל מקום יש \u0003זכר לדבר\u0004 שעץ כזה נקרא שרוף, שנאמר: \"\u0003הנה לאש ניתן לאכלה את שני קצותיו אכלה האש ותוכו נחר היצלח למלאכה\u0004\" \u0005(יחזקאל טו, ד)\u0006.","מאחר שדובר בענין זה, מביאים פסוק אחר הדן בהבערת האש. שמסופר על המלך יהויקים \u0003\"והאח לפניו מבערת\"\u0004 (ירמיה לו כב). ובשאלה \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003אח\u0004 זו נחלקו אמוראים. \u0003רב\u0004 אמר שהכוונה היא ל\u0003אחוונא\u0004 \u0005[עץ ערבה].\u0006 \u0003ושמואל אמר:\u0004 מדובר כאן ב\u0003עצים שנדלקו באחוונא,\u0004 כלומר, באחווה, שכל העצים נדלקים זה מזה, ואף הקטן מן הגדול\u0003.\u0004 אף פירוש המלה \"אחוונא\" נשתכח, ומסופר, \u0003ההוא\u0004 \u0005[אדם אחד]\u0006 ש\u0003אמר להו\u0004 \u0005[להם]\u0006 לאנשים בשוק: \u0003מאן בעי\u0004 \u0005[מי רוצה]\u0006 \u0003אחוונא? אישתכח ערבתא\u0004 \u0005[\u0006ו\u0005נמצא\u0006 שמכר \u0005ערבה],\u0006 והובן פירושה של המלה.","\u0003אמר רב הונא: קנים\u0004 שמדליק בהם מדורה בערב שבת \u0003אין צריכין\u0004 שיידלקו \u0003רוב\u0004 הקנים לפני כניסת השבת, לפי שהם נדלקים היטב. ואולם אם \u0003אגדן\u0004 — נעשו הקנים כקורת עץ ו\u0003צריך\u0004 להדליק את \u0003הרוב.\u0004 וכן \u0003גרעינין\u0004 של תמר שמדליק בהם \u0003אין צריכין רוב,\u0004 שהם בוערים בקלות. ואולם אם \u0003נתנן בחותלות\u0004 (סלים קלועים) \u0003צריכין\u0004 שיידלק ה\u0003רוב. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב חסדא: אדרבא, איפכא מסתברא\u0004 \u0005[ההיפך מסתבר]\u0006 לומר, שכן \u0003קנים\u0004 — \u0003מבדרן\u0004 \u0005[מפוזרים],\u0006 ואילו כאשר \u0003אגדן\u0004 — \u0003לא מבדרן\u0004 \u0005[אינם מפוזרים],\u0006 ולכן קנים אגודים בוערים טוב יותר מאשר קנים בודדים. וכן, \u0003גרעינין\u0004 — \u0003מבדרן\u0004 \u0005[מפוזרים],\u0006 ואם \u0003נתנן בחותלות\u0004 — \u0003לא מבדרן\u0004 \u0005[אינם מפוזרים].\u0006 \u0003איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 מעין דברים אלה,"],["ש\u0003אמר רב כהנא: קנים שאגדן\u0004 — \u0003צריכין\u0004 שיידלק ה\u0003רוב, לא אגדן\u0004 — \u0003אין צריכין\u0004 שיידלק ה\u0003רוב,\u0004 כדברי רב הונא. ואולם \u0003גרעינין\u0004 — \u0003צריכין\u0004 שיידלק ה\u0003רוב,\u0004 ואם \u0003נתנן בחותלות\u0004 — שוב \u0003אין צריכין\u0004 שיידלק ה\u0003רוב.\u0004","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רב יוסף: ארבע מדורות אין צריכין\u0004 שיידלק ה\u0003רוב,\u0004 שכן חומריהן בוערים יפה אם אך נאחזה בהם האש. והן: מדורה \u0003של זפת, ושל גפרית, ושל גבינה\u0004 יבשה \u0003ושל רבב\u0004 (דברים שמנים). \u0003במתניתא תנא\u0004 \u0005[בברייתא שנו]\u0006 עוד: \u0003אף\u0004 מדורה \u0003של קש ושל גבבא\u0004 (לקט עצים הנאספים מן השדה) אין צריך שיידלק הרוב. \u0003אמר ר' יוחנן: עצים של בבל אין צריכין רוב. מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003רב יוסף\u0004 הבבלי: \u0003מאי היא\u0004 \u0005[מה הוא]?\u0006 מה הם העצים שנוהגים להשתמש בהם בבבל שבעירתם טובה כל כך? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהם \u0003סילתי\u0004 \u0005[קיסמים דקים]\u0006 שהשתמשו בהם להבערה ולמאור — \u0003השתא\u0004 \u0005[עכשיו]\u0006 יודעים אנו שעל \u0003פתילה אמר עולא\u0004 ש\u0003המדליק\u0004 אותה לנר שבת \u0003צריך שידליק ברוב היוצא\u0004 מן הכלי, ואם כן \u0003סילתי מבעיא\u0004 \u0005[קיסמים דקים צריך\u0006 לומר\u0005]\u0006 שיש להדליקם ברובם? \u0003אלא אמר רב יוסף:\u0004 וודאי נתכוון ל\u0003שוכא דארזא\u0004 \u0005[ענף של\u0006 עץ \u0005ארז].\u0006 ו\u0003רמי בר אבא אמר:\u0004 המדובר כאן הוא ב\u0003זאזא\u0004 \u0005[אזוב].\u0006","","","במשנה זו מופיעה רשימה של חמרי הבעירה והפתילות שאין להשתמש בהם בהדלקת הנרות בשבת. אם משום שאפשר להכשל על ידם בעבירה, אם משום שאינם ראוים לכבוד השבת. כיון שסתם נר שמדובר בו הריהו כלי המכיל שמן ובתוכו פתילה, מבואר בתחילה מה הם החומרים שאין עושים מהם פתילות לנר שבת, ואחר כך רשימה אחרת של חומרים שאין משתמשים בהם כשמן בנרות אלה. \u0003במה מדליקין\u0004 נרות שבת, \u0003ובמה אין מדליקין?\u0004 לענין סוגי הפתילות אמרו \u0003כי אין מדליקין לא בלכש, ולא בחוסן, ולא בכלך, ולא בפתילת האידן, ולא בפתילת המדבר, ולא בירוקה שעל פני המים.\u0004 ולענין סוגי השמנים אמרו כי אין מדליקים \u0003לא בזפת, ולא בשעוה, ולא בשמן קיק, ולא בשמן שריפה, ולא באליה, ולא בחלב. נחום המדי אומר: מדליקין בחלב מבושל. וחכמים אומרים: אחד\u0004 חלב \u0003מבושל ואחד שאינו מבושל אין מדליקין בו.\u0004","רוב המילים והמושגים המוזכרים במשנה לא היו מובנים בבבל והם תורגמו ובוארו. שנינו במשנה שאין מדליקים בלכש. ומסבירים כי \u0003לכש\u0004 הוא \u0003שוכא דארזא\u0004 \u0005[ענף הארז].\u0006 ושואלים: הלא \u0003שוכא דארזא\u0004 \u0005[עץ ארז]\u0006 \u0003עץ בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא!\u0004 וכיצד יתכן לעשות ממנו פתילה? ומשיבים: מדובר כאן \u0003בעמרניתא דאית ביה\u0004 \u0005[בכעין צמר שיש בו],\u0006 מתחת לקליפתו.","עוד שנינו במשנה כי \u0003לא\u0004 מדליקים \u0003בחוסן. אמר רב יוסף:\u0004 החוסן הוא \u0003נעורת\u0004 (החלקים הדקים הנופלים מאניצים) \u0003של פשתן. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"והיה החסון לנעורת\"\u0004 (ישעיה א, לא), ו\u0003מכלל\u0004 הדברים אתה למד כי \u0003חוסן לאו\u0004 \u0005[לא]\u0006 \u0003נעורת הוא! אלא אמר אביי:\u0004 החוסן הוא \u0003כיתנא דדייק\u0004 \u0005[פשתן ש\u0006כבר \u0005דכו]\u0006 את גבעוליה \u0003ו\u0004עדיין \u0003לא נפיץ\u0004 \u0005[נפצום],\u0006 והחוטים המצויים בגבעול מכוסים עוד בקליפה ולכך אינם בוערים יפה. עוד שנינו במשנה כי \u0003לא\u0004 מדליקים \u0003בכלך. אמר שמואל: שאלתינהו\u0004 \u0005[שאלתי אותם]\u0006 את \u0003כל נחותי ימא\u0004 \u0005[יורדי הים]\u0006 \u0003ואמרי\u0004 \u0005[ואמרו]\u0006 \u0003לי\u0004 שכלך האמור במשנה \u0003כולכא שמיה\u0004 \u0005[שמו]\u0006 היום. \u0003רב יצחק בר זעירא אמר:\u0004 כלך הוא \u0003גושקרא\u0004 \u0005[פקעת של תולעת משי].\u0006","","ומסופר כי \u0003רבין ואביי הוו יתבי קמיה\u0004 \u0005[היו יושבים לפני]\u0006 \u0003רבנא נחמיה אחוה דריש גלותא\u0004 \u0005[אחיו של ראש הגולה].\u0006 \u0003חזייה דהוה לביש מטכסא\u0004 \u0005[ראה אותו\u0006 רבין את ר' נחמיה \u0005שהוא לבוש סוג משי].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין לאביי: היינו\u0004 \u0005[זהו]\u0006 ה\u0003כלך דתנן\u0004 \u0005[ששנינו\u0006 במשנתנו\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: \u0003אנן\u0004 \u0005[אנחנו]\u0006 \u0003\"שירא פרנדא\" קרינן ליה\u0004 \u0005[קוראים אנו לו].\u0006","\u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנינו: \u0003השיראים והכלך והסיריקין\u0004 (סוג משי) \u0003חייבין\u0004 כולם \u0003בציצית,\u0004 והרי שהשיראים והכלך הם מינים שונים, ואם כן הרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על \u0003רבין\u0004 שקרא כלך לשירא פרנדא! ומעירים: אכן, \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 היא. \u0003איבעית אימא\u0004 \u0005[אם תרצה אמור],\u0006 ותתרץ כי \u0003שירא לחוד, ושירא פרנדא לחוד.\u0004 ושירא פרנדא הוא המין הזהה לכלך.","","","","עוד שנינו במשנה כי \u0003לא\u0004 מדליקים \u0003בפתילת האידן.\u0004 ומסבירים כי פתילת האידן היא \u0003אחוינא\u0004 \u0005[ערבה],\u0006 ובעירתה \u0005אינה יפה.\u0006 ומסופר כי \u0003רבין ואביי הוו קאזלי בפקתא\u0004 \u0005[היו הולכים\u0006 \u0003בבקעת] טמרוריתא. חזינהו להנהו ארבתא\u0004 \u0005[ראו את אותם ערבות].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבין לאביי: היינו\u0004 \u0005[זהו]\u0006 ה\u0003אידן דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אביי: הרי \u0003האי\u0004 \u0005[זה]\u0006 \u0003עץ בעלמא\u0004 \u0005[סתם]\u0006 \u0003הוא!\u0004 וכיצד עושים ממנו פתילה? \u0003קלף\u0004 רבין את הערבה \u0003ואחוי ליה עמרניתא דביני ביני\u0004 \u0005[והראה לו\u0006 מעין \u0005הצמר שביניהם],\u0006 כלומר, בין הקליפה לעץ. שנינו במשנה כי \u0003לא\u0004 מדליקים \u0003בפתילת המדבר.\u0004 ומסבירים כי \u0003פתילת המדבר היא שברא,\u0004 שהוא מין עשב ארוך שבעירתו אינה יפה. עוד שנינו במשנה כי \u0003לא\u0004 משתמשים כפתילה להדלקת נרות שבת \u0003בירוקה שעל\u0004 פני המים. ושואלים \u0003מאי\u0004 \u0005[מה]\u0006 \u0003היא\u0004 ירוקה זו? \u0003אילימא אוכמתא דחריצי\u0004 \u0005[אם תאמר\u0006 שהיא \u0005הירוקת שעל תעלות\u0006 המים\u0005]?\u0006 והלא ירוקת זו \u0003איפרוכי מפרכן\u0004 \u0005[נפרכת היא]\u0006 ואי אפשר לטוות ממנה פתיל. \u0003אלא אמר רב פפא:\u0004 המדובר הוא ב\u0003אוכמתא דארבא\u0004 \u0005[ירוקת\u0006 המצטברת \u0005על הספינה]\u0006 שהיא גמישה יותר, ואפשר לעשות ממנה פתילה כשהיא מתייבשת. \u0003תנא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הוסיפו עליהן,\u0004 על הפתילות האסורות בהדלקה ששנינו במשנה גם את \u0003של צמר ושל שער.\u0004 ומעירים: \u0003ו\u0004ה\u0003תנא דידן\u0004 \u0005[שלנו]\u0006 במשנה לא מנה את אלה כיון שלא מצא צורך בכך, כי כמעט בלתי אפשרי הוא לעשות פתילות מחמרים אלה, שכן ה\u0003צמר\u0004 הבוער \u0003מכווץ כוויץ\u0004 \u0005[מתכווץ],\u0006 וה\u0003שער\u0004 רק \u0003איחרוכי מיחרך\u0004 \u0005[נחרך],\u0006 ולפיכך אינם יכולים להגיע לשימוש כפתילות. שנינו במשנה ש\u0003לא\u0004 משתמשים כשמן להדלקת הנרות \u0003בזפת\u0004 ולא בשעוה. ומסבירים כי זפת הוא \u0003זיפתא,\u0004 ו\u0003שעוה\u0004 היא \u0003קירותא. תנא\u0004 \u0005[שנינו\u0006 ברייתא\u0005]:\u0006 \u0003עד כאן\u0004 (עד הזפת ברשימה) דובר ב\u0003פסול\u0004 החומרים שאינם ראויים להיעשות \u0003פתילות,\u0004 ו\u0003מכאן ואילך\u0004 מדובר ב\u0003פסול\u0004 חמרים שאינם ראויים להיות \u0003שמנים.\u0004 על כך שואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמזפת וכיוצא בה אי אפשר לעשות פתילה! ומשיבים: בענין ה\u0003שעוה איצטריכא ליה\u0004 \u0005[הוצרך לו]\u0006 לומר. שכן \u0003מהו דתימא\u0004 \u0005[שתאמר]\u0006 שכציפוי \u0003לפתילות,\u0004 כדרך שעושים כרגיל נרות \u0003נמי לא חזיא\u0004 \u0005[גם כן אינה ראויה],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שאף שהשעוה אינה יפה כשמן, אבל כציפוי לפתילה ראויה היא.","\u0003אמר רמי בר אבין: עטרנא פסולתא דזיפתא\u0004 \u0005[העיטרן\u0006 הוא \u0005פסולת הזפת],\u0006 שכאשר מבעירים עצים להוציא מהם זפת זבה אחר הזפת תמצית בהירה יותר, והיא העיטרן. וכן \u0003שעוה\u0004 היא \u0003פסולתא דדובשא\u0004 \u0005[פסולת הדבש].\u0006"],["\u0003למאי נפקא מינה\u0004 \u0005[ומה יוצא מזה]\u0006 ממה שלימדנו רמי בר אבין? ומסבירים: יש לכך משמעות \u0003ל\u0004גבי \u0003מקח וממכר.\u0004 שהקונה עיטרן יכול לעמוד על כך שתהיה זו פסולת הזפת ולא חומר אחר, וכן בקונה שעוה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בתוספתא: \u0003כל אלו\u0004 החומרים \u0003שאמרו\u0004 לאסור אותם הרי זה רק לענין ש\u0003אין מדליקין בהן\u0004 נרות ל\u0003שבת, אבל עושין מהן\u0004 לכתחילה \u0003מדורה, בין\u0004 כדי \u0003להתחמם כנגדה\u0004 ו\u0003בין להשתמש לאורה, בין על גבי קרקע, בין על גבי כירה. ולא אסרו\u0004 את החמרים הללו \u0003אלא\u0004 כאשר רוצה \u0003לעשות מהן פתילה לנר בלבד.\u0004","שנינו במשנה כי \u0003לא\u0004 מדליקים נרות שבת \u0003בשמן קיק.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003שמן קיק\u0004 זה? \u0003אמר שמואל: שאילתינהו\u0004 \u0005[שאלתי אותם]\u0006 את \u0003כל נחותי ימא\u0004 \u0005[יורדי הים],\u0006 \u0003ואמרו לי: עוף אחד יש בכרכי הים ו\"קיק\" שמו,\u0004 ומשמנו עושים את שמן הקיק. \u0003רב יצחק בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהודה אמר:\u0004 המדובר הוא ב\u0003משחא דקאזא\u0004 \u0005[שמן כותנה].\u0006 \u0003ריש לקיש אמר:\u0004 הוא שמן שנעשה מן הקיקיון, כעין \u0003קיקיון\u0004 של \u0003יונה.\u0004 ו\u0003אמר רבה בר בר חנה: לדידי חזי לי\u0004 \u0005[אני ראיתי]\u0006 את מין ה\u0003קיקיון\u0004 של \u0003יונה ול\u0004עץ \u0003צלוליבא דמי\u0004 \u0005[\u0006הוא \u0005דומה]\u0006 \u0003ומדפשקי רבי\u0004 \u0005[וגדל על יד תעלות מים],\u0006 \u0003ועל פום חנותא מדלן יתיה\u0004 \u0005[פתחי החנויות\u0006 \u0003מדלים אותו], ומפרצידוהי עבדי משחא\u0004 \u0005[ומגרעיניו עושים שמן],\u0006 \u0003ובענפוהי נייחן כל בריחי דמערבא\u0004 \u0005[ו\u0006תחת \u0005ענפיו נחים כל חולי ארץ ישראל].\u0006","\u0003אמר רבה:\u0004 אותן \u0003פתילות שאמרו חכמים\u0004 ש\u0003אין מדליקין בהן בשבת,\u0004 טעמו של דבר: \u0003מפני שהאור מסכסכת בהן,\u0004 שאין האש דולקת יפה, אלא מקפצת על גבי הפתילה. ואותם \u0003שמנים שאמרו חכמים\u0004 ש\u0003אין מדליקין בהן\u0004 בשבת, טעמו של דבר: \u0003מפני שאין נמשכין\u0004 כראוי \u0003אחר הפתילה.\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003אביי מרבה:\u0004 אותם \u0003שמנים שאמרו חכמים\u0004 ש\u0003אין מדליקין בהן בשבת, מהו\u0004 דינם לענין \u0003שיתן לתוכן שמן\u0004 הכשר להדלקה מלכתחילה \u0003כל שהוא וידליק\u0004 בתערובת? וצדדי השאלה: \u0003מי גזרינן דילמא אתי לאדלוקי בעינייהו\u0004 \u0005[האם גוזרים אנו שמא יבוא להדליק\u0006 שמנים אלה \u0005בעינם],\u0006 בלא תוספת שמן כשר, \u0003או לא\u0004 חוששים בכגון זה? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003אין מדליקין. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003לפי שאין מדליקין,\u0004 כלומר, כך היא ההלכה שגם בתערובת אין מדליקים (ערוך).","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 אביי לרבה ממה ששנינו בתוספתא: \u0003כרך דבר שמדליקין בו על גבי דבר שאין מדליקין בו\u0004 — \u0003אין מדליקין בו. אמר רבן שמעון בן גמליאל: של בית אבא היו כורכין פתילה\u0004 שמדליקים בה \u0003על גבי אגוז ו\u0004כך היו \u0003מדליקין. וקתני מיהת\u0004 \u0005[ושנינו בכל אופן]\u0006 כי \u0003מדליקין,\u0004 והרי שמותר להדליק כשמצרפים פתילה מותרת ואסורה!","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבה: \u0003אדמותבת\u0004 \u0005[עד שאתה מקשה]\u0006 \u0003לי מ\u0004דברי \u0003רבן שמעון בן גמליאל, סייעינהו\u0004 \u0005[סייע לנו,\u0006 לדברינו\u0005]\u0006 \u0003מ\u0004דברי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שאסר להדליק בכגון זה! ומשיבים: \u0003הא לא קשיא\u0004 \u0005[זו אינה קשה],\u0006 שעדיף להקשות כאן מדברי רבן שמעון בן גמליאל אודות מנהג בית אביו בענין זה משום הכלל \u0003\"מעשה רב\".\u0004 כי גדול כוח ההוכחה שמביאים מדבר שנהגו בו למעשה, מהלכה מופשטת בלבד, שאולי אף אומרה לא התכוון לבצעה הלכה למעשה. \u0003מכל מקום\u0004 עדיין \u0003קשיא\u0004 \u0005[קשה]\u0006 מדברי רבן שמעון בן גמליאל, שהרי \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן לענין \u0003להדליק\u0004 את הפתילה עם האגוז? ואם כן הרי שמותר הדבר! על כך משיבים: \u0003לא,\u0004 המדובר הוא \u0003להקפות,\u0004 כלומר לסייע שהפתילה תצוף על גבי השמן בעזרת האגוז. על כך שואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר רק לענין \u0003להקפות\u0004 את הפתילה, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 שאוסר? ומשיבים: המשנה \u0003כולה\u0004 דעת \u0003רבן שמעון בן גמליאל היא, וחסורי מיחסרא, והכי קתני\u0004 \u0005[וחסרה היא וכך יש לשנותה]:\u0006 \u0003כרך דבר שמדליקין בו על גבי דבר שאין מדליקין בו\u0004 — \u0003אין מדליקין בו. במה דברים אמורים\u0004 — \u0003להדליק\u0004 בשניהם, \u0003אבל\u0004 אם השתמש בדבר שאין מדליקים בו \u0003להקפות\u0004 בלבד — \u0003מותר,\u0004 ששנינו \u0003שרבן שמעון בן גמליאל אומר: של בית אבא היו כורכין פתילה על גבי\u0004 אגוז. בכל אופן סוכם עד כה כי אסור להדליק בתערובת של שמן מותר ושמן אסור.","ושואלים: \u0003איני\u0004 \u0005[\u0006וכי \u0005כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב ברונא אמר רב: חלב מהותך\u0004 (מותך) או \u0003קרבי דגים שנמוחו\u0004 (נמעכו, נמסו) ונעשו כשמן, \u0003אדם נותן לתוכן שמן\u0004 הראוי להדלקה \u0003כל שהוא ומדליק\u0004 בהם. והרי שמדליקים בתערובת שמן מותר ושמן אסור? על כך משיב רבה: \u0003הני מימשכי בעינייהו, והני לא מימשכי בעינייהו\u0004 \u0005[אלה,\u0006 החלב וקרבי הדגים, \u0005נמשכים\u0006 בפתילה אף \u0005בעינם, ואלה,\u0006 השמנים שנאסרו, \u0005אינם נמשכים בעינם].\u0006 כי מתחילה אסרו את החלב המהותך כיון ש\u0003גזרו רבנן\u0004 \u0005[חכמים]\u0006 \u0003על חלב מהותך משום חלב שאינו מהותך, ועל קרבי דגים שנמוחו משום קרבי דגים שלא נמוחו,\u0004 ואולם אם הוסיף לתוכם שמן כלשהו הראוי להדלקה התירם. ושואלים: אם גזירה היא, אם כן \u0003וליגזור נמי\u0004 \u0005[ושיגזור גם כן]\u0006 \u0003חלב מהותך ו\u0004כן \u0003קרבי דגים שנמוחו שנתן לתוכן שמן משום חלב מהותך וקרבי דגים שנמוחו שלא נתן לתוכן שמן\u0004 ראוי! ודוחים: \u0003היא גופא\u0004 \u0005[עצמה],\u0006 חלב מותך וקרבי דגים שנימוחו הלא איסורם רק משום \u0003גזירה, ואנן ניקום\u0004 \u0005[ואנו נעמוד]\u0006 \u0003וניגזור גזירה\u0004 אחת על \u0003גזירה\u0004 אחרת?! ולכן אין סיבה לאוסרם.","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003רמי בר חמא\u0004 ברייתא: אותם \u0003פתילות ושמנים שאמרו חכמים\u0004 ש\u0003אין מדליקין בהן בשבת\u0004 — \u0003אין מדליקין\u0004 בהם אף \u0003במקדש, משום שנאמר\u0004 במנורת המקדש: \u0003\"\u0004ואתה תצוה את בני ישראל ויקחו אליך שמן זית זך כתית למאור \u0003להעלות נר תמיד\"\u0004 (שמות כז, כ). \u0003הוא\u0004 רמי בר חמא \u0003תני לה\u0004 \u0005[שנה אותה]\u0006 ברייתא, \u0003והוא\u0004 גם \u0003אמר לה\u0004 \u0005[אותה],\u0006 כלומר, את פירושה; מה היא הראייה מן הכתוב — שיש בדרש הכתוב \u0003כדי\u0004 לחייב \u0003שתהא שלהבת\u0004 הנר \u0003עולה מאיליה, ולא שתהא עולה על ידי דבר אחר,\u0004 על ידי תיקון והטייה של הפתילה מאוחר יותר.","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003מבלאי מכנסי\u0004 ה\u0003כהנים ומהמיניהם\u0004 (חגורותיהם) \u0003היו מפקיעין\u0004 (מתירים חוטים) לעשות מהם פתילות, \u0003ומהן,\u0004 מאותן פתילות, היו \u0003מדליקין\u0004 ב\u0003שמחת בית השואבה.\u0004 ומאחר שבאבנטים היה גם צמר, שהרי נאמר שהיו עשויים בין השאר מתכלת, ותכלת האמור במקרא הוא צמר צבוע, והרי שמדליקים בדבר שיש בו תערובת פתיל שאינו ראוי לדלוק! ומשיבים: \u0003שמחת בית השואבה שאני\u0004 \u0005[שונה],\u0006 שבשמחה זו לא הדליקו את מנורת המקדש, אלא פנסים מיוחדים שנעשו לצורך זה, ובהם לא הקפידו על סוג הפתילות.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 שאלה על כך ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רבה בר מתנה: בגדי כהונה שבלו מפקיעין אותם\u0004 לחוטים, \u0003ומהן היו עושין פתילות למקדש. מאי לאו\u0004 \u0005[האם לא]\u0006 שהשתמשו גם בבגדים שהם \u0003כלאים,\u0004 וכגון אבנטי הכהנים העשויים צמר ופשתים (כלאיים) יחד! ומשיבים: \u0003לא,\u0004 את הפתילות הללו היו עושים רק מבגדי \u0003בוץ\u0004 (פשתן).","\u0003אמר רב הונא:\u0004 אותן \u0003פתילות ושמנים שאמרו חכמים\u0004 ש\u0003אין מדליקין בהן בשבת, אין מדליקין בהן\u0004 אף לצורך נר \u0003בחנוכה, בין בשבת בין בחול. אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב הונא?\u0004 — \u0003קסבר\u0004 \u0005[הוא סבור]\u0006 שאם \u0003כבתה\u0004 נר חנוכה לאחר שהדליק אותו כראוי, \u0003זקוק לה\u0004 לתקן ולהדליקה מחדש באופן שתבער היטב, ולכן יש לדאוג מראש שתהיה הפתילה בוערת כראוי. \u0003ו\u0004מכיוון שאמר ש\u0003מותר להשתמש לאורה\u0004 של מנורת החנוכה הרי אינו פורש מלהשתמש בה בימות החול, ואם כן כדי שלא יבוא לידי תקלה אף בשבת יש להקפיד מלכתחילה שתבער הפתילה היטב, שמא יבוא לתקן את הנר בשבת. \u0003ורב חסדא אמר:\u0004 אותם שמנים ופתילות שאסרו חכמים להדליקם בשבת \u0003מדליקין בהן\u0004 בחנוכה \u0003ב\u0004ימי ה\u0003חול, אבל לא בשבת. קסבר\u0004 \u0005[סבור הוא]\u0006 שאם \u0003כבתה\u0004 נר החנוכה"],["\u0003אין זקוק לה\u0004 להדליקה, ולכן אין סיבה לדאוג מראש להדלקה בדבר שבוער היטב, שהרי אף אם תכבה אינו צריך לתקן את הדבר. \u0003ו\u0004אולם אף לדעתו \u0003מותר להשתמש לאורה,\u0004 ומכיון שכן בשבת צריך לדאוג שתהא הפתילה בוערת כראוי, שאם לא כן עלול לבוא לידי תקלה ולבוא להטות ולתקן את הנר כדי שיוכל להשתמש בו. דעה שלישית \u0003אמר ר' זירא אמר רב מתנה, ואמרי לה\u0004 \u0005[ויש\u0006 אומרים] ש\u0003אמר\u0004 זאת \u0003ר' זירא אמר רב: פתילות ושמנים שאמרו חכמים\u0004 ש\u0003אין מדליקין בהן בשבת,\u0004 מכל מקום \u0003מדליקין בהן בחנוכה, בין בחול בין בשבת. אמר ר' ירמיה: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב?\u0004 — \u0003קסבר\u0004 \u0005[הוא\u0006 סבור] שאם \u0003כבתה אין זקוק לה\u0004 להדליקה שנית, \u0003ואסור להשתמש לאורה,\u0004 ולכן גם ביום השבת אין לחשוש שמא יבוא לתקן את הפתילה, שהרי ממילא אסור לו להשתמש לאורה.","מסופר כי \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים\u0006 להלכה זו \u0005לפני]\u0006 \u0003אביי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' ירמיה ולא קיבלה,\u0004 שלא החשיב למדי את ר' ירמיה. ואולם \u0003כי אתא\u0004 \u0005כאשר\u0006 \u0003בא] רבין\u0004 מארץ ישראל לבבל \u0003אמרוה רבנן קמיה\u0004 \u0005[חכמים\u0006 להלכה זו \u0005לפני]\u0006 \u0003אביי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' יוחנן וקיבלה.\u0004 ואז \u0003אמר\u0004 אביי בצער: \u0003אי זכאי, גמירתיה לשמעתיה מעיקרא\u0004 \u0005[לו הייתי זוכה, הייתי לומד ההלכה הזאת מתחילה].\u0006 ותוהים: \u0003והא גמרא\u0004 \u0005[והרי למדה]\u0006 וקבלה לבסוף! ומשיבים: \u0003נפקא מינה לגירסא דינקותא\u0004 \u0005[יוצא מכאן,\u0006 הבדל, \u0005לגבי גרסת הילדות],\u0006 שדברים שאדם לומד בצעירותו זוכר הוא יפה יותר.","על שיטה זו ששנינו שאם כבה נר חנוכה אין נזקקים לו להדליקו בשנית, שואלים: \u0003ו\u0004האם אכן כאשר \u0003כבתה\u0004 נר חנוכה \u0003אין זקוק לה? ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 על כך ממה ששנינו בברייתא: \u0003מצותה\u0004 של הדלקת הנר בחנוכה \u0003משתשקע החמה עד שתכלה רגל\u0004 העוברים \u0003מן השוק. מאי לאו דאי\u0004 \u0005[האם לא\u0006 הכוונה היא \u0005שאם]\u0006 \u0003כבתה\u0004 הנר \u0003הדר\u0004 \u0005[חוזר]\u0006 ו\u0003מדליק לה\u0004 \u0005[אותה]\u0006 כדי שתהא בוערת במשך כל הזמן הזה! ומשיבים: \u0003לא,\u0004 את הברייתא אפשר להבין באופנים אחרים; \u0003דאי\u0004 \u0005[שאם]\u0006 עדיין \u0003לא אדליק\u0004 \u0005[הדליק]\u0006 כלל עם שקיעת החמה — \u0003מדליק\u0004 עוד במשך הזמן הזה את נרות החנוכה. \u0003אי נמי\u0004 \u0005[או\u0006 \u0003גם כן]\u0004 יכול אתה לומר כי אמרו זאת לענין \u0003שיעורה\u0004 של ההדלקה, שיש להכין פתילה ושמן המספיקים לבעור במשך זמן זה, אך אם כבה הנר — אין להקפיד על כך.","הוזכר כאן הביטוי \u0003\"עד שתכלה רגל מן השוק\".\u0004 ועל כך שואלים: \u0003ועד כמה\u0004 בדיוק הוא זמן זה? \u0003אמר רבה בר בר חנה אמר ר' יוחנן: עד דכליא ריגלא דתרמודאי\u0004 \u0005[שתכלה הרגל\u0006 של \u0005אנשי תדמור]\u0006 שהיו מוכרים עצים להדלקה, והם היו נשארים בשוק אחרונים כדי שיוכלו הכל לקנות עצים מהם.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003מצות חנוכה\u0004 הריהי מעיקרה הדלקה בכל יום של \u0003נר\u0004 אחד שידליק \u0003איש,\u0004 כלומר, בעל הבית, הוא \u0003וביתו. והמהדרין\u0004 (מקפידים במצוות) מדליקים \u0003נר לכל אחד ואחד\u0004 מבני הבית. \u0003והמהדרין מן המהדרין\u0004 משנים בסדר הנרות מיום ליום. ונחלקו במהות סדר זה בית שמאי ובית הלל. ש\u0003בית שמאי אומרים:\u0004 ב\u0003יום הראשון מדליק שמנה\u0004 נרות, ו\u0003מכאן ואילך פוחת והולך\u0004 במנין הנרות, עד שביום האחרון של חנוכה מדליק רק נר אחד. \u0003ובית הלל אומרים:\u0004 ב\u0003יום\u0004 ה\u0003ראשון מדליק\u0004 נר \u0003אחת,\u0004 ו\u0003מכאן ואילך מוסיף והולך\u0004 עד שביום האחרון מדליק שמונה נרות.","\u0003אמר עולא: פליגי\u0004 \u0005[נחלקו]\u0006 \u0003בה\u0004 בהלכה זו \u0003תרי אמוראי במערבא\u0004 \u0005[שני אמוראים בארץ ישראל],\u0006 והם \u0003ר' יוסי בר אבין ור' יוסי בר זבידא. חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003בית שמאי\u0004 הוא \u0003כנגד ימים הנכנסין,\u0004 כלומר, העתידים לבוא. שביום הראשון, מאחר שיש עוד שמונה ימי חג — מדליקים שמונה נרות, וביום השני שנשארו עוד שבעה ימים — מדליקים שבעה וכן הלאה. \u0003וטעמא\u0004 \u0005[ו\u0006אילו \u0005הטעם]\u0006 של \u0003בית הלל\u0004 הוא \u0003כנגד ימים היוצאין,\u0004 שמדליקים בכל יום כמנין ימי החג שיצאו ועברו כבר. \u0003וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר\u0004 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003בית שמאי\u0004 הוא \u0003כנגד פרי החג,\u0004 הפרים שהקריבו בחג הסוכות, שביום הראשון היו מקריבים שלושה עשר פרים, ובכל יום הפחיתו פר אחד (במדבר כט, יב–לא). \u0003וטעמא\u0004 \u0005[ו\u0006אילו \u0005הטעם]\u0006 של \u0003בית הלל\u0004 הוא ש\u0003מעלין בקדש ואין מורידין,\u0004 ולפיכך אם רוצים לשנות מנין הנרות לפי הימים, ראוי שיוסיפו וילכו במניינם עם עבור הימים.","\u0003אמר רבה בר בר חנה\u0004 ש\u0003אמר ר' יוחנן: שני זקנים היו בצידן,\u0004 ש\u0003אחד\u0004 מהם \u0003עשה כ\u0004שיטת \u0003בית שמאי ואחד\u0004 מהם \u0003עשה כדברי בית הלל\u0004 ונתנו טעם לדבריהם; \u0003זה נותן טעם לדבריו כנגד פרי החג, וזה נותן טעם\u0004 לדבריו משום ש\u0003מעלין בקדש ואין מורידין.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003נר חנוכה מצוה להניחה על פתח ביתו מבחוץ\u0004 כדי שיראו הכל את הנרות. ו\u0003אם היה דר בעלייה\u0004 (קומה גבוהה יותר) — \u0003מניחה בחלון הסמוכה לרשות הרבים. ובשעת הסכנה\u0004 כאשר גזרו איסור על הדלקת נרות — \u0003מניחה על שלחנו ודיו\u0004 בכך.","\u0003אמר רבא: צריך,\u0004 נוסף לנרות החנוכה, עוד \u0003נר אחרת\u0004 כדי \u0003להשתמש לאורה,\u0004 שהרי אסור להשתמש בנרות חנוכה. \u0003ואי איכא\u0004 \u0005[ו\u0006אולם \u0005אם יש]\u0006 \u0003מדורה\u0004 — \u0003לא צריך\u0004 להדליק נר נוסף, שמשתמש הוא באור המדורה. \u0003ו\u0004אולם \u0003אי\u0004 \u0005[אם]\u0006 \u0003אדם חשוב\u0004 הוא, שאינו רגיל להשתמש לאורה של המדורה — \u0003אף על גב דאיכא\u0004 \u0005[אף על פי שיש]\u0006 \u0003מדורה צריך נר אחרת.\u0004","ושואלים: \u0003מאי\u0004 \u0005[מה היא]\u0006 \u0003חנוכה?\u0004 ומה טעם מדליקים בחנוכה נרות דווקא? ומשיבים, \u0003דתנו רבנן\u0004 \u0005[ששנו חכמים]\u0006 במגילת תענית: \u0003בכ\"ה בכסליו יומי\u0004 \u0005[ימי]\u0006 ה\u0003חנוכה תמניא אינון\u0004 \u0005[שמונה הם]\u0006 ש\u0003לא למספד בהון\u0004 \u0005[לספוד בהם]\u0006 \u0003ו\u0004ש\u0003לא להתענות בהון\u0004 \u0005[בהם].\u0006 ומה טעם הדבר? \u0005—\u0006 \u0003שכשנכנסו יוונים להיכל טמאו\u0004 במגעם את \u0003כל השמנים שבהיכל, וכשגברה מלכות בית חשמונאי ונצחום בדקו ולא מצאו אלא פך אחד של שמן שהיה מונח\u0004 סגור \u0003בחותמו של כהן גדול\u0004 ולא פתחוהו היוונים. \u0003ולא היה בו\u0004 שיעור \u0003אלא להדליק יום אחד. נעשה בו נס והדליקו ממנו שמונה ימים. לשנה אחרת קבעום ועשאום ימים טובים ב\u0004אמירת \u0003הלל והודאה\u0004 מיוחדת, בתפילה ובברכות.","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 בענין נזיקין: \u0003גץ\u0004 (ניצוץ) \u0003היוצא מתחת הפטיש\u0004 ש\u0003יצא\u0004 מחוץ למקום מלאכת האומן, \u0003והזיק\u0004 — \u0003חייב\u0004 המכה בפטיש באחריות. וכן \u0003גמל\u0004 שהיה \u0003טעון פשתן והוא עובר ברשות הרבים ונכנסה פשתנו לתוך החנות ודלקה\u0004 (נדלקה) \u0003בנרו של\u0004 ה\u0003חנוני ו\u0004אחר כך \u0003הדליק את הבירה\u0004 (הבנין) — \u0003בעל הגמל חייב,\u0004 שפשתנו נכנס לרשות אחרת שלא היה רשאי להכנס לתוכה, וכל הנזקים שנגרמו מחמת רשלנותו נגרמו. ואולם אם \u0003הניח\u0004 ה\u0003חנוני נרו מבחוץ\u0004 לחנות והדליק את הפשתן — במקרה זה \u0003החנוני חייב,\u0004 שהוא יצא מתחומו.","\u0003ר' יהודה אומר:\u0004 אם נדלק הפשתן \u0003בנר חנוכה\u0004 של החנווני שהניחו על פתח חנותו מבחוץ — \u0003פטור\u0004 החנווני, שאז מותר לחנווני להניח את נרו בחוץ. ומכאן \u0003אמר רבינא משום\u0004 (בשם) \u0003רבה: זאת אומרת\u0004 שנר חנוכה \u0003מצוה להניחה בתוך עשרה\u0004 טפחים מהקרקע. \u0003דאי סלקא דעתך\u0004 \u0005[שאם יעלה על דעתך]\u0006 לומר כי מותר להניחה \u0003למעלה מעשרה טפחים,\u0004 מדוע ייפטר החנווני? \u0003לימא ליה\u0004 \u0005[יאמר לו],\u0006 בעל הגמל לחנווני: \u0003היה לך להניח\u0004 את הנר \u0003למעלה מ\u0004גובה \u0003גמל ורוכבו,\u0004 ואז לא היה נגרם נזק, ולכן אין בעל הגמל אחראי. ודוחים: \u0003ודילמא\u0004 \u0005[ושמא]\u0006 יתכן שמותר להניח את נר החנוכה גם למעלה מעשרה טפחים, וטעמו של ר' יהודה שפטר — משום שחשש למצות חנוכה וסבר, \u0003אי מיטרחא ליה טובא אתי לאימנועי\u0004 \u0005[אם יטריחו\u0006 אותו \u0005הרבה יבוא להמנע]\u0006 \u0003ממצוה\u0004 זו של הדלקת נר חנוכה. וכיון שהוצאת נר החנוכה החוצה היא במצות חכמים — אין לחייב את החנווני לנקוט אמצעי זהירות יתרים אלה.","ולעיקר הענין \u0003אמר רב כהנא: דרש רב נתן בר מניומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003ר' תנחום:\u0004"],["\u0003נר של חנוכה שהניחה\u0004 בגובה \u0003למעלה מעשרים אמה\u0004 — \u0003פסולה, כ\u0004דרך שאנו פוסלים \u0003סוכה\u0004 שסככה למעלה מעשרים אמה, \u0003וכמבוי\u0004 שקורתו למעלה מעשרים אמה לענין עירוב. וטעם הדברים אחד הוא — שלגובה שלמעלה מעשרים אמה אין אנשים רגילים לשאת את ראשיהם, ודבר שצריך לראותו — פסול אם היה למעלה מגובה זה. \u0003ו\u0004אגב כך הביאו עוד דבר ש\u0003אמר רב כהנא,\u0004 ש\u0003דרש רב נתן בר מניומי משמיה\u0004 \u0005[משמו]\u0006 של \u0003רב תנחום: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות כתוב זה \u0005שנאמר]\u0006 ביוסף \u0003\"\u0004ויקחוהו וישליכו אותו הבורה \u0003והבור רק אין בו מים\"\u0004 (בראשית לז, כד)? האם \u0003ממשמע שנאמר \"והבור רק \" איני יודע שאין בו מים? אלא מה תלמוד לומר \"אין בו מים\"\u0004 — שבא הכתוב להדגיש וללמד כי \u0003מים אין בו אבל נחשים ועקרבים יש בו.\u0004","\u0003אמר רבה: נר חנוכה מצוה להניחה ב\u0004מרחק של \u0003טפח הסמוכה לפתח.\u0004 ושואלים: \u0003והיכא מנח ליה\u0004 \u0005[והיכן,\u0006 באיזה צד, \u0005מניח אותו]?\u0006 ובכך נחלקו הדעות: \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא אמר: מ\u0004צד \u0003ימין\u0004 של הפתח. \u0003רב שמואל מדפתי אמר: מ\u0004צד \u0003שמאל. והילכתא\u0004 \u0005[והלכה\u0006 היא\u0005]\u0006 שיש להניחה \u0003משמאל.\u0004 וטעמו של דבר: \u0003כדי שתהא נר חנוכה משמאל ומזוזה מימין.\u0004 ונמצא הנכנס לבית מסובב במצוות (גאונים).","\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב אסי\u0004 שכך \u0003אמר רב: אסור להרצות\u0004 (למנות) \u0003מעות כנגד נר חנוכה.\u0004 וסיפר רב יהודה: \u0003כי אמריתה קמיה\u0004 \u0005[כאשר אמרתי אותה,\u0006 את הלכה זו \u0005לפני]\u0006 \u0003שמואל, אמר לי: וכי נר\u0004 חנוכה \u0003קדושה יש בה\u0004 שאסור להשתמש לאורה? \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 על שאלה זו \u0003רב יוסף:\u0004 וכי מה שאלה היא זו, \u0003וכי דם\u0004 שחיטה \u0003קדושה יש בו? דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 שאת הפסוק \u0003\"ושפך...\u0004 את דמו \u0003וכסה\u0004 בעפר\u0003\"\u0004 (ראה ויקרא יז, יג) דרשו: \u0003במה ששפך יכסה.\u0004 שכשם ששפך את דם השחיטה בידו, כך חייב לכסות את הדם בידו, \u0003שלא יכסנו ברגל,\u0004 וטעמו של דבר: \u0003שלא יהו מצות בזויות עליו. הכא נמי\u0004 \u0005[כאן גם כן]\u0006 יש לנהוג קדושה בנר חנוכה, כדי \u0003שלא יהו מצות בזויות עליו\u0004 וישתמש בהן לצרכים אחרים.","מסופר כי \u0003בעו מיניה\u0004 \u0005[שאלו ממנו]\u0006 \u0003מר' יהושע בן לוי: מהו\u0004 הדין שיוכל אדם \u0003להסתפק\u0004 (להשתמש, להנות) \u0003מנויי סוכה\u0004 (אותם הדברים שתולים בסוכה כדי ליפותה) \u0003כל שבעה\u0004 ימי חג הסוכות? \u0003אמר להו\u0004 \u0005[להם]:\u0006 \u0003הרי\u0004 כבר \u0003אמרו\u0004 בדומה לכך ש\u0003אסור להרצות מעות כנגד נר חנוכה,\u0004 ומכאן שאין להשתמש בחפץ של מצוה לתכלית אחרת. אמר על כך \u0003רב יוסף\u0004 בתמיהה: \u0003מריה\u0004 \u0005[ריבונו]\u0006 של \u0003אברהם! תלי תניא בדלא תניא\u0004 \u0005[תלה את\u0006 הדבר \u0005השנוי\u0006 בדבר \u0005שאיננו שנוי],\u0006 שהרי לגבי \u0003סוכה תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 שיש איסור ליהנות מנויה, והאיסור בנר \u0003חנוכה לא תניא\u0004 \u0005[נשנה]\u0006 בברייתא כלל. \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]\u0006 למסכת סוכה: סוכה אשר \u0003סככה כהלכתה ועיטרה בקרמים\u0004 (יריעות צבועות) \u0003ובסדינין המצויירין, ותלה בה\u0004 לקישוט \u0003אגוזים, אפרסקין, שקדים ורמונים, ופרכילי\u0004 (ענפי) \u0003ענבים ועטרות\u0004 (זרים) \u0003של שבלים, יינות, של שמנים וסלתות\u0004 (כלים מלאים סולת) — \u0003אסור להסתפק מהן עד מוצאי יום טוב האחרון של חג. ו\u0004אולם \u0003אם התנה עליהן\u0004 לפני שתלה אותם שתהא בידו רשות להשתמש בהם אף בימי החג — \u0003הכל לפי תנאו,\u0004 ומותר. ובכל אופן מאחר והאיסור להנות מנר חנוכה לא נשנה במפורש אין להביא ראיה \u0003ממנו לענין נוי סוכה! אלא אמר רב יוסף:\u0004 אין צורך להביא ראיה לדין הסוכה מנר חנוכה, כי אם \u0003אבוהון דכולהו\u0004 \u0005[אביהם של כולהו]\u0006 \u0003דם,\u0004 שהמקור הראשון שממנו למדים אנו שאין לנהוג בזיון במצוות הוא הכתוב בדבר כיסוי דם שחיטה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 במחלוקת האמוראים: \u0003רב אמר, אין מדליקין\u0004 בנרות חנוכה \u0003מנר\u0004 אחד \u0003לנר\u0004 אחר. \u0003ושמואל אמר מדליקין.\u0004 ואגב כך הביאו גם כן ש\u0003רב אמר: אין מתירין ציצית מבגד\u0004 אחד כדי להטילה ב\u0003בגד\u0004 אחר. \u0003ושמואל אמר: מתירין מבגד לבגד.\u0004 ועוד, \u0003רב אמר: אין הלכה כ\u0004שיטת \u0003ר' שמעון בגרירה,\u0004 כלומר, כר' שמעון שהתיר לגרור חפצים בשבת, אף שבגרירתם הם עושים חריץ באדמה, מאחר שאין הוא מתכוון בגרירה לחפור באדמה. ואילו \u0003שמואל אמר\u0004 שיש לפסוק \u0003הלכה כ\u0004שיטת \u0003ר' שמעון בגרירה.\u0004","\u0003אמר אביי: כל מילי דמר עביד\u0004 \u0005[הדברים עשה החכם]\u0006 רבה \u0003כרב לבר מהני תלת דעביד\u0004 \u0005[חוץ משלשה אלה שעשה]\u0006 \u0003כשמואל\u0004 שפסק: \u0003מדליקין\u0004 בנר חנוכה \u0003מנר לנר, ומתירין\u0004 ציצית \u0003מבגד לבגד, והלכה כר' שמעון ב\u0004דין \u0003גרירה.\u0004 וענין הגרירה הוא כפי \u0003דתניא\u0004 \u0005[ששנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' שמעון אומר: גורר אדם מטה, כסא\u0004 או \u0003ספסל\u0004 על האדמה, \u0003ובלבד שלא יתכוין\u0004 בכך \u0003לעשות חריץ\u0004 באדמה. אך אם נעשה חריץ ממילא — אין להקפיד.","\u0003יתיב ההוא מרבנן קמיה\u0004 \u0005[ישב אחד החכמים לפני]\u0006 \u0003רב אדא בר אהבה ויתיב וקאמר\u0004 \u0005[וישב ואמר]:\u0006 \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003רב\u0004 שאסר להדליק בנרות חנוכה מנר לנר הרי הוא \u0003משום ביזוי מצוה,\u0004 שעל ידי השימוש בנר הוא מבזה את מצות החנוכה, שבכך הוא משתמש בנר החנוכה לא להארה אלא לצורך אחר. \u0003אמר להו\u0004 \u0005[להם]\u0006 רב אדא בר אהבה לתלמידיו: \u0003לא תציתו ליה\u0004 \u0005[אל תשמעו לו],\u0006 כי \u0003טעמא\u0004 \u0005[הטעם]\u0006 של \u0003רב\u0004 הוא: \u0003משום דקא\u0004 \u0005[שהוא]\u0006 \u0003מכחיש מצוה,\u0004 שעל ידי ההדלקה מנר לנר הוא ממעט קצת מן השמן והפתילה שהוקדשו לצורך המצוה. ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה הבדל\u0006 המעשי \u0005ביניהם]?\u0006 ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה באופן \u0003דקא\u0004 \u0005[שהוא]\u0006 \u0003מדליק משרגא לשרגא\u0004 \u0005[מנר לנר]\u0006 במישרין, ואיננו מדליק קיסם או נר אחר כדי להדליק בו אחר כך את השני שלדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שטעמו של רב \u0003משום ביזוי מצוה,\u0004 הרי \u0003משרגא לשרגא\u0004 \u0005[מנר לנר]\u0006 \u0003מדליק\u0004 אף מלכתחילה, שאינו מפחית מקדושת המצוה בהדלקת נר אחר שאף הוא לצורך מצוה, ואילו לדעת \u0003מאן דאמר\u0004 \u0005[מי שאומר]\u0006 שטעמו של רב \u0003משום אכחושי\u0004 \u0005[הכחשה]\u0006 של \u0003המצוה,\u0004 אם כן \u0003משרגא לשרגא נמי\u0004 \u0005[מנר לנר גם כן]\u0006 \u0003אסור,\u0004 שהרי סוף סוף מנצל הוא נר של מצוה לדבר שהיה יכול לעשותו בנר של חולין.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אויא\u0004 ממה ששנינו בתוספתא: \u0003סלע\u0004 (מטבע) \u0003של\u0004"],["\u0003מעשר שני אין שוקלין כנגדו דנרי זהב\u0004 כדי לקבוע את משקלם המדוייק, \u0003ואפילו\u0004 אם נעשית שקילה זו על מנת \u0003לחלל עליו מעשר שני אחר,\u0004 כדי לא ליהנות מכסף המעשר. \u0003אי אמרת בשלמא כי פליגי\u0004 \u0005[נניח אם אתה אומר\u0006 כי \u0005כאשר חלוקים]\u0006 \u0003רב ושמואל\u0004 הרי זה במדליק \u0003מנר לנר\u0004 ממש, \u0003אבל בקינסא\u0004 \u0005[בקיסם]\u0006 \u0003אסר שמואל, הא לא תהוי תיובתא\u0004 \u0005[זו לא תהיה קושיה חמורה עליו].\u0006 \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003בקינסא נמי שרי\u0004 \u0005[בקיסם גם כן מותר]\u0006 להדליק מנר של מצוה, \u0003הא תהוי תיובתא\u0004 \u0005[זו תהיה קושיה חמורה],\u0006 שהרי לא הותרו שימוש והנאה מדבר שבקדושה אפילו לצורך קדושה דומה! \u0003אמר רבה:\u0004 אין זו קושיה, כי במעשר אסרו \u0003גזירה שמא לא יכוין משקלותיו\u0004 בדיוק, ויתברר שדינרי זהב ששקל כנגד הסלע לא היו שווים לו במשקלם, וימלך בדעתו \u0003וקא מפיק להו\u0004 \u0005[ויוציאם]\u0006 \u0003לחולין,\u0004 כלומר, ישאירם חולין כמו שהיו, ונמצא שהשתמש בכסף מעשר לצורך חולין. אך כשמדליק אפילו קיסם לצורך נר חנוכה ודאי שהמטרה היא לצורך מצוה, ואין כאן איסור.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב ששת\u0004 ממה ששנינו בברייתא: נאמר על המנורה \u0003\"מחוץ לפרוכת העדת\u0004 באהל מועד \u0003יערך\u0004 אותו אהרן מערב עד בוקר לפני ה' תמיד חוקת עולם לדורותיכם\u0003\"\u0004 (ויקרא כד, ג). ויש להבין: \u0003וכי\u0004 ה' \u0003לאורה הוא צריך,\u0004 שיאירו לפניו בלילה? \u0003והלא כל ארבעים שנה שהלכו בני ישראל במדבר לא הלכו אלא לאורו\u0004 של ה' בעמוד האש! \u0003אלא\u0004 הדלקת המנורה \u0003עדות היא לבאי עולם שהשכינה שורה בישראל.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 \u0003עדות זו? אמר רב: זו נר מערבי\u0004 שבמנורה \u0003שנותן בה שמן כמדת\u0004 השמן שהיה נותן ב\u0003חברותיה,\u0004 שאר הנרות, \u0003ו\u0004בכל זאת \u0003ממנה היה מדליק ובה היה מסיים,\u0004 שהנר המערבי היה ממשיך לבעור במשך כל היממה, בעוד ששאר הנרות דלקו רק בלילה, ובכל ערב היו שבים ומדליקים את שאר הנרות מהנר המערבי. \u0003והא הכא\u0004 \u0005[והרי כאן],\u0006 במקדש, הלא \u0003כיון דקביעי\u0004 \u0005[שקבועים]\u0006 ה\u0003נרות\u0004 במנורה ואין אפשרות להדליק מנר לנר ממש, \u0003לא סגיא דלא משקיל ואדלוקי\u0004 \u0005[אי אפשר בלא לקחת ולהדליק]\u0006 קיסם, ועל ידו להדליק מן הנר המערבי את שאר הנרות, ואם כן, \u0003קשיא\u0004 \u0005[קשה]\u0006 \u0003בין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי אין מדליקים מנר לנר \u0003משום בזוי מצוה, ובין למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי אין מדליקים \u0003משום אכחושי\u0004 \u0005[הכחשת]\u0006 ה\u0003מצוה!\u0004","\u0003תרגמה\u0004 \u0005[הסביר אותה]\u0006 \u0003רב פפא\u0004 שאין הכרח לפרש כך, אלא המדובר \u0003בפתילות ארוכות\u0004 שאפשר היה למשוך אותן מנר אחד לחבירו ולהדליקם בדרך זו. ואולם \u0003סוף סוף, למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי אין מדליקים מנר לנר \u0003משום אכחושי\u0004 \u0005[הכחשת]\u0006 ה\u0003מצוה קשיא\u0004 \u0005[קשה]\u0006 מכאן. ומשיבים: אכן, אין תשובה בדבר והשאלה נשארת \u0003קשיא\u0004 \u0005[קשה].\u0006","ולסיכום שואלים: \u0003מאי הוי עלה\u0004 \u0005[מה היה עליה,\u0006 על הלכה זו\u0005],\u0006 כיצד נוהגים בענין הדלקה מנר לנר? \u0003אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003ר' יהושע: חזינא\u0004 \u0005[רואים אנו],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 אם ההלכה כדעת האומר שה\u0003הדלקה\u0004 של נר החנוכה היא ה\u0003עושה\u0004 את \u0003המצוה\u0004 והשאר איננו אלא טפל — הרי \u0003מדליקין מנר לנר,\u0004 שכן עצם ההדלקה היא עיקרה של מצות נר חנוכה. \u0003ואי\u0004 \u0005[ואם]\u0006 ההלכה כדעת האומר שה\u0003הנחה\u0004 של הנר הדלוק במקום ראוי היא ה\u0003עושה\u0004 את ה\u0003מצוה\u0004 — הרי \u0003אין מדליקין מנר לנר,\u0004 שלפי שיטה זו ההדלקה היא רק פעולת עזר לעצם המצוה, שהיא הנחת הנרות במקום שייראו לרבים, ומאחר והיא לשם הכנה בלבד אין לזלזל בכבוד המצוה.","אגב שהוזכר הדיון אם הדלקה עושה מצוה או הנחה עושה מצוה, מביאים אותו במלואו. \u0003דאיבעיא להו\u0004 \u0005[שנשאלה להם]\u0006 לבני הישיבה שאלה זו: האם בנר חנוכה ה\u0003הדלקה\u0004 היא ה\u0003עושה\u0004 את ה\u0003מצוה,\u0004 והנחת הנרות הבוערים היא המשך בלבד, \u0003או\u0004 שמא \u0003ההנחה\u0004 של הנרות הבוערים היא ה\u0003עושה\u0004 את ה\u0003מצוה,\u0004 וההדלקה היא רק הכרח מעשי לצורך ההנחה?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה זו ממה ש\u0003אמר רבא:\u0004 מי ש\u0003היה תפוש נר חנוכה\u0004 דולק בידו \u0003ועומד\u0004 — \u0003לא עשה ולא כלום. שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי ה\u0003הנחה\u0004 היא ה\u0003עושה\u0004 את ה\u0003מצוה,\u0004 וכל עוד לא הניח את הנר במקומו הראוי לא קיים את המצוה! ודוחים: \u0003התם\u0004 \u0005[שם]\u0006 אמרו שאינו יוצא ידי חובה מטעם אחר, משום ש\u0003הרואה\u0004 אותו \u0003אומר\u0004 לעצמו כי המחזיק את הנר לא לצורך מצוה אוחזו אלא \u0003לצורכו הוא דנקיט לה\u0004 \u0005[שמחזיק אותה],\u0006 וכיון שיכול המחזיק להטעות את הרואים בדבר, ודאי אין בכך משום מצוה.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ש\u0003אמר רבא:\u0004 מי ש\u0003הדליקה\u0004 לאותו נר חנוכה \u0003בפנים והוציאה\u0004 אחר כך החוצה והניחה בפתח ביתו — \u0003לא עשה כלום\u0004 בקיום המצוה. \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 ש\u0003הדלקה עושה מצוה\u0004 — מובן הדבר, כי \u0003הדלקה במקומו\u0004 (כלומר, במקום שחלה המצוה) \u0003בעינן\u0004 \u0005[אנו צריכים],\u0006 ו\u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003לא עשה ולא כלום. אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי \u0003הנחה עושה מצוה, אמאי\u0004 \u0005[מדוע]\u0006 אם כן \u0003לא עשה ולא כלום?\u0004 והלא הניחה במקום הראוי לה! \u0003ומשיבים: התם נמי\u0004 \u0005[שם גם כן]\u0006 \u0003הרואה\u0004 אותו שהדליקה בפנים אף שהוציאה לאחר מכן החוצה, \u0003הוא אומר\u0004 לעצמו כי \u0003לצורכו הוא דאדלקה\u0004 \u0005[שהדליקה]\u0006 אותו אדם, וסבור שלא הדליק נר חנוכה כמצוותו.","אלא \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון אחר לדבר ממה ששנינו ש\u0003אמר ר' יהושע בן לוי:\u0004"],["\u0003עששית\u0004 (פנס) \u0003שהיתה דולקת והולכת כל היום כולו\u0004 בשבת, \u0003למוצאי שבת מכבה ומדליקה\u0004 מחדש, ויכול להשתמש בה כנר חנוכה. ומעתה \u0003אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי ה\u0003הדלקה\u0004 היא ה\u0003עושה\u0004 את ה\u0003מצוה\u0004 — \u0003שפיר\u0004 \u0005[יפה]\u0006 ומובן הדבר, שלכן יש לכבות את העששית ולחזור להדליקה כדי לקיים בפועל מצות הדלקת נר חנוכה. \u0003אלא אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 כי ה\u0003הנחה\u0004 היא ה\u0003עושה\u0004 את ה\u0003מצוה,\u0004 אם כן \u0003האי\u0004 \u0005[\u0006לשון \u0005זה]\u0006 ששנינו ש\u0003מכבה ומדליקה\u0004 אינו מדוייק, שכן לפי זה הרי \u0003מכבה ומגביהה\u0004 ממקומה \u0003ומניחה ומדליקה מיבעי ליה\u0004 \u0005[צריך\u0006 היה \u0005לו]\u0006 לומר, שהלא רק על ידי הנחה במקום הראוי בכך יוכל לקיים את מצות הנחת נר החנוכה במקומה. \u0003ועוד\u0004 ראיה: \u0003מדקא מברכינן\u0004 \u0005[מ\u0006מה \u0005שאנו מברכים]\u0006 על הנרות בלשון \u0003\"אשר קדשנו במצותיו וצונו להדליק נר של חנוכה\" שמע מינה\u0004 \u0005[למד ממנה]\u0006 כי ה\u0003הדלקה\u0004 היא ה\u0003עושה\u0004 את ה\u0003מצוה\u0004 ועליה מברכים. \u0003שמע מינה\u0004 \u0005[למד ממנה].\u0006","ומעירים: \u0003השתא דאמרינן\u0004 \u0005[עכשיו שאמרנו]\u0006 כי ה\u0003הדלקה עושה מצוה\u0004 הרי יש לכך אף משמעות מעשית, שאם \u0003הדליקה\u0004 את נר החנוכה \u0003חרש, שוטה\u0004 או \u0003קטן,\u0004 שאינם חייבים במצוות — \u0003לא עשה ולא כלום,\u0004 ואף אם הניחה אחר כך גדול בר דעת במקום ראוי. וזאת משום שהנחת הנרות המודלקים אין בה מן המצוה, וההדלקה היא צריכה להיעשות כראוי בידי בר דעת החייב במצוה. ואולם \u0003אשה ודאי מדליקה,\u0004 ש\u0003אמר ר' יהושע בן לוי: נשים חייבות ב\u0004הדלקת \u0003נר חנוכה,\u0004 לפי \u0003שאף הן היו באותו הנס\u0004 של הצלה מגזירות השמד.","\u0003אמר רב ששת: אכסנאי\u0004 \u0005[דייר הגר במלון]\u0006 \u0003חייב ב\u0004הדלקת \u0003נר חנוכה\u0004 במקום שבו הוא נמצא. מסופר ש\u0003אמר ר' זירא: מריש כי הוינא בי\u0004 \u0005[מתחילה כאשר הייתי\u0006 לומד \u0005בבית]\u0006 ה\u0003רב משתתפנא בפריטי בהדי אושפיזא\u0004 \u0005[הייתי משתתף בפרוטות עם בעל המלון],\u0006 שיהיה לי חלק בהדלקת נר החנוכה שהדליקו שם. \u0003בתר דנסיבי איתתא, אמינא\u0004 \u0005[אחרי שנשאתי אשה, אמרתי]:\u0006 \u0003השתא ודאי לא צריכנא, דקא מדליקי עלי בגו ביתאי\u0004 \u0005[עכשיו ודאי אינני צריך,\u0006 מאחר \u0005שמדליקים עלי בתוך ביתי].\u0006","\u0003אמר ר' יהושע בן לוי: כל השמנים כולן יפין לנר, ושמן זית מן המובחר.\u0004 ו\u0003אמר אביי: מריש הוה\u0004 \u0005[בראשונה היה]\u0006 \u0003מהדר מר\u0004 \u0005[אדוני],\u0006 רבה, \u0003אמשחא דשומשמי\u0004 \u0005[אחר שמן שומשומין],\u0006 כי \u0003אמר\u0004 \u0005[היה אומר]:\u0006 \u0003האי משך נהוריה טפי\u0004 \u0005[זה,\u0006 שמן השומשומין \u0005נמשך אורו יותר]\u0006 זמן, שאינו כלה מהר כשמן הזית. \u0003כיון\u0004 ש\u0003שמע לה להא\u0004 \u0005[לאותה]\u0006 אימרה של \u0003ר' יהושע בן לוי,\u0004 היה \u0003מהדר אמשחא דזיתא\u0004 \u0005[אחר שמן\u0006 \u0003זית],\u0004 כי \u0003אמר\u0004 \u0005[היה אומר]:\u0006 \u0003האי צליל נהוריה טפי\u0004 \u0005[זה צלול אורו יותר].\u0006","\u0003ו\u0004בדומה לכך \u0003אמר ר' יהושע בן לוי: כל השמנים יפין ל\u0004עשיית ה\u0003דיו, ושמן זית מן המובחר. איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה זו: מה היתה כוונתו של ר' יהושע בן לוי, האם כוונתו שהעשן היוצא מהדלקת שמן הזית מובחר יותר בכך שניתן \u0003לגבל\u0004 אותו באופן הטוב ביותר לדיו, \u0003או\u0004 בכלל לענין \u0003לעשן,\u0004 כלומר, שהעשן היוצא מנר של שמן זית הוא המובחר ביותר לצורך עשיית דיו? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 תשובה לדבר ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב שמואל בר זוטרא: כל השמנים יפין לדיו, ושמן זית מן המובחר, בין לגבל בין לעשן. רב שמואל בר זוטרא מתני הכי\u0004 \u0005[היה שונה כך]:\u0006 \u0003כל העשנים יפין לדיו, ושמן זית מן המובחר.\u0004 מעין זה \u0003אמר רב הונא: כל השרפין יפין ל\u0004חזק את תרכובת ה\u0003דיו, ושרף קטף יפה מכולם.\u0004","\u0003אמר רב חייא בר אשי אמר רב: המדליק נר של חנוכה צריך לברך. ור' ירמיה אמר: הרואה נר של חנוכה\u0004 כשהוא דלוק \u0003צריך לברך,\u0004 שאין המצוה בהדלקה בלבד, אלא אף בראיית הנרות, ולכך אף בראייה בלבד יש מקום לברכה. \u0003אמר רב יהודה:\u0004 ב\u0003יום ראשון\u0004 של חנוכה, \u0003הרואה\u0004 את הנרות כשהם דלוקים \u0003מברך שתים,\u0004 שתי ברכות, \u0003ו\u0004ה\u0003מדליק מברך שלש\u0004 ברכות. \u0003מכאן ואילך,\u0004 מהיום השני של חנוכה והלאה, ה\u0003מדליק מברך שתים, ו\u0004ה\u0003רואה מברך\u0004 ברכה \u0003אחת.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 איזו ברכה הוא \u0003ממעט\u0004 בשאר הימים? ומשיבים: הריהו \u0003ממעט\u0004 את ברכת ה\u0003זמן,\u0004 \"שהחיינו וקיימנו והגיענו לזמן הזה\". ושואלים: \u0003ונימעוט\u0004 \u0005[ושימעט]\u0006 את ברכת ה\u0003נס,\u0004 \"שעשה נסים\"! ומשיבים: ה\u0003נס\u0004 ב\u0003כל יומי איתיה\u0004 \u0005[הימים ישנו],\u0006 ואולם ברכת \"שהחיינו\" שייכת רק להתחלת המצוה בכל שנה.","ו\u0003מאי\u0004 \u0005[מה]\u0006 הוא \u0003מברך?\u0004 — \u0003מברך \"אשר קדשנו במצותיו וצונו להדליק נר של חנוכה\".\u0004 ושואלים: \u0003והיכן צונו?\u0004 שהרי אין מצות החנוכה נזכרת בתורה, וכיצד אפשר לומר עליה שהיא דבר שציוונו ה'? ומשיבים: \u0003רב אויא אמר:\u0004 חובת ברכה זו נלמדת \u0003מ\u0004הכתוב \u0003\"לא תסור\u0004 מן הדבר אשר יגידו לך ימין ושמאל\u0003\"\u0004 (דברים יז, יא), שמכתוב זה נלמד הציווי לכל ישראל לשמוע לגזירות החכמים, ומכאן שהמקיים דבריהם — מקיים מצות ה'. \u0003רב נחמיה אמר:\u0004 למדים זאת מן הפסוק \u0003\"שאל אביך ויגדך זקניך ויאמרו לך\"\u0004 (דברים לב, ז), ומכאן שיש מצוה לשמוע בקול זקני ישראל.","על עיקרה של תשובה זו \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב עמרם\u0004 ממה ששנינו במשנה: נאמר כי \u0003הדמאי\u0004 שהוא תבואה שנרכשה מעם הארץ, וספק בידינו אם הופרש ממנה מעשר, \u0003מערבין בו\u0004 עירוב תחומים וחצרות, \u0003ומשתתפין בו\u0004 שיתוף מבואות, \u0003ומברכין עליו\u0004 לפניו ואחריו, \u0003ומזמנין עליו.\u0004 שאף שאמרו חכמים שיש לחזור ולהפריש מעשר מן הדמאי, בכל זאת בדיעבד התירו שימושו לצרכים מסויימים ובשעת הדחק. \u0003ו\u0004כן אמרו ש\u0003מפרישין אותו,\u0004 את המעשר מהדמאי כשהמפריש \u0003ערום,\u0004 וגם \u0003בין השמשות\u0004 בערב שבת, בעוד שהפרשת מעשר מטבל ממש אסורה. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003כל\u0004 דבר \u0003שהוא מדרבנן בעי\u0004 \u0005[מדברי סופרים צריך,\u0006 טעון\u0005]\u0006 \u0003ברכה,\u0004 כיון שקיומם מדברי חכמים מבוסס על מצות \"לא תסור\", אם כן \u0003הכא כי קאי\u0004 \u0005[כאן כאשר\u0006 הוא \u0005עומד]\u0006 \u0003ערום היכי\u0004 \u0005[איך]\u0006 הוא \u0003מברך? והא בעינן\u0004 \u0005[והרי צריכים אנו]\u0006 שיקויים \"\u0003והיה מחניך קדוש\u0004 ולא יראה בך ערות דבר ושב מאחריך\u0003\"\u0004 (דברים כג, טו), \u0003וליכא\u0004 \u0005[ואין]\u0006 אפשרות שתהא אותה הקדושה האמורה כאשר הוא מברך בגילוי ערוה! \u0003אמר אביי:\u0004 יש לחלק בדברים: \u0003ודאי דדבריהם,\u0004 כלומר מצוה ודאית שהיא מדברי סופרים, \u0003בעי\u0004 \u0005[צריכה,\u0006 טעונה\u0005]\u0006 \u0003ברכה,\u0004 ואילו \u0003ספק דדבריהם,\u0004 שגזרו עליו חכמים רק מחמת הספק, כהפרשת דמאי \u0003לא בעי\u0004 \u0005[אינו צריך]\u0006 \u0003ברכה\u0004 ושואלים:","\u0003והא\u0004 \u0005[והרי]\u0006 \u0003יום טוב שני\u0004 של גלויות ש\u0003ספק\u0004 שמ \u0003דבריהם הוא\u0004 אם היום הראשון הוא יום החג האמיתי או השני, \u0003ו\u0004בכל זאת \u0003בעי\u0004 \u0005[\u0006הוא \u0005טעון]\u0006 ברכה, שמברכים בשני את כל ברכות החג? ומשיבים: \u0003התם כי היכי דלא לזילזולי בה\u0004 \u0005[שם,\u0006 ביום טוב שני, חובת הברכה היא \u0005כדי שלא יזלזלו בו],\u0006 שאם לא היו מצריכים לברך את ברכות החג, היו באים לזלזל בקדושת יום טוב שני. \u0003רבא אמר\u0004 טעם אחר: לדעתו הדמאי איננו אפילו בגדר ספק מדברי חכמים, כי \u0003רוב עמי הארץ מעשרין הן,\u0004 והחשש שמא לא הופרש מעשר מן התבואה אינו בגדר ספק רגיל והריהו חשש בלבד, ועל כעין זה לא תקנו חכמים ברכה. מה שאין כן לגבי יום טוב שני שאף שהוא גזירה מחמת הספק, מכל מקום מברך בו על ברכות יום טוב. שמאחר ותקנת חכמים היא, חייב לברך כמו שתקנו ברכה לכל תקנות חכמים.","\u0003אמר רב הונא: חצר שיש לה שני פתחים צריכה שתי נרות,\u0004 נר בכל פתח, שייראה שמדליקים בחצר זו כראוי. \u0003אמר רבא: לא אמרן\u0004 \u0005[אמרנו]\u0006 דבר זה \u0003אלא\u0004 כששני הפתחים הם \u0003משתי רוחות\u0004 (צדדים), \u0003אבל\u0004 כאשר שניהם \u0003מרוח אחת\u0004 — \u0003לא צריך\u0004 להדליק יותר מבפתח אחד\u0003.\u0004 את דברי רבא מבררים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אילימא\u0004 \u0005[אם נאמר]\u0006 שהוא \u0003משום חשדא\u0004 \u0005[חשד]\u0006 של הרואים את הפתח ואין נר דלוק בו שמא אינו מדליק נרות חנוכה, \u0003חשדא דמאן\u0004 \u0005[חשד של מי]?\u0006 \u0003אילימא חשדא דעלמא\u0004 \u0005[אם תאמר\u0006 שהוא \u0005חשד\u0006 של אנשים \u0005סתם],\u0006 שאינם בני העיר ואינם מכירים אותו, אם כן \u0003אפילו\u0004 כאשר שני הפתחים \u0003ברוח אחת נמי ליבעי\u0004 \u0005[גם כן יצטרכו]\u0006 להדליק בשניהם, שהרי אין אלה יודעים ששני הפתחים שייכים לחצר אחת. \u0003ואי חשדא דבני מתא\u0004 \u0005[ואם חשד של בני העיר]\u0006 — \u0003אפילו\u0004 כאשר שני הפתחים \u0003משני רוחות נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליבעי\u0004 \u0005[יצטרכו],\u0006 שהרי הם מכירים ויודעים שרק אדם אחד גר בחצר זו וחושבים שאם לא מונח נר בפתח זה ודאי הדליק בפתח השני. ומשיבים: \u0003לעולם\u0004 תאמר שהדבר הוא \u0003משום חשדא דבני מתא\u0004 \u0005[חשד בני העיר],\u0006 \u0003וזימנין דמחלפי בהאי ולא חלפי בהאי\u0004 \u0005[ולפעמים\u0006 קורה \u0005ש\u0006הם \u0005עוברים ליד\u0006 פתח \u0005זה,\u0006 אחד, \u0005ואינם חולפים ליד זה,\u0006 השני\u0005],\u0006 \u0003ואמרי\u0004 \u0005[ואומרים]:\u0006 \u0003כי היכי דבהאי פיתחא\u0004 \u0005[כמו שבפתח זה]\u0006 \u0003לא אדליק\u0004 \u0005[הדליק]\u0006 — \u0003בהך פיתחא נמי\u0004 \u0005[בפתח זה,\u0006 השני, \u0005גם כן]\u0006 \u0003לא אדליק\u0004 \u0005[הדליק] ,\u0006 וכדי לצאת מחשד הבריות מוטב שידליק בשני פתחיו.","\u0003ומנא תימרא דחיישינן\u0004 \u0005[ומנין תאמר,\u0006 ראייה לכך, \u0005שאנו חוששים]\u0006 \u0003לחשד?\u0004 — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בתוספתא\u0005]\u0006 ש\u0003אמר ר' שמעון: בשביל ארבעה דברים אמרה תורה\u0004 שיש \u0003להניח פיאה\u0004 ולהשאיר את התבואה לעניים דווקא \u0003בסוף שדהו,\u0004 שרק אחר שקצר כמעט את כל שדהו יותיר בסוף פאה שאינה קצורה לעניים. ולא ישאיר את החלק המיועד לפאה באמצע השדה בתוך מהלך הקצירה. והטעמים הם: \u0003מפני גזל עניים, ומפני ביטול עניים, ומפני החשד, ומשום \"בל תכלה\u0004 פאת שדך בקצרך\u0003\"\u0004 (ראה ויקרא כג, כב). ומפרשים: \u0003מפני גזל עניים\u0004 — \u0003שלא יראה בעל הבית שעה פנוייה\u0004 שאין העניים נמצאים ליד השדה \u0003ו\u0004מאחר שיכול הוא להגדיר את הפאה כרצונו יש לחשוש שמא \u0003יאמר לקרובו\u0004 ה\u0003עני: \"הרי זו פאה\"\u0004 במקום ובזמן שהוא רוצה, ובכך להעלים משאר העניים את העובדה שיש פאה בשדהו, ונמצא שנגזל חלקם של שאר עניים."],["\u0003ומפני ביטול עניים\u0004 — כדי \u0003שלא יהו\u0004 ה\u0003עניים\u0004 שאינם יודעים מתי הוא עשוי לקצור את השדה, והיכן הוא עתיד להשאיר להם את הפאה, \u0003יושבין ומשמרין\u0004 (מצפים) עד שיגדיר את הפאה, ואומרים כל הזמן לעצמם: \u0003\"עכשיו מניח בעל הבית פאה\"\u0004 ועתה שמניח בקצה שדהו במקום מוגדר, ויודעים העניים בדיוק היכן עתיד להיות חלקם, ולא יבטלו העניים זמנם בצפיה. \u0003ומפני החשד\u0004 — שאם הניח פאה באמצע שדהו, הרי משהגדיר את מקום הפאה מיד יבואו העניים ויטלו חלקם, ולאחר מכן יבוא הוא ויקצור ויאסוף את כל שאר התבואה שבשדה ובשל כך לא תיראה הפאה. וכדי \u0003שלא יהיו עוברין ושבין אומרים: תבא מארה לאדם שלא הניח פאה בשדהו,\u0004 לכך אמרו שיגדיר את מקום הפאה רק בסוף הקצירה. שנינו כי הטעם הרביעי הוא \u0003משום \"בל תכלה\".\u0004 ותוהים: \u0003אטו כולהו לאו\u0004 \u0005[האם כולם לא]\u0006 \u0003משום \"בל תכלה\" נינהו\u0004 \u0005[הם]?\u0006 והרי כל שאר הטעמים באו להסביר מדוע מניחים את הפאה בסוף השדה! \u0003אמר רבא:\u0004 הטעם האחרון משמעו שעשו זאת \u0003מפני הרמאין,\u0004 שמא לא יפריש אדם פאה כלל ויוכל לטעון שהפרישה כבר בתוך שדהו וכבר נטלוה העניים, וכדי לחזק את קיום מצות הפאה תיקנו שיפרישו דווקא בסוף השדה. ולענייננו למדים אנו כי הרצון שלא להביא את הבריות לידי חשד הוא נימוק שמתחשבים בו בהלכה.","\u0003אמר רב יצחק בר רדיפה\u0004 שכך \u0003אמר רב הונא: נר\u0004 (כלי קיבול לשמן) \u0003שיש לה שני פיות\u0004 המיועדות לפתילות, ופתילה בכל אחד מהן — \u0003עולה\u0004 (נחשבת) היא לצאת ידי חובת נר חנוכה \u0003לשני בני אדם.\u0004 ומעין זה \u0003אמר רבא: מילא קערה\u0004 ב\u0003שמן והקיפה\u0004 ב\u0003פתילות,\u0004 אם \u0003כפה\u0004 (הפך) \u0003עליה כלי\u0004 — \u0003עולה\u0004 היא לצאת ידי חובת נר חנוכה \u0003לכמה בני אדם\u0004 כמנין הפתילות, שעל ידי כפיית הכלי על הקערה נראית כל פתילה בוערת לעצמה. ואם \u0003לא כפה עליה כלי\u0004 — \u0003עשאה\u0004 שתיראה \u0003כמין מדורה\u0004 שאור כל הנרות נראה מרחוק כאחד, \u0003ואפילו לאחד נמי\u0004 \u0005[גם כן]\u0006 \u0003אינה עולה,\u0004 שהרי המצוה בנר דווקא.","\u0003אמר רבא: פשיטא\u0004 \u0005[פשוט,\u0006 מובן\u0005]\u0006 \u0003לי\u0004 כי קיים סדר עדיפויות מסויים, וכי כאשר יש לאדם אפשרות להדליק או את \u0003נר ביתו\u0004 (נר שבת) או \u0003נר חנוכה,\u0004 שהוא עני ואין לו כדי לקנות שמן לשני נרות — הרי \u0003נר ביתו עדיף,\u0004 וטעם הדבר, \u0003משום שלום ביתו,\u0004 שאילולא הנר הדולק ישבו בני ביתו ויאכלו סעודתם בחושך. וכן אם בעיה היא גם בהכרעה בין \u0003נר ביתו\u0004 או \u0003קידוש היום\u0004 (היין לצורך הקידוש) — גם אז \u0003נר ביתו עדיף, משום שלום ביתו.\u0004 ואולם \u0003בעי\u0004 \u0005[שאל,\u0006 נסתפק\u0005]\u0006 \u0003רבא:\u0004 כאשר ההכרעה אמורה להיות בין \u0003נר חנוכה\u0004 או היין ל\u0003קידוש היום מהו\u0004 הדין בכגון זה? האם נאמר כי \u0003קידוש היום עדיף,\u0004 שכן הוא \u0003תדיר\u0004 ונעשה בכל שבוע, וכלל הוא שמצוה תדירה ושאינה תדירה — תדירה קודמת, \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003נר חנוכה עדיף משום פרסומי ניסא\u0004 \u0005[פרסום הנס]?\u0006 \u0003בתר דאבעיא, הדר פשטה\u0004 \u0005[אחר ששאלה, חזר ופתרה]\u0006 בעצמו, ופסק כי בכגון זה \u0003נר חנוכה עדיף, משום פרסומי ניסא\u0004 \u0005[פרסום הנס].\u0006","\u0003אמר רב הונא: הרגיל ב\u0004הדלקת ה\u0003נר\u0004 בשבת ובחנוכה — זוכה ו\u0003הויין ליה\u0004 \u0005[יהיו לו]\u0006 \u0003בנים תלמידי חכמים\u0004 שיאירו באורה של התורה. \u0003הזהיר במזוזה\u0004 — \u0003זוכה לדירה נאה\u0004 לקבוע בה את מזוזתו. \u0003הזהיר בציצית\u0004 — \u0003זוכה לטלית נאה. הזהיר בקידוש היום\u0004 — \u0003זוכה וממלא גרבי\u0004 \u0005[כדי]\u0006 \u0003יין.\u0004 ומסופר כי \u0003רב הונא הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה חליף ותני אפתחא\u0004 \u0005[שהיה עובר ושונה על פתח]\u0006 בית \u0003ר' אבין נגרא\u0004 \u0005[הנגר].\u0006 \u0003חזא דהוה\u0004 \u0005[ראה\u0006 את ר' אבין \u0005שהיה]\u0006 \u0003רגיל בשרגי טובא\u0004 \u0005[ב\u0006הדלקת \u0005נרות הרבה]\u0006 לכבוד השבת, \u0003אמר: תרי גברי רברבי נפקי מהכא\u0004 \u0005[שני אנשים גדולים ייצאו מכאן].\u0006 ואכן \u0003נפקי מינייהו\u0004 \u0005[יצאו מהם,\u0006 משם\u0005]\u0006 שני בניו הגדולים, \u0003רב אידי בר אבין ורב חייא בר אבין.\u0004 ומעין זה מסופר: \u0003רב חסדא הוה\u0004 \u0005[היה]\u0006 \u0003רגיל דהוה חליף ותני אפיתחא דבי נשא\u0004 \u0005[שהיה עובר ושונה על פתח בית משפחת]\u0006 אבי \u0003רב שיזבי. חזא דהוה\u0004 \u0005[ראה\u0006 את אבי רב שיזבי \u0005שהיה]\u0006 \u0003רגיל בשרגי טובא\u0004 \u0005[ב\u0006הדלקת \u0005נרות הרבה]\u0006 לכבוד השבת, \u0003אמר: גברא רבה נפק מהכא\u0004 \u0005[אדם גדול ייצא מכאן].\u0006 ואכן \u0003נפק מינייהו\u0004 \u0005[יצא מהם]\u0006 \u0003רב שיזבי.\u0004","מסופר כי \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003רב יוסף הות מאחרא ומדלקת לה\u0004 \u0005[היתה מאחרת בהדלקת]\u0006 נרות שבת. \u0003אמר לה רב יוסף:\u0004 והלא \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 מה שנאמר \u0003\"לא ימיש עמוד הענן יומם ועמוד האש לילה\u0004 לפני העם\u0003\"\u0004 (שמות יג, כב), \u0003מלמד ש\u0004היה \u0003עמוד הענן משלים לעמוד האש\u0004 ולא היה מסתלק מיד עם בואו של עמוד האש, אלא נשאר גם זמן קצר בלילה, \u0003ו\u0004כן היה \u0003עמוד האש משלים לעמוד הענן.\u0004 ולפיכך אף בהדלקת נר השבת ראוי להקדים בהדלקה, ולהוסיף מערב שבת לשבת. \u0003סברה לאקדומה\u0004 \u0005[להקדים אותה],\u0006 את הדלקת הנרות, זמן רב לפני שבת. \u0003אמר לה ההוא סבא\u0004 \u0005[זקן אחד],\u0006 \u0003תנינא\u0004 \u0005[שנינו]:\u0006 \u0003ובלבד שלא יקדים ולא יאחר\u0004 יותר מדי.","מעין הדברים על שכר המדליק נרות \u0003אמר רבא: דרחים רבנן, הוו ליה בנין רבנן\u0004 \u0005[האוהב חכמים, יהיו לו בנים תלמידי חכמים].\u0006 \u0003דמוקיר רבנן, הוו ליה חתנוותא רבנן\u0004 \u0005[המכבד חכמים, יהיו לו חתנים תלמידי חכמים].\u0006 \u0003דדחיל מרבנן\u0004 \u0005[המתיירא מן החכמים],\u0006 \u0003הוא גופיה הוי צורבא מרבנן\u0004 \u0005[עצמו יהיה תלמיד חכם].\u0006 \u0003ואי לאו בר הכי\u0004 \u0005[ואם לא בר כך]\u0006 \u0003הוא,\u0004 שאינו מוכשר לכך, \u0003משתמען מיליה כצורבא מרבנן\u0004 \u0005[יישמעו דבריו כ\u0006דברי \u0005תלמיד חכם].\u0006","\u0003ו\u0004עוד שנינו במשנה ש\u0003לא\u0004 מדליקים \u0003בשמן שריפה\u0004 בשבת. ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003שמן שריפה? אמר רבה:\u0004 הוא \u0003שמן של תרומה שנטמאה. ואמאי קרו\u0004 \u0005[מדוע קוראים]\u0006 \u0003לה \"שמן שריפה\"?\u0004 — \u0003הואיל ולשריפה\u0004 הוא \u0003עומד,\u0004 שבשמן זה אסור להשתמש לאכילה, וחייבים לשורפו. ושואלים: \u0003ובשבת מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא\u0004 מדליקים בשמן שריפה? ומסבירים: ש\u0003מתוך שמצוה עליו לבערו\u0004 ודאי אם כן שיעשה כך, ולכן גזרו \u0003גזרה שמא\u0004 בתוך כך \u0003יטה\u0004 את הנר להחיש את בערתו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: אלא מעתה\u0004 שטעם האיסור בחשש שמא יטה, אם כן \u0003ביום טוב\u0004 שהטיית הנר מותרת בו \u0003לישתרי\u0004 \u0005[יהא מותר]!\u0006 ו\u0003אלמה\u0004 \u0005[מדוע]\u0006 \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 ש\u0003אין מדליקין בשמן שריפה ביום טוב?\u0004 ומשיבים: \u0003גזרה\u0004 היא שגזרו חכמים לאסור זאת אף ב\u0003יום טוב,\u0004 אף שלכאורה אין סיבה \u0003לאסור זאת, אטו\u0004 \u0005[משום]\u0006 האיסור שבדבר ב\u0003שבת\u0004.","\u0003רב חסדא אמר:\u0004 טעם האיסור בהדלקת נר שבת בשמן שריפה הוא אחר, שכן \u0003לשמא יטה לא חיישינן\u0004 \u0005[אין אנו חוששים],\u0006 \u0003אלא הכא\u0004 \u0005[כאן]\u0006 \u0003ביום טוב שחל להיות\u0004 ב\u0003ערב שבת עסקינן\u0004 \u0005[אנו עוסקים]\u0006 במשנתנו ואין להדליק את נרות השבת בשמן שריפה ביום טוב, \u0003לפי שאין שורפין קדשים ביום טוב,\u0004 ובכלל זה אף תרומה. ושואלים: \u0003והא מדקתני סיפא\u0004 \u0005[והרי ממה ששנינו בסוף\u0006 המשנה\u0005],\u0006 כלומר, במשנה הבאה, ש\u0003אין מדליקין בשמן שריפה ביום טוב, מכלל\u0004 הדברים אתה למד \u0003דרישא לאו\u0004 \u0005[הרי שבתחילה,\u0006 במשנה הראשונה, \u0005לא]\u0006 \u0003ביום טוב עסקינן\u0004 \u0005[אנו עוסקים]\u0006 אלא בשבת רגילה! \u0003אמר ר' חנינא מסורא:\u0004 יש להבין את סגנון המשנה בדרך זו, שלא שתי הלכות נבדלות לפנינו כי אם בדרך פירוש \u0003\"מה טעם\" קאמר\u0004 \u0005[אמר]:\u0006 וכך יש להבין: \u0003מה טעם אין מדליקין בשמן שריפה ביום טוב\u0004 ובערב שבת שביום טוב — \u0003לפי שאין שורפין קדשים ביום טוב\u0004 כלל."],["ואכן, \u0003תניא כוותיה\u0004 \u0005[שנויה כשיטתו]\u0006 של \u0003רב חסדא. כל אלו\u0004 השמנים \u0003שאמרו\u0004 ש\u0003אין מדליקין בהן בשבת\u0004 מכל מקום \u0003מדליקין בהן ביום טוב, חוץ משמן שריפה, לפי שאין שורפין קדשים ביום טוב.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לבני הישיבה\u0005]\u0006 שאלה זו: \u0003מהו\u0004 הדין לענין הצורך \u0003להזכיר\u0004 עניינה \u0003של חנוכה בברכת המזון?\u0004 וצדדי השאלה: \u0003כיון דמדרבנן\u0004 \u0005[שמדברי סופרים]\u0006 \u0003הוא,\u0004 לכן \u0003לא מדכרינן\u0004 \u0005[אין אנו מזכירים],\u0006 \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003משום פרסומי ניסא מדכרינן\u0004 \u0005[פרסום הנס אנו מזכירים]?!\u0006 \u0003אמר רבא\u0004 שכך \u0003אמר רב סחורה אמר רב הונא: אינו מזכיר. ו\u0004אולם \u0003אם בא להזכיר\u0004 — \u0003מזכיר בהודאה,\u0004 בברכה המתחילה \"נודה לך\". מסופר כי \u0003רב הונא בר יהודה איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רבא\u0004 בחנוכה. ולאחר שסעד שם עמד לברך ברכת המזון, ובתוך כך \u0003סבר לאדכורי\u0004 \u0005[להזכיר]\u0006 את חנוכה \u0003ב\u0004ברכת \u0003\"בונה ירושלים\". אמר להו\u0004 \u0005[להם]\u0006 לבני הישיבה\u0005]\u0006 \u0003רב ששת:\u0004 מזכירים את חנוכה בברכת המזון \u0003כתפלה. מה\u0004 ב\u0003תפלה\u0004 מזכירים חנוכה \u0003ב\u0004ברכת ה\u0003הודאה\u0004 (\"מודים\") — \u0003אף ברכת המזון\u0004 מזכירים בה ענין חנוכה \u0003ב\u0004ברכת ה\u0003הודאה.\u0004","מתוך הסתמכות על השאלה הקודמת \u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לבני הישיבה\u0005]\u0006 עוד שאלה זו: \u0003מהו\u0004 הדין לענין הצורך \u0003להזכיר\u0004 את \u0003ראש חודש בברכת המזון?\u0004 וצדדי השאלה: \u0003אם תימצי\u0004 \u0005[אם תרצה]\u0006 \u0003לומר\u0004 כי \u0003בחנוכה\u0004 מכיון שהוא רק \u0003דרבנן\u0004 \u0005[מדברי סופרים]\u0006 \u0003לא צריך\u0004 להזכיר אותו בברכת המזון, ואולם \u0003ראש חודש\u0004 שהוא \u0003דאורייתא\u0004 \u0005[מן התורה]\u0006 — \u0003צריך\u0004 להזכיר. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כיון דלא\u0004 \u0005[שאינו]\u0006 \u0003אסור בעשיית מלאכה\u0004 — \u0003לא מזכרינן\u0004 \u0005[אין אנו מזכירים].\u0006 ונחלקו חכמים בדבר, \u0003רב אמר: מזכיר\u0004 את ראש חדש בברכת המזון, ו\u0003ר' חנינא אמר: אינו מזכיר. אמר רב זריקא: נקוט\u0004 \u0005[החזק]\u0006 בהלכה של \u0003רב בידך,\u0004 כיון \u0003דקאי\u0004 \u0005[שעומד]\u0006 \u0003ר' אושעיא כוותיה\u0004 \u0005[כמותו,\u0006 בשיטתו\u0005].\u0006 \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003ר' אושעיא\u0004 בתוספתא: אותם \u0003ימים שיש בהן קרבן מוסף\u0004 בבית המקדש, \u0003כגון ראש חודש וחולו של מועד,\u0004 ב\u0003ערבית, ושחרית ומנחה מתפלל\u0004 אדם \u0003שמונה עשרה\u0004 ברכות שלמות \u0003ואומר מעין המאורע\u0004 של יום \u0003ב\u0004ברכת ה\u0003עבודה\u0004 (\"רצה\"). \u0003ואם לא אמר\u0004 — \u0003מחזירין אותו.\u0004 ואומרה בפעם השניה. \u0003ו\u0004בימים אלה \u0003אין בהן קדושה על הכוס,\u0004 שאין עושים קידוש בכניסת היום, \u0003ו\u0004אולם \u0003יש בהן הזכרה\u0004 של היום \u0003בברכת המזון\u0004 (וכשיטת רב). ואילו \u0003ימים שאין בהן קרבן מוסף, כגון שני וחמישי ושני\u0004 או \u0003תעניות\u0004 או \u0003מעמדות\u0004 דינם שונה וכפי שיפורט.","עוד לפני סיכום הדברים מבררים: \u0003שני וחמישי מאי עבידתייהו\u0004 \u0005[מה מעשיהם]?\u0006 כלומר, מדוע הוזכרו בכלל יום שני וחמישי שאין בהם תפילות מיוחדות? ומסבירים: \u0003אלא\u0004 ודאי מדובר ב\u0003שני וחמישי ושני של\u0004 ימי ה\u0003תעניות\u0004 על הגשמים \u0003ו\u0004של \u0003מעמדות.\u0004 ובימים אלה בתפילות \u0003ערבית, ושחרית ומנחה מתפלל שמונה עשרה\u0004 ברכות, \u0003ואומר מעין המאורע\u0004 (את ענין התענית) \u0003ב\u0004ברכת \u0003\"שומע תפלה\", ו\u0004אולם \u0003אם לא אמר\u0004 — \u0003אין מחזירין אותו. ואין בהן קדושה על הכוס, ואין בהן הזכרה בברכת המזון.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לבני הישיבה\u0005]\u0006 עוד שאלה זו: \u0003מהו\u0004 הדין לענין הצורך \u0003להזכיר\u0004 עניינה \u0003של חנוכה\u0004 בתפילת ה\u0003מוספין\u0004 בשבת חנוכה, או בראש חודש טבת החל בחנוכה, שיש בהם מוסף? וצדדי השאלה: האם נאמר \u0003כי כיון דלית ביה\u0004 \u0005[שאין בה]\u0006 בחנוכה \u0003מוסף בדידיה\u0004 \u0005[בה עצמה,\u0006 שלה\u0005]\u0006 לכך \u0003לא מדכרינן\u0004 \u0005[אין אנו מזכירים],\u0006 שהרי בימי החנוכה עצמם אין מוסיפים תפילת מוספים, ואם כן, המוסף אינו שייך כלל מבחינת מהותו לחג החנוכה, ולכן אין צורך להזכיר בו את החנוכה. \u0003או דילמא\u0004 \u0005[שמא]\u0006 עצם ה\u0003יום הוא שחייב\u0004 להזכיר בו את של חנוכה, ולכך אין סיבה לחלק בין התפילות ו\u0003בארבע תפלות\u0004 יש להזכיר, וביניהם גם מוסף של שבת או של ראש חודש, שאף היא נכללת בתפילות היום, ומכיון שכן חייבת היא בהזכרת החנוכה. ובכך נחלקו הדעות, \u0003רב הונא ורב יהודה דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003אינו מזכיר.\u0004 ו\u0003רב נחמן ור' יוחנן דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מזכיר.\u0004","\u0003אמר אביי לרב יוסף: הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 של \u0003רב הונא ורב יהודה\u0004 משל \u0003רב הוא,\u0004 שמוצאים אנו כשיטה זו גם בדברי רב, רבם. ש\u0003אמר רב גידל אמר רב: ראש חדש שחל להיות בשבת\u0004 — \u0003המפטיר בנביא בשבת אינו צריך להזכיר\u0004 בברכת ההפטרה את \u0003של ראש חדש, שאילמלא\u0004 היה זה יום \u0003שבת אין\u0004 קריאה ב\u0003נביא בראש חדש,\u0004 וההפטרה בנביא נחשבת שאינה נוגעת ליום ראש החודש, ועל כן אין מזכירים בה את ראש חודש. ואם כן הוא הדין לענין הזכרת חנוכה במוסף ראש חודש, כיון שאילמלא היה זה ראש חודש לא היה מתפלל מוסף בחנוכה, על כן אף שמתפלל מוסף — לא יצטרך להזכיר בו את של חנוכה.","אף את ההשוואה הזו דוחים: \u0003מי דמי\u0004 \u0005[האם\u0006 זה \u0005דומה]?!\u0006 \u0003התם\u0004 \u0005[שם]\u0006 הלא קריאה ב\u0003נביא ב\u0004סדר התפילה ב\u0003ראש חדש ליכא\u0004 \u0005[אינה]\u0006 \u0003כלל,\u0004 ואילו \u0003הכא איתיה\u0004 \u0005[כאן ישנה]\u0006 הזכרת חנוכה \u0003ב\u0004תפילות \u0003ערבית ושחרית ומנחה. אלא להא דמיא\u0004 \u0005[לזו\u0006 היא \u0005דומה]:\u0006 ש\u0003אמר רב אחדבוי\u0004 שכך \u0003אמר רב מתנה\u0004 שכך \u0003אמר רב: יום טוב שחל להיות בשבת, המפטיר בנביא במנחה בשבת אינו צריך להזכיר של יום טוב, שאילמלא\u0004 היה זה \u0003שבת אין\u0004 קריאה ב\u0003נביא במנחה ביום טוב.\u0004 ואם כן, אף שיש הפטרה בנביא ביום טוב בשחרית, כיון שבמנחה אין קוראים בנביא, נחשבת הקריאה הזאת כבלתי שייכת לגופו של יום טוב, ואין מזכירים בה ענין יום טוב. וכן גם בחנוכה — אינו מזכיר של חנוכה במוסף."],["\u0003ולית הילכתא ככל הני שמעתתא\u0004 \u0005[ואין הלכה ככל השמועות,\u0006 ההלכות \u0005הללו],\u0006 \u0003אלא כי הא\u0004 \u0005[כמו\u0006 הלכה \u0005זו]\u0006 ש\u0003אמר ר' יהושע בן לוי,\u0004 שאמר: \u0003יום הכפורים שחל להיות בשבת, המתפלל\u0004 את התפילה הנוספת של היום, \u0003נעילה, צריך להזכיר של שבת\u0004 אף בתפילה זו, ואף שאין מתפללים נעילה בכל שבת. וטעמו של דבר: שיום הכפורים ה\u0003יום\u0004 עצמו \u0003הוא שנתחייב בארבע תפלות\u0004 (שחרית, מוסף, מנחה, נעילה), וכיון שחל בשבת — יש להזכיר את השבת בכל אחת מן התפילות. ואם כן, רואים אנו שביום שבו יחוד, קשור הדבר לכל ענין שבקדושה המתארע בו, בין שהוא בא בשל היום ובין שהוא בא מטעם אחר.","ומקשים: \u0003קשיא הילכתא אהילכתא\u0004 \u0005[קשה הלכה\u0006 אחת \u0005על הלכה\u0006 אחרת\u0005].\u0006 שכן מצד אחד \u0003אמרת\u0004 כי \u0003הילכתא\u0004 \u0005[הלכה]\u0006 היא \u0003כר' יהושע בן לוי, וקיימא לן הילכתא\u0004 \u0005[ו\u0006מצד אחר \u0005מוחזק לנו,\u0006 בידינו כי \u0005הלכה]\u0006 \u0003כרבא,\u0004 והיא סתירה להלכה הראשונה, שכן \u0003אמר רבא:\u0004 ב\u0003יום טוב שחל להיות בשבת, שליח\u0004 ה\u0003ציבור היורד לפני התיבה\u0004 להתפלל תפילת \u0003ערבית\u0004 מקוצרת בקול רם (ברכה מעין שבע — \"קונה שמים וארץ\") \u0003אינו צריך להזכיר\u0004 בה את של \u0003יום טוב, שאילמלא\u0004 היתה זו גם \u0003שבת אין שליח צבור יורד\u0004 להתפלל תפילה זו ב\u0003ערבית ביום טוב.\u0004 ואם כן, חוזרים אנו להנחה שדבר שאינו נובע מעצם דיניו של אותו יום נחשב כזר לו, ואינו נזכר בו.","את הקושיה הזו דוחים: \u0003הכי השתא\u0004 \u0005[כיצד אתה משווה]?!\u0006 \u0003התם\u0004 \u0005[שם,\u0006 בשבת\u0005]\u0006 \u0003בדין הוא\u0004 ש\u0003אפילו בשבת נמי\u0004 \u0005[גם כן]\u0006 \u0003לא צריך\u0004 שיחזור שליח הציבור כדרך שאין חוזרים על תפילת ערבית אחרת, \u0003ורבנן\u0004 \u0005[ו\u0006אולם \u0005חכמים]\u0006 \u0003הוא דתקוני\u0004 \u0005[שתיקנו]\u0006 לעשות זאת \u0003משום\u0004 חשש \u0003סכנה,\u0004 כדי לעכב קצת את היוצאים מבית הכנסת, שהמאחרים לבוא ייצאו יחד עם כולם. כי בתי הכנסת מצויים היו מחוץ לעיר, והיתה סכנה ללכת יחידי בלילה. וחזרה זו על התפילה אינה מחיובו של היום, אלא תקנה לתועלת אחרת. \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ביום הכיפורים — \u0003יום הוא שנתחייב בארבע תפלות,\u0004 ולכן בכל יום שיש בו תפילה נוספת יש להזכיר בה את כל המאורעות החלים בו כמו בשאר התפילות.","\u0003ו\u0004עוד שנינו במשנה ש\u0003לא\u0004 מדליקים \u0003באליה\u0004 ולא בחלב. ונחום המדי אומר שמדליקים בחלב מבושל. וחכמים אומרים שבין שהוא מבושל ובין שאינו מבושל אין מדליקים בו. ושואלים: והלא שיטת ה\u0003חכמים היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 כלומר, סתם משנה, שהרי הם חוזרים על אותו רעיון! ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל למעשה ביחס למה ש\u0003רב ברונא אמר\u0004 בשם \u0003רב,\u0004 שחלב מבושל שהוסיפו בו שמן מותר להדליק בו, ואחד מקבל דעה זו להלכה ומתיר והשני אוסר. \u0003ו\u0004אולם \u0003לא מסיימי\u0004 \u0005[אין\u0006 הם \u0005מוגדרים],\u0006 שאף שמתוך סגנון הדברים במשנה נראה שיש הבדל ביניהם בנקודה זו, ואולם לא נשנתה במפורש שיטת כל אחד מהם.","כהמשך לדברי המשנה הקודמת מוסיפה משנה זו כי \u0003אין מדליקין בשמן שריפה ביום טוב,\u0004 וכאשר יבואר טעם הדבר בגמרא. בהדלקת נרות השבת היו חכמים שאסרו שמנים ידועים. \u0003ר' ישמעאל אומר\u0004 ש\u0003אין מדליקין בעטרן מפני כבוד השבת,\u0004 שריחו של העטרן רע, והוא מפריע ליושבים בבית. \u0003ו\u0004אילו \u0003חכמים מתירין\u0004 להשתמש להדלקת הנר \u0003בכל השמנים,\u0004 אם רק בוערים הם כיאות, \u0003בשמן שומשמין, בשמן אגוזים, בשמן צנונות, בשמן דגים, בשמן פקועות, בעטרן ו\u0004אף \u0003בנפט. ר' טרפון אומר: אין מדליקין אלא בשמן זית בלבד,\u0004 שהוא המובחר בשמנים ונאה לכבוד השבת.","על דברי המשנה, שאין מדליקים בשמן שריפה ביום טוב, שואלים בגמרא: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? ומשיבים: \u0003לפי\u0004 שבכלל \u0003אין שורפין קדשים ביום טוב.\u0004 ועל עצם העקרון שאין שורפים קדשים ביום טוב שואלים: \u0003מנהני מילי\u0004 \u0005[מניין הדברים הללו]?\u0006 \u0003אמר חזקיה, וכן תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה,\u0004 מה ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"ולא תותירו ממנו עד בקר והנתר ממנו עד בקר\u0004 באש תשרופו\u0003\"\u0004 (שמות יב, י) דרוש הסבר, \u0003ש\u0004כן \u0003אין תלמוד לומר,\u0004 כלומר, אין אנו למדים דבר מהמילים \u0003\"עד בקר\"\u0004 בפעם השניה, ודי היה לומר \"והנותר ממנו באש תשרופו\"! אלא \u0003מה תלמוד לומר \"עד בקר\"\u0004 — \u0003בא הכתוב ליתן לו בקר שני לשריפתו,\u0004 שאת הנותר מקרבן הפסח אין שורפים מיד בבוקר הבא, ביום טוב, אלא למחרת, ביום הראשון של חול המועד. ומכאן שאסור לשרוף קדשים ביום טוב.","\u0003אביי אמר:\u0004 דבר זה נלמד ממקרא אחר, ש\u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"עלת שבת בשבתו\"\u0004 (במדבר כח, י), ומכאן נלמד שרק עולת השבת מותר להקריב ביום השבת, \u0003ו\u0004אולם \u0003לא עולת חול בשבת, ולא עולת חול ביום טוב.\u0004 הרי שאף דבר מצוה אסור לעשותו ביום טוב, אם לא נכלל במפורש בין הדברים שהותרו במלאכה ביום טוב.","\u0003רבא אמר:\u0004 דבר זה נלמד מכתוב אחר, ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בדיני יום טוב: \u0003\"\u0004כל מלאכה לא יעשה בהם אך אשר יאכל לכל נפש \u0003הוא לבדו יעשה לכם\"\u0004 (שמות יב, טז), ומן ההדגשה \"הוא לבדו\" למדים אנו: \u0003\"הוא\"\u0004 — אוכל נפש לבדו הוא המותר בעשייה ביום טוב, \u0003ו\u0004אולם \u0003לא\u0004 הדברים ה\u0003מכשירין\u0004 הדרושים לצורך האכילה. שאף שמלאכת בישול מותרת, מכל מקום אסורה הכנת דברים המכשירים לבישול. וכן ממה שנאמר \u0003\"לבדו\"\u0004 נלמד: \u0003ולא מילה שלא בזמנה.\u0004 שאם לא נימול הילד בזמנו ביום השמיני ללידתו מסיבה כל שהיא ורוצים למולו ביום אחר, אין למולו ביום טוב. \u0003דאתיא\u0004 \u0005[ש\u0006אף ש\u0005באה]\u0006 אפשרות להתירה \u0003ב\u0004דרך לימוד מ\u0003קל וחומר,\u0004 הרי בא הכתוב ואוסר במפורש מלאכה זו ביום טוב. וכן שריפת קדשים, אם כי יש ציווי בכתוב לעשותה, כיון שאין חובה לעשותה ביום זה דווקא, לא הותר לעשותה ביום טוב.","\u0003רב אשי אמר\u0004 נימוק אחר: נאמר בכתוב לגבי הימים הטובים לשון \u0003\"שבת\"\u0004 ולשון \u0003\"שבתון\"\u0004 (ויקרא כ״ג:ג׳), והרי"],["\u0003עשה\u0004 של שביתה. \u0003ו\u0004אם כן, \u0003הוה ליה\u0004 \u0005[נעשה]\u0006 \u0003יום טוב\u0004 מצוה שיש בה גם צד של מצות \u0003עשה\u0004 (מצות שבתת) וגם מצות \u0003לא תעשה\u0004 (\"לא תעשה כל מלאכה\"). \u0003ואין עשה\u0004 של שריפת הקדשים \u0003דוחה את לא תעשה ועשה\u0004 של יום טוב.","מן הדברים האמורים ניתן להסיק ש\u0003ביום טוב הוא דאסיר\u0004 \u0005[שאסור]\u0006 להדליק נרותיו בשמן שריפה, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003בחול\u0004 — \u0003שפיר דמי\u0004 \u0005[יפה הדבר,\u0006 מותר\u0005].\u0006 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שהרי מסתבר לומר שיהא איסור בהנאה כלשהי מן התרומה הטמאה! \u0003אמר רב: כשם שמצוה לשרוף\u0004 את \u0003הקדשים שנטמאו, כך מצוה לשרוף את התרומה שנטמאת, ואמרה\u0004 ה\u0003תורה: בשעת ביעורה תיהני ממנה.\u0004 ושואלים: \u0003היכן אמרה תורה\u0004 דבר זה, והיכן נרמז בכתוב? ומשיבים: אפשר ללמוד זאת מדברי \u0003רב נחמן,\u0004 ש\u0003אמר רב נחמן אמר רבה בר אבוה: אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ואני הנה נתתי לך את משמרת תרומתי\"\u0004 (במדבר יח, ח), ומלשון הריבוי \"תרומותי\" למדים אנו ש\u0003בשתי תרומות הכתוב מדבר, אחת תרומה טהורה ואחת תרומה טמאה. ואמר רחמנא\u0004 \u0005[הקדוש ברוך הוא]:\u0006 \u0003\"\u0004נתתי \u0003לך\",\u0004 והכוונה: \u0003שלך תהא\u0004 ומותר לך להנות ממנה, וכיון שיש איסור חמור באכילתה, הרי שההנאה היא \u0003להסיקה תחת תבשילך\u0004 והנאות דומות הבאות בשעת ביעורה של התרומה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 דרך אחרת ללמוד הלכה זו \u0003מ\u0004דברי \u0003ר' אבהו\u0004 ש\u0003אמר ר' אבהו אמר ר' יוחנן:\u0004 נאמר בוידוי על הפרשת המעשר \u0003\"\u0004לא אכלתי באוני ממנו \u0003ולא בערתי ממנו בטמא\"\u0004 (דברים כו, יד). וההדגשה — \u0003\"ממנו\" אי\u0004 (אין) \u0003אתה מבעיר, אבל אתה מבעיר שמן של תרומה שנטמאת.\u0004 ושואלים: \u0003ואימא\u0004 \u0005[ואמור]\u0006 אחרת: \u0003ממנו אי אתה מבעיר, אבל אתה מבעיר\u0004 ונהנה משריפת \u0003שמן קדש שנטמא!\u0004","ומשיבים: אי אפשר לקבל הנחה כזו, שכן \u0003ולאו\u0004 \u0005[ו\u0006האם \u0005לא]\u0006 \u0003קל וחומר הוא?\u0004 שכן יש לומר \u0003: מה מעשר הקל\u0004 בדיניו \u0003אמרה\u0004 בו ה\u0003תורה \"\u0004לא \u0003בערתי ממנו בטמא\", קדש\u0004 שהוא \u0003חמור\u0004 — \u0003לא כל שכן\u0004 שאסור לשורפו ולבערו בטומאתו?","ודוחים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שאנו דנים בדבר בדרך קל וחומר, אם כן ב\u0003תרומה נמי לימא\u0004 \u0005[גם כן נאמר]\u0006 כי \u0003קל וחומר הוא,\u0004 שהרי חמורה התרומה מן המעשר, ואם המעשר אסור בהנאה בשעת שריפתו — כל שכן התרומה, ויאסר אם כן ליהנות משריפתה! ומשיבים: \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ממנו\",\u0004 ומלשון זו אנו למדים שיש דבר שאיסור שריפה בטומאה אינו חל עליו.","ושואלים: \u0003ומה ראית\u0004 לומר ש\"ממנו\" בא להדגיש \"ממנו\" ולא מתרומה, ושמא הכוונה היא \"ממנו\" — ולא מן הקודש! ומשיבים: \u0003מסתברא\u0004 \u0005[מסתבר]\u0006 כי את ה\u0003קדש לא ממעיטנא\u0004 \u0005[אין אני ממעט]\u0006 מן האיסור ליהנות משריפתו, שכן בקודש מצויות חומרות רבות ו\u0003סימן\u0004 להן \u0003פנ\"ק עכ\"ס,\u0004 שהן: דין ה\u0003פיגול\u0004 (שהחושב בשעת אחת מעבודות הקרבן, שחיטה, קבלה, הולכה זריקה, לאוכלו שלא בזמנו — פוסלו במחשבה בלבד), דין ה\u0003נותר\u0004 (שקודש הנשאר יותר מזמנו הקבוע נפסל על ידי השהיה), ועוד שהמועל והנהנה מן הקודש בשגגה מביא \u0003קרבן מעילה, ו\u0004האוכל ממנו בטומאה חייב \u0003כרת,\u0004 והוא \u0003אסור\u0004 באכילה \u0003לאונן\u0004 (מי שמת לו מת בו ביום ועדיין לא הובא לקבורה). וכל אלה אינם מצויים בתרומה. ולכן חמור הקודש ואין נהנים ממנו אפילו בשעת ביעורו בטומאה.","ודוחים: \u0003אדרבה, תרומה לא ממעיטנא\u0004 \u0005[נמעט],\u0006 מן האיסור, שהרי יש בתרומה חומרות שסימנן \u0003מחפ\"ז,\u0004 והם איסור \u0003מיתה\u0004 למי שלא הותר לו לאכול תרומה ואכלה בזדון, והחובה של זר, שאכל תרומה בשגגה, לשלם את מחירה לכהן בתוספת \u0003חומש,\u0004"],["\u0003ו\u0004עוד ש\u0003אין לה,\u0004 לתרומה, \u0003פדיון,\u0004 שלאחר שהוקדשה אינה יכולה להיפדות ולהיעשות חולין, \u0003ו\u0004עוד שהיא \u0003אסורה לזרים,\u0004 שאין היתר למי שאינו כהן לאוכלה, וחומרות אלה אינן כן בקדשים. ומשיבים: אף על פי כן \u0003הנך נפישן\u0004 \u0005[אלו מרובים],\u0006 כלומר, החומרות המצויות בקודש מרובות יותר מאלה המצויות בתרומה, ולפיכך ראוי להחמיר בקודש מבתרומה.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 טעם אחר בלא למנות את ריבוי החומרות: \u0003קדש חמור שכן\u0004 האוכלו בטומאה \u0003ענוש כרת,\u0004 ובתרומה העונש קל יותר והוא אך מיתה בידי שמים, והרי שבאותו ענין עצמו מחמיר הכתוב בקודש. \u0003רב נחמן בר יצחק אמר:\u0004 הוכחה אחרת היא שמותר ליהנות מן התרומה הנשרפת, שכן \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ראשית דגנך תירושך ויצהרך וראשית גז צאנך \u0003תתן לו\"\u0004 (דברים יח, ד), ודרשו מכאן שצריך לתת לכהן תרומה טהורה, שיהיה בה כדי נתינה. שכן אמר הכתוב \u0003\"לו \"\u0004להדגיש: \u0003ולא\u0004 שיתן לכהן תרומה הראויה רק \u0003לאורו,\u0004 כלומר, לשרוף אותה במדורתו. \u0003מכלל\u0004 \u0005[ואגב הדברים]\u0006 הרי למדים אנו \u0003דבת אורו הוא\u0004 שתרומה טמאה מותר לכהן ליהנות ממנה בשעת שריפתה.","שנינו במשנה ש\u0003ר' ישמעאל אומר\u0004 שאסור להדליק נר שבת בעטרן. ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? \u0003אמר רבא: מתוך שריחו\u0004 של העטרן \u0003רע, גזרו חכמים גזרה\u0004 מתוך החשש \u0003שמא יניחנה\u0004 לאותו נר \u0003ויצא. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ויצא!\u0004 וכי מה חובה לו לשבת ליד הנר? \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא: \u0003שאני אומר הדלקת נר בשבת חובה\u0004 היא, וצריך לאכול לאור הנר דווקא, משום כבוד השבת. ש\u0003אמר רב נחמן בר רב זבדא, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 ש\u0003אמר\u0004 זאת \u0003רב נחמן בר רבא אמר רב: הדלקת נר בשבת\u0004 היא \u0003חובה,\u0004 ואילו \u0003רחיצת ידים ורגלים בחמין ערבית,\u0004 לפני כניסת השבת אינה אלא \u0003רשות. ואני אומר:\u0004 לא רשות בלבד, כי אם \u0003מצוה,\u0004 אף שאינה חובה.","ושואלים: \u0003מאי\u0004 \u0005[מה,\u0006 איזו\u0005]\u0006 \u0003מצוה\u0004 יש בדבר? ומסבירים ש\u0003אמר רב יהודה אמר רב: כך היה מנהגו של ר' יהודה בר אלעאי, בערב שבת\u0004 היו \u0003מביאים לו עריבה\u0004 (קערה) \u0003מלאה חמין ו\u0004היה \u0003רוחץ\u0004 בה \u0003פניו ידיו ורגליו, ומתעטף ויושב בסדינין\u0004 של פשתן \u0003המצוייצין\u0004 (שיש בהם ציציות), \u0003ו\u0004היה \u0003דומה למלאך ה' צבאות,\u0004 וכל זה משום כבוד השבת. \u0003ו\u0004מסופר ש\u0003היו תלמידיו,\u0004 שישבו אף הם בסדינים, \u0003מחבין\u0004 (מסתירים) \u0003ממנו כנפי כסותן,\u0004 שלא יראה שאין ציציות בסדיניהם. \u0003אמר להן: בני,\u0004 וכי \u0003לא כך שניתי לכם: סדין\u0004 של פשתן \u0003ב\u0004ענין דיני \u0003ציצית, בית שמאי פוטרין\u0004 משום שחלק מן הציצית עשוי תמיד צמר, וצמר ופשתן יחד הוא שעטנז, ולא הותר שעטנז אפילו לצורך ציצית. \u0003ו\u0004אילו \u0003בית הלל מחייבין,\u0004 שסברו שכאן דוחה מצות עשה שבציצית את איסור השעטנז. \u0003ו\u0004הרי \u0003הלכה כ\u0004שיטת \u0003בית הלל\u0004 היא, ולכן גם סדינים ראוי לשים בהם ציציות. \u0003ואינהו סברי\u0004 \u0005[והם,\u0006 התלמידים, \u0005סברו]\u0006 שאף שמן התורה מותר לשים ציציות בבגד פשתן, מכל מקום גזרו חכמים שלא יעשה כן \u0003משום כסות לילה,\u0004 שמא ילבש אדם את הסדין הזה בלילה, ומאחר שבלילה אינו מחוייב במצות ציצית נמצא שהוא לבוש שעטנז בלא שתהיה בכך מצות עשה של ציצית. ולכן אסרו להטיל ציציות צמר בבגד פשתן אפילו בכסות יום.","ומתוך שהוזכרה הרחיצה כהכנה לעונג שבת, מביאים את מה שנדרש על הפסוק העוסק מענין ההולכים לגלות. נאמר: \u0003\"ותזנח משלום נפשי נשיתי טובה\"\u0004 (איכה ג, יז). \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 הכתוב \u0003\"ותזנח משלום נפשי\"\u0004 — \u0003אמר ר' אבהו: זו הדלקת הנר בשבת,\u0004 שהגולה אינו יכול לקיימה. \u0003\"נשיתי טובה\"\u0004 — \u0003אמר ר' ירמיה: זו\u0004 חוסר אפשרות להשתמש ב\u0003בית המרחץ. ר' יוחנן אמר: זו\u0004 חוסר אפשרות ל\u0003רחיצת ידים ורגלים בחמין. ר' יצחק נפחא אמר:\u0004 \"טובה\" \u0003זו\u0004 היא \u0003מטה נאה וכלים נאים שעליה\u0004 שאין לגולה אותם. \u0003ר' אבא אמר : זו מטה מוצעת ואשה מקושטת,\u0004 כלומר, ראויה והגונה (רשב\"א) \u0003לתלמידי חכמים.\u0004","וכיון שדברו במה שנקרא \"טובה\", מזכירים את מה ש\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בנושא דומה: \u0003איזהו עשיר?\u0004 — \u0003כל שיש לו נחת רוח בעשרו.\u0004 אלו \u0003דברי ר' מאיר. סימן מ\"ט ע\"ס. ר' טרפון אומר:\u0004 עשיר הוא \u0003כל שיש לו מאה כרמים ומאה שדות ומאה עבדים שעובדין בהן. ר' עקיבא אומר: כל שיש לו אשה נאה במעשים. ר' יוסי אומר: כל שיש לו בית הכסא סמוך לשולחנו.\u0004","\u0003תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' שמעון בן אלעזר אומר: אין מדליקין\u0004 בשבת \u0003בצרי\u0004 (שרף ריחני מעצי בושם). ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? — \u0003אמר רבה: מתוך שריחו נודף\u0004 חששו \u0003שמא\u0004 ישכח ו\u0003יסתפק\u0004 (ישתמש) \u0003ממנו\u0004 בשבת ונמצא כמכבה את הנר, שהלוקח שמן מן הנר בשעת בעירתו הרי זה כמכבהו, שהרי זמן בעירתו פוחת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004"]]};
